const _astro_dataLayerContent = [["Map",1,2,9,10],"meta::meta",["Map",3,4,5,6,7,8],"astro-version","5.18.2","content-config-digest","7bacc4463ae61e0b","astro-config-digest","{\"root\":{},\"srcDir\":{},\"publicDir\":{},\"outDir\":{},\"cacheDir\":{},\"site\":\"https://shortdramacost.com\",\"compressHTML\":true,\"base\":\"/\",\"trailingSlash\":\"always\",\"output\":\"static\",\"scopedStyleStrategy\":\"attribute\",\"build\":{\"format\":\"directory\",\"client\":{},\"server\":{},\"assets\":\"_astro\",\"serverEntry\":\"entry.mjs\",\"redirects\":true,\"inlineStylesheets\":\"auto\",\"concurrency\":1},\"server\":{\"open\":false,\"host\":false,\"port\":4321,\"streaming\":true,\"allowedHosts\":[]},\"redirects\":{},\"image\":{\"endpoint\":{\"route\":\"/_image/\"},\"service\":{\"entrypoint\":\"astro/assets/services/sharp\",\"config\":{}},\"domains\":[],\"remotePatterns\":[],\"responsiveStyles\":false},\"devToolbar\":{\"enabled\":true},\"markdown\":{\"syntaxHighlight\":{\"type\":\"shiki\",\"excludeLangs\":[\"math\"]},\"shikiConfig\":{\"langs\":[],\"langAlias\":{},\"theme\":\"github-dark\",\"themes\":{},\"wrap\":false,\"transformers\":[]},\"remarkPlugins\":[],\"rehypePlugins\":[],\"remarkRehype\":{},\"gfm\":true,\"smartypants\":true},\"security\":{\"checkOrigin\":true,\"allowedDomains\":[],\"actionBodySizeLimit\":1048576},\"env\":{\"schema\":{},\"validateSecrets\":false},\"experimental\":{\"clientPrerender\":false,\"contentIntellisense\":false,\"headingIdCompat\":false,\"preserveScriptOrder\":false,\"liveContentCollections\":false,\"csp\":false,\"staticImportMetaEnv\":false,\"chromeDevtoolsWorkspace\":false,\"failOnPrerenderConflict\":false,\"svgo\":false},\"legacy\":{\"collections\":false}}","guides",["Map",11,12,68,75,69,128,67,184,177,231,274,279,178,330,123,374,227,423,481,482,180,530,179,587,275,636,685,686,739,740,70,797,124,846,226,905,326,968],"how-to-cancel-reelshort-subscription",{id:11,data:13,body:71,filePath:72,digest:73,deferredRender:74},{title:14,description:15,app:16,targetKeyword:17,intent:18,shortAnswer:19,publishedOn:26,updatedOn:27,priceVerifiedOn:27,toc:28,faqs:50,relatedGuides:66},"How to Cancel a ReelShort Subscription (iOS, Android and Web)","Subscriptions must be cancelled through the store you bought them on, not inside the app. Step-by-step for iOS and Android, plus how to confirm it worked.","reelshort","how to cancel reelshort subscription","bottom",[20,21,22,23,24,25],"VIP subscriptions must be cancelled through the store you subscribed on — usually in the app, not inside the app.","iOS: Settings → your name → Subscriptions → select the app → Cancel Subscription.","Android: Play Store → profile icon → Payments & subscriptions → Subscriptions → select → Cancel.","Coins are a one-off purchase and cannot be refunded or cancelled — there is nothing to cancel.","After cancelling, re-open the subscription page and confirm the renewal date is gone.","Access usually continues until the end of the period you already paid for.","2026-10-01","2026-10-09",[29,32,35,38,41,44,47],{id:30,label:31},"why-in-app-does-not-work","Why you cannot cancel inside the app",{id:33,label:34},"ios","Cancel on iPhone or iPad",{id:36,label:37},"android","Cancel on Android",{id:39,label:40},"web","Cancel if you subscribed on the web",{id:42,label:43},"confirm","Confirm it actually worked",{id:45,label:46},"refunds","If you were already charged",{id:48,label:49},"limitations","What cancelling does not do",[51,54,57,60,63],{q:52,a:53},"Why can I not find a cancel button in the ReelShort app?","Because the app usually did not sell you the subscription. On iOS and Android the purchase is handled by the app store, so the cancellation control lives in your store account settings rather than inside the app.",{q:55,a:56},"Do I get a refund if I cancel immediately?","Normally no. Cancelling stops the next renewal, and access continues until the end of the period you already paid for. Refunds are a separate request made through the app store, not an automatic result of cancelling.",{q:58,a:59},"I cancelled but it charged me again — what happened?","The two most common causes are cancelling in the wrong place (for example, deleting the app instead of cancelling the subscription) or cancelling after the renewal had already been processed. Check your store subscription list for the actual renewal date, then request a refund through the store.",{q:61,a:62},"Can I cancel coins and get my money back?","Coins are a one-off purchase, not a subscription, so there is nothing to cancel. Refunds for spent coins are handled case by case through the app store refund process and are not guaranteed.",{q:64,a:65},"Does cancelling delete my account or my coin balance?","Cancelling a subscription does not delete your account. Your remaining coin balance stays attached to the account, so if you resubscribe later you do not lose coins you already bought.",[67,68,69,70],"reelshort-price-explained","is-reelshort-legit","how-to-get-free-coins-on-reelshort","how-to-cancel-dramabox-subscription","import Callout from '../../components/Callout.astro';\nimport Screenshot from '../../components/Screenshot.astro';\nimport AffiliateCTA from '../../components/AffiliateCTA.astro';\n\n<h2 id=\"why-in-app-does-not-work\">Why you cannot cancel inside the app</h2>\n\nThis is the single thing that confuses most people, and it is not a trick.\n\nWhen you subscribe through the Apple App Store or Google Play, the app store\nowns the subscription — it took the payment, it holds the renewal instruction,\nand it is the only party that can stop it. The app you are looking at is a\ntenant of that system, not the landlord.\n\nSo you will usually find no \"cancel subscription\" button inside the app. People\nconclude it cannot be cancelled, give up, and get charged again. In reality the\ncontrol is one screen away, in your store account settings.\n\n<Callout kind=\"info\" title=\"What that list screen tells you\">\nThe store's subscription list is the authoritative record — it is what decides\nwhether you are still going to be charged, regardless of what any app screen\nclaims. Two fields matter: the <strong>next billing date</strong> and the\n<strong>renewal amount</strong>. If you subscribed on a discounted week, the\namount shown there is the <em>renewal</em> rate, not the one you paid the first\ntime. That difference is usually where the surprise charge comes from.\n</Callout>\n\n<Callout kind=\"alert\" title=\"Two things that are not cancellations\">\n<strong>Deleting the app</strong> does not cancel anything. The subscription\nsurvives and keeps renewing. This is the most common cause of surprise charges.\n<br /><br />\n<strong>Logging out</strong> does not cancel anything either, for the same\nreason.\n</Callout>\n\n<h2 id=\"ios\">Cancel on iPhone or iPad</h2>\n\n<ol class=\"steps\">\n  <li>\n    <strong>Open Settings.</strong> Not the app store — the system Settings app\n    on your device.\n  </li>\n  <li>\n    <strong>Tap your name at the top.</strong> If you do not see it, tap\n    \"Sign in to your iPhone\" first — the subscription list only appears for a\n    signed-in account.\n  </li>\n  <li>\n    <strong>Tap Subscriptions.</strong> This lists every active and recently\n    expired subscription tied to your Apple ID.\n  </li>\n  <li>\n    <strong>Select the app in the list.</strong> If it is not there, you did not\n    subscribe with this Apple ID — check whether you used a different account or\n    subscribed on Android or the web.\n  </li>\n  <li>\n    <strong>Tap Cancel Subscription.</strong> If you see \"Cancel Free Trial\"\n    instead, the same tap works — this is the step that stops the first charge.\n  </li>\n  <li>\n    <strong>Confirm.</strong> Apple usually offers a retention prompt with an\n    alternative offer. Choosing to continue cancelling is fine; the prompt does\n    not block you.\n  </li>\n</ol>\n\n<Callout kind=\"info\" title=\"How we checked the iPhone steps\">\nWe tested this flow end to end on Android, with screenshots. For iOS we had no\ndevice to capture, so the steps above follow Apple's own published\ncancellation documentation — and we would rather tell you that than show you a\npicture we cannot stand behind. The screen names are exactly as Apple labels\nthem in the iOS Settings app.\n</Callout>\n\n<h2 id=\"android\">Cancel on Android</h2>\n\n<ol class=\"steps\">\n  <li>\n    <strong>Open the Google Play Store</strong> and tap your profile icon in the\n    top right.\n  </li>\n  <li>\n    <strong>Open \"Payments &amp; subscriptions\", then \"Subscriptions\".</strong>\n    This is the authoritative list of what will renew.\n  </li>\n  <li>\n    <strong>Select the app.</strong> If it is not listed, check whether you paid\n    through a different Google account — this is common on phones with more than\n    one account signed in.\n  </li>\n  <li>\n    <strong>Tap Cancel subscription</strong> and work through the confirmation\n    screens, which will include a retention offer.\n  </li>\n  <li>\n    <strong>Take a screenshot of the confirmation.</strong> It is the fastest\n    evidence to have on hand if a charge still appears.\n  </li>\n</ol>\n\n<Callout kind=\"info\" title=\"What the Play subscription detail page gives you\">\nThe detail page is the screen where cancellation is actually done, and it is\nalso where the <strong>exact renewal amount</strong> appears. Before you tap\ncancel, read that figure off — it is the number that will be charged, and it is\nfrequently higher than the price you originally paid. If it is higher and you\ndid not expect it, that is the moment to cancel rather than later.\n</Callout>\n\n<p>\n  This is what a Google Play subscription confirmation actually looks like, and\n  it is worth reading closely because the price jump is printed in plain sight.\n  The line marked <em>\"Today · 1-week period\"</em> is the discounted first\n  period. The line beneath it — <em>\"Starting Oct 16, 2026\"</em> — is what you\n  will actually pay from then on: <strong>$24.99/week against the $15.99 you\n  agreed to</strong>.\n</p>\n\n<Screenshot\n  src=\"/screenshots/netshort-gplay-subscription.webp\"\n  alt=\"A Google Play subscription confirmation screen showing a discounted first week at 15.99 dollars and the renewal rate of 24.99 dollars per week from a later date\"\n  caption=\"A real Google Play subscription confirmation, captured 8 October 2026. Read the two price lines together: the discounted first period, and the renewal rate that replaces it. It also carries the cancellation terms in the app's own words.\"\n/>\n\n<p>\n  Note the two lines in the middle, which appear in the store's own wording:\n  <em>\"Cancel anytime in Subscriptions on Google Play\"</em> and <em>\"We'll send\n  you a reminder 2 days before your intro price ends.\"</em> The second one is\n  the honest part of the offer — you do get warning. But it is two days, and\n  people who subscribe on a discount routinely treat that as the end of it\n  rather than the start. If you subscribe on a discount, act on the reminder.\n</p>\n\n<Callout kind=\"info\" title=\"How to tell cancellation worked\">\nAfter cancelling, the same subscription entry stays in the list — it does not\ndisappear. What changes is the date: a live subscription shows a\n<strong>next billing date</strong>, a cancelled one shows an\n<strong>access-until date</strong> instead. If you still see a future billing\ndate after cancelling, the cancellation did not go through, and you should check\nyour email for a confirmation from Google Play. That confirmation is the only\nreliable receipt; keep it.\n</Callout>\n\n<h2 id=\"web\">Cancel if you subscribed on the web</h2>\n\nIf you subscribed through the desktop web player, the subscription is not held\nby either app store, and neither app store's subscription list will show it. The\ncancellation route is wherever you entered payment details — the app's own\naccount or billing page in a browser.\n\nThis is worth checking specifically, because a web subscription is easy to\nforget: it will not appear in the app store settings you are used to checking.\nIf you are unsure which route you used, start with\n<a href=\"/guides/is-reelshort-legit\">our legitimacy check</a>, which explains\nwho processes which payment.\n\n<h2 id=\"confirm\">Confirm it actually worked</h2>\n\nDo not stop at the confirmation screen. Do this:\n\n<ul>\n  <li>Re-open the subscription list in the same place you cancelled from.</li>\n  <li>Confirm the renewal date is <strong>gone</strong> or the entry has moved to\n  an expired section.</li>\n  <li>Check the expiry date it now shows — access normally continues until the\n  end of the period you already paid for, then ends.</li>\n  <li>Keep the screenshot until after that expiry date has passed.</li>\n</ul>\n\n<Callout kind=\"info\" title=\"Why the confirmation screen is not enough\">\nA cancelled subscription that still shows a renewal date is not cancelled. If\nthe date is still there after you confirmed, the cancellation did not register —\nrun the steps again rather than waiting to see what happens.\n</Callout>\n\n<h2 id=\"refunds\">If you were already charged</h2>\n\nCancelling stops future renewals. It does not refund a charge that already went\nthrough, and it is not automatic.\n\nFor an unexpected charge:\n\n<ol class=\"steps\">\n  <li>\n    <strong>Go to the store's refund route first.</strong> On iOS that is the\n    Apple \"Report a Problem\" flow; on Android it is the Play Store refund\n    request. These are the parties that processed the payment and they control\n    the outcome.\n  </li>\n  <li>\n    <strong>Cancel the subscription as well</strong>, so the refund request and\n    the renewal stop are both in place.\n  </li>\n  <li>\n    <strong>Be specific about the timeline</strong> — when you cancelled, when\n    the charge appeared, and whether you tried to cancel earlier.\n  </li>\n</ol>\n\nContacting the app publisher is usually the slower path for a billing problem,\nbecause they cannot issue refunds for store-processed payments. Use the store\nroute first.\n\n<AffiliateCTA\n  appName=\"ReelShort\"\n  href=\"https://r.reelsgo.tv/1vwtyh4hj9R3\"\n  sub=\"Free to download · check the renewal terms before you subscribe\"\n/>\n\n<h2 id=\"limitations\">What cancelling does not do</h2>\n\n- **It does not refund the current period.** You keep access until the period\n  ends, and you do not get that money back. For what a period actually costs,\n  see <a href=\"/guides/reelshort-price-explained\">the price breakdown</a>.\n- **It does not delete your account or your coin balance.** Coins you already\n  bought stay on the account, so nothing is lost if you come back.\n- **It does not work retroactively.** If the renewal already processed, you are\n  in refund territory, not cancellation territory.\n- **It does not cover a subscription taken out on a different account.** Families\n  sharing devices regularly hit this. If the app is not in your subscription\n  list, check the other Apple ID or Google account on the device before assuming\n  there is nothing to cancel.\n\n<h2 id=\"bottom-line\">Bottom line</h2>\n\nCancel through the store that holds the subscription, not inside the app.\nDeleting nothing, logging out of nothing — the only thing that stops a renewal\nis cancelling it in your store account settings. Then go back and confirm the\nrenewal date is gone.","src/content/guides/how-to-cancel-reelshort-subscription.mdx","05f18c42ec5f27cb",true,{id:68,data:76,body:125,filePath:126,digest:127,deferredRender:74},{title:77,description:78,app:16,targetKeyword:79,intent:18,shortAnswer:80,publishedOn:26,updatedOn:87,priceVerifiedOn:87,toc:88,faqs:109,relatedGuides:122},"Is ReelShort Legit? What the 4.7★ App Store Score and 1.3★ Trustpilot Score Really Mean","ReelShort is a real app — but its 4.7 App Store score and 1.3 Trustpilot score disagree sharply. What each measures, and the billing risk to watch.","is reelshort legit",[81,82,83,84,85,86],"Yes, the app is legitimate. It is published by New Leaf Publishing and is one of the largest short-drama apps worldwide — 100M+ downloads on Google Play alone.","We checked three independent sources in October 2026: App Store 4.7★ (506K ratings), Google Play 3.8★ (1.92M reviews), Trustpilot 1.3★ (265 reviews).","The gap is not a contradiction: store ratings are prompted in-app after an episode; Trustpilot reviews are written by people with a billing problem.","Trustpilot's dominant complaint theme is payment — repeated charges and difficult cancellations. Its profile is unclaimed, so the company does not respond there.","The real risk with apps like this is subscription renewal and cancellation friction, not fraud.","One more thing we verified on 10 October 2026: the same Weekly VIP plan cost $11.87 for the first week on the publisher web checkout versus $1.99–$5.99 on Play billing in our earlier captures. The checkout you land on changes the price — and web subscriptions sit outside the store management tools.","2026-10-10",[89,92,95,98,101,104,107],{id:90,label:91},"short-version","The short answer",{id:93,label:94},"same-app","Why two scores disagree",{id:96,label:97},"who-publishes","Who publishes it",{id:99,label:100},"real-risks","The actual risks",{id:102,label:103},"two-checkouts","Two checkouts, two prices",{id:105,label:106},"how-to-protect","How to protect yourself",{id:48,label:108},"What this page cannot tell you",[110,113,116,119],{q:111,a:112},"Is ReelShort a scam?","No. It is published by New Leaf Publishing and is among the largest short-drama apps by usage — 100M+ downloads and a 1.92M-review Google Play presence as of October 2026. The complaints attached to it are about subscription renewal and cancellation friction, which is a pricing-model problem rather than a fraud problem.",{q:114,a:115},"Why does ReelShort have such a low Trustpilot score?","Because people write a Trustpilot review after something went wrong, typically a charge they did not expect or a cancellation that did not stick. Delighted viewers rate the app inside the app store instead. The two scores are answering different questions — and note the Trustpilot profile is unclaimed, so nobody from the company responds there.",{q:117,a:118},"Is it safe to enter card details in ReelShort?","In the app, purchases are processed through Google Play billing, which is the safer arrangement. But we verified on 10 October 2026 that ReelShort also runs its own web checkout that takes cards, PayPal and other methods directly — there you are paying the publisher outside the store. It is a normal payment processor rather than a stranger, but the store subscription-management and refund tools will not cover it. The risk is not card theft — it is an auto-renewing subscription you forget about.",{q:120,a:121},"What should I check before subscribing?","Three things: the exact renewal period, the price after any introductory offer ends, and the cancellation steps. Decide how you will cancel before you subscribe, not after the first charge appears.",[11,67,69,123,124],"short-drama-app-subscription-trap","are-short-drama-apps-a-scam","import Callout from '../../components/Callout.astro';\nimport Screenshot from '../../components/Screenshot.astro';\nimport AffiliateCTA from '../../components/AffiliateCTA.astro';\n\n<h2 id=\"short-version\">The short answer</h2>\n\nYes, it is legitimate. It is published by New Leaf Publishing, it has tens of\nmillions of users, and payments run through the normal app store billing\nsystems.\n\nBut \"legitimate\" and \"safe to hand your card to without thinking\" are different\nclaims, and the second one deserves a proper answer. The complaints that\nsurround this app are almost entirely about **subscription renewal and\ncancellation friction** — not about it being fake.\n\n<Screenshot\n  src=\"/screenshots/reelshort-store-listing.webp\"\n  alt=\"Google Play listing for ReelShort showing publisher New Leaf Publishing, a 3.8 star rating from 1.92 million reviews and 100M plus downloads\"\n  caption=\"The Google Play listing on 8 October 2026: publisher New Leaf Publishing, 3.8★ from 1.92M reviews, 100M+ downloads. The store listing is the fastest legitimacy check.\"\n/>\n\n<h2 id=\"same-app\">Why the three scores disagree so violently</h2>\n\nThis is the most useful thing on this page, so it is worth slowing down for.\nWe pulled the app's standing from three independent sources in October 2026:\n\n| Source | Score | Sample | What it measures |\n|---|---|---|---|\n| Apple App Store (US) | **4.7 / 5** | 506K ratings | \"Was that story good?\" |\n| Google Play | **3.8 / 5** | 1.92M reviews | A mix of content and billing gripes |\n| Trustpilot | **1.3 / 5 (Bad)** | 265 reviews | \"Did billing treat me well?\" |\n\nThat spread — nearly five stars on one platform, barely one on another — is not\nevidence of a cover-up. It is evidence that each platform collects answers to a\ndifferent question from a different population.\n\n<Screenshot\n  src=\"/screenshots/reelshort-rating-comparison.webp\"\n  alt=\"Side by side screenshots of the Apple App Store listing showing 4.7 stars and the Trustpilot page for ReelShort showing 1.3 stars rated Bad\"\n  caption=\"Same app, opposite scores, both captured 8 October 2026: 4.7★ on the App Store (left) against 1.3★ on Trustpilot (right)\"\n/>\n\n<Callout kind=\"info\" title=\"The mechanism, plainly\">\n<strong>App store ratings</strong> are usually prompted inside the app, often\nright after an episode ends. So they measure <em>\"was that story good?\"</em>\n<strong>Trustpilot-style reviews</strong> are written unprompted, and the\noverwhelming trigger for writing one is a problem with money. Trustpilot's own\ntopic summary for this app puts <strong>Payment</strong> first, with recurring\ncomplaints about repeated charges and cancelled subscriptions that kept billing.\nNobody opens a review site to say a drama was fun.\n</Callout>\n\nBoth numbers are therefore \"true\" and neither is a complete picture. A high app\nstore score with a low billing review score describes a product people enjoy\nthat is sold in an annoying way. That is a legitimate thing to be warned about —\nand it is a pricing-model criticism, not a fraud accusation.\n\nOne more detail that matters when reading those Trustpilot reviews: the profile\nis **unclaimed**, meaning the publisher has not taken it over and does not\nrespond there. Silence on Trustpilot is normal for app publishers — it does not\nconfirm the complaints, but it means you should not expect a public rebuttal\neither. Judge both sides yourself.\n\n<h2 id=\"who-publishes\">Who publishes it, and why that matters</h2>\n\nThe app comes from an established studio that pioneered the English-language\nvertical drama format — the model where each episode runs a minute or two and\nevery episode ends on a cliffhanger. On Google Play it appears as New Leaf\nPublishing, with 100M+ installs and a catalogue updated weekly. It is one of the\nlargest operators in the category by user numbers and reported revenue.\n\nPractical significance: this is not an anonymous app that might vanish with your\nsubscription. It is a real business with a catalogue, a support process, and a\nreputation to protect. The company is not the risk. The billing model is.\n\n<h2 id=\"real-risks\">The actual risks, ranked</h2>\n\n<ol class=\"steps\">\n  <li>\n    <strong>Auto-renewal you did not plan for.</strong>\n    The single most common complaint. Weekly tiers renew fast — we documented a\n    plan at $5.99/week after a $1.99 first week — and \"I'll cancel after this\n    series\" easily becomes three more weeks of charges.\n  </li>\n  <li>\n    <strong>Cancellation friction.</strong>\n    Cancelling has to be done through the store you subscribed on — the app\n    itself usually cannot cancel it for you. People who look in the wrong place\n    conclude it cannot be cancelled.\n  </li>\n  <li>\n    <strong>Coins spent before you notice the total.</strong>\n    Paying per episode hides the running total. At 60 coins (about 60 cents) per\n    episode, a series that feels like small purchases adds up to $25–45 — more\n    than an annual subscription at some rivals.\n  </li>\n  <li>\n    <strong>Third-party \"free coins\" sites.</strong>\n    Not a risk from the app itself, but the most common way people actually lose\n    money around it. See our\n    <a href=\"/guides/how-to-get-free-coins-on-reelshort\">free coins guide</a>\n    for what genuinely works.\n  </li>\n</ol>\n\n<Screenshot\n  src=\"/screenshots/netshort-gplay-subscription.webp\"\n  alt=\"A Google Play subscription confirmation screen for a short drama app showing the discounted first period price and the higher weekly renewal rate\"\n  caption=\"Where the real control lives — the store account, not the app. This is a real Play subscription screen, and it carries the cancellation terms in writing\"\n/>\n\n<Callout kind=\"alert\" title=\"What is genuinely not a risk\">\nYour card details are not being handled by an unknown party — in-app purchases\ngo through Google Play billing, and the web checkout documented below is a\nstandard payment page. Nobody is going to drain your bank account. The\nrealistic worst case is a few unwanted renewals, which is why the fix is\nprocess rather than paranoia.\n</Callout>\n\n<h2 id=\"two-checkouts\">Same plan, two checkouts — and prices that do not match</h2>\n\nWhile re-verifying prices on 10 October 2026 we ran into something the store\nlisting does not mention: ReelShort does not only bill through Google Play.\nThe app also funnels subscribers to its own web checkout —\nreelshort.com/third-pay/checkout — which takes Google Pay, Cash App, bank\ntransfer, PayPal and cards directly. That form is run by the publisher, outside\nthe store billing system.\n\nThe same Weekly VIP plan is priced differently on the two paths:\n\n| Checkout | First week | Then | Captured |\n|---|---|---|---|\n| Google Play billing (in-app) | $1.99–$5.99 (varies daily) | about $19.99/week | 8–9 Oct 2026 |\n| Publisher web checkout | **$11.87** incl. tax | **$20.51/week** incl. tax | 10 Oct 2026 |\n\nSame app, same plan — a first week that costs up to six times more depending on\nwhich checkout you land on, and a web total that no longer matches the $10.99\nin-app sticker it upsells from.\n\n<Screenshot\n  src=\"/screenshots/reelshort-web-checkout.webp\"\n  alt=\"ReelShort web checkout page showing Google Pay, Cash App Pay, Pay By Bank and PayPal options with a Weekly VIP total of 11.87 dollars including tax\"\n  caption=\"The publisher's own web checkout on 10 October 2026: $11.87 for the first week, then $20.51/week with tax — the same plan Play billed at $1.99–$5.99 two days earlier.\"\n/>\n\nTwo things follow from this, and both matter more than any single number:\n\n<ul>\n  <li>\n    <strong>The billing path changes your rights.</strong> A store-billed\n    subscription can be cancelled and refunded through the store. A\n    web-checkout subscription is a direct deal with the publisher — your store\n    subscription settings will not list it, so the \"cancel through the store\"\n    advice above only covers one of the two paths.\n  </li>\n  <li>\n    <strong>Treat discount banners as noise, not a price.</strong> Between\n    daily-rotating intro offers and two parallel checkouts, no single number\n    here survives a week. The only figure to trust is the total, tax included,\n    on the exact screen you are about to pay on — which is why every price on\n    this site carries the date we captured it.\n  </li>\n</ul>\n\n<h2 id=\"how-to-protect\">How to protect yourself in five minutes</h2>\n\n<ul>\n  <li><strong>Before subscribing:</strong> write down the renewal period and the\n  post-intro price. Screenshot the subscription screen.</li>\n  <li><strong>Before subscribing:</strong> open your app store's subscription\n  settings and confirm you can see the app listed there. If you can see it, you\n  can cancel it.</li>\n  <li><strong>At sign-up:</strong> set a calendar reminder two days before the\n  first renewal.</li>\n  <li><strong>If you want to stop:</strong> cancel through the app store, then\n  re-open the subscription page and confirm the renewal date is gone. Our\n  <a href=\"/guides/how-to-cancel-reelshort-subscription\">cancellation walkthrough</a>\n  covers the exact steps.</li>\n  <li><strong>If you subscribed on the web checkout:</strong> the store\n  subscription list will not show it at all. Cancel from the same place you\n  signed up — the publisher subscription page — and keep the confirmation\n  email.</li>\n  <li><strong>If a charge looks wrong:</strong> go to the app store's refund\n  route first — it is faster than contacting the publisher and it is the channel\n  that actually controls the billing.</li>\n</ul>\n\n<AffiliateCTA\n  appName=\"ReelShort\"\n  href=\"https://r.reelsgo.tv/1vwtyh4hj9R3\"\n  sub=\"Free to download · check the current subscription terms in-app before you pay\"\n  buttonLabel=\"Open ReelShort\"\n/>\n\n<h2 id=\"limitations\">What this page cannot tell you</h2>\n\n- **Ratings move.** The three scores above were captured on 8 October 2026; by\n  the time you read this they will have drifted. The pattern — high in-app\n  store scores, poor independent billing reviews — has been stable, but check\n  the live numbers yourself.\n- **We cannot tell you whether you will enjoy it.** That is a taste judgement\n  and no review substitutes for the free episodes.\n- **A legitimacy check is not a quality verdict.** This page answers \"is it\n  real\", not \"is it worth it\". For the second question see\n  <a href=\"/apps/reelshort\">the full review</a>.\n- **We are not affiliated with the publisher.** We earn a commission if you sign\n  up through our links, at no extra cost to you. That is disclosed on every page.\n\n<h2 id=\"bottom-line\">Bottom line</h2>\n\nIt is a real app from a real studio, and the content is why it has tens of\nmillions of users. The thing to be careful about is the same thing you should be\ncareful about in every subscription app: know the renewal terms before you\nsubscribe, and know how to cancel before you need to.","src/content/guides/is-reelshort-legit.mdx","4dca874b1e260a3f",{id:69,data:129,body:181,filePath:182,digest:183,deferredRender:74},{title:130,description:131,app:16,targetKeyword:132,intent:18,shortAnswer:133,publishedOn:26,updatedOn:139,priceVerifiedOn:27,toc:140,faqs:163,relatedGuides:176},"How to Get Free Coins on ReelShort (2026): Every Method, Ranked","Every way to get ReelShort coins free — free episodes, check-ins, ad unlocks, watch-time tasks, coupons — with the daily caps we counted in-app.","how to get free coins on reelshort",[134,135,136,137,138],"Free episodes are the biggest allowance: the series we tested ran 10–16 free episodes before the paywall, and it differs by title.","Verified daily free-coin sources (October 2026): check-in up to 200 coins on day 7, up to 340 coins/day from watch-time tasks, 17 ad tasks/day, and a 50-coin login bonus for new accounts.","Ad unlocks trade a video for an episode on selected titles, capped at 10 per day.","New releases hand out free daily coupons for the 7 days before launch — check the NEW tab.","There is no unlimited free route; coins or VIP are the only ways past a series paywall.","2026-10-16",[141,143,146,149,152,155,158,161],{id:90,label:142},"The short version",{id:144,label:145},"free-episodes","1. Free opening episodes",{id:147,label:148},"daily-coins","2. Daily check-in coins",{id:150,label:151},"ad-unlocks","3. Limited ad unlocks",{id:153,label:154},"promo-series","4. New-release coupons & promos",{id:156,label:157},"what-does-not-work","What does not work",{id:159,label:160},"best-strategy","The strategy we actually use",{id:48,label:162},"When this approach does not work",[164,167,170,173],{q:165,a:166},"Can you get unlimited free coins on ReelShort?","No. We counted every free-coin source in the app (October 2026): check-in coins, watch-time tasks, ad tasks and new-release coupons are all capped per day — the theoretical maximum is under 1,000 coins a day of active effort, while one episode costs 60 coins. Every series eventually reaches a paywall.",{q:168,a:169},"How many episodes can you watch for free?","It varies by series and neither app publishes the boundary. In our testing, one 81-episode series ran 16 episodes before charging, while a 54-episode series locked around episode 10–15. Expect roughly 10–16 free episodes and check the episode list of the specific series you want.",{q:171,a:172},"Do ReelShort daily check-in coins expire?","Check-in coins accumulate in your balance rather than expiring after a day, but the amounts are small: the 7-day streak we documented pays 10, 10, 80, 20, 25, 30 and 200 coins — 375 coins in week one, about six episodes at 60 coins each.",{q:174,a:175},"Is there a ReelShort redeem code for free coins?","We have not verified any working public redeem code for this app. Any site offering one in exchange for your details or a payment is a red flag — the genuine free sources are all inside the app and are listed on this page.",[67,11,68,177,178,179,180],"reelshort-vs-dramabox","how-to-stop-paying-for-short-drama-apps","short-drama-app-most-free-episodes","reelshort-coins-vs-vip","import Callout from '../../components/Callout.astro';\nimport Screenshot from '../../components/Screenshot.astro';\nimport AffiliateCTA from '../../components/AffiliateCTA.astro';\n\n<h2 id=\"short-version\">The short version</h2>\n\nThere are five genuine free routes on ReelShort, and they stack. None of them\nwill let you finish a series for nothing — that is not an accident, it is the\nbusiness model. What they will do is let you watch a meaningful amount before\nyou decide whether to pay.\n\nHere is the honest framing: **the free tier is a sampler, not a product.** If\nyou understand that going in, you can extract a lot of value from it. If you\nexpect to find a loophole, you will waste an evening on sites that promise one.\n\n<Screenshot\n  src=\"/screenshots/reelshort-home-free-banner.webp\"\n  alt=\"ReelShort NEW tab showing a Coming Soon banner offering a free daily coupon seven days before new releases\"\n  caption=\"The NEW tab on Android, 9 October 2026: new series hand out free daily coupons for the week before launch — the most under-used free route\"\n/>\n\n<h2 id=\"free-episodes\">1. Free opening episodes — the biggest allowance</h2>\n\nEvery series on the app opens with a block of free episodes before the paywall\nappears. This is by far the largest free allowance available, and because it\napplies per series rather than per account, you can use it across lots of\ndifferent titles.\n\nThe boundary is not fixed, and that is worth knowing before you plan around it.\nWe checked two series in October 2026: an 81-episode title ran 16 episodes\nbefore the paywall, while a 54-episode title started locking around episode 10\nand hit its paywall at 15. ReelShort does not publish the number, so open the\nepisode list of the series you actually want and scroll to the first lock\nbefore you commit to anything.\n\n<Screenshot\n  src=\"/screenshots/reelshort-episode-free-boundary.webp\"\n  alt=\"Episode list inside a ReelShort series showing unlocked early episodes and the first locked episode with a price\"\n  caption=\"Where the free block ends on Android, 8 October 2026 — this is the line that matters, and it moves from series to series\"\n/>\n\n<Callout kind=\"info\" title=\"Why this matters more than coin tricks\">\nTen to sixteen free episodes across five different series is 50–80 episodes of\nviewing for nothing. Chasing a few free coins instead is the wrong trade — the\nper-series free tier is worth far more, and people routinely under-use it.\n</Callout>\n\n<h2 id=\"daily-coins\">2. Daily check-in coins</h2>\n\nThe check-in calendar pays real coins, and the streak matters. The 7-day cycle\nwe documented on Android pays 10 → 10 → 80 → 20 → 25 → 30 → **200** coins —\n375 coins in the first week, or about six episodes at 60 coins each. After\nchecking in, a button offers to double that day's reward (+20 coins) for\nwatching one ad.\n\nNew accounts also get a one-time 50-coin login bonus.\n\nThe honest maths: at 60 coins per episode, even a perfect week of check-ins\ncovers about six episodes. Treat check-ins as a discount on a series you were\ngoing to pay for anyway — not as a route to watching for free.\n\n<Screenshot\n  src=\"/screenshots/reelshort-checkin-calendar.webp\"\n  alt=\"ReelShort daily check-in calendar showing coin rewards from 10 coins on day one up to 200 coins on day seven\"\n  caption=\"The 7-day check-in cycle on Android, 8 October 2026: 375 coins for a full week — real, but it covers about six episodes\"\n/>\n\n<h2 id=\"ad-unlocks\">3. Limited ad unlocks</h2>\n\nSelected titles let you unlock an episode by watching an advertisement instead\nof spending coins. This is genuinely useful when it is available, because it\ncosts you time rather than money.\n\nTwo hard limits we confirmed in the app:\n\n- The daily cap is **10 ad unlocks** — the popup shows your count (0/10) and\n  stops at ten\n- It only appears on **selected titles**, so you cannot count on it for the\n  series you actually want\n\nAlso worth knowing what you are trading: the ads we were served in testing\nincluded a fake-sounding insurance pitch one day and a TikTok install ad the\nnext. The \"price\" of the free route is sitting through low-quality advertising —\ndecide if that trade suits you before leaning on it.\n\n<Screenshot\n  src=\"/screenshots/reelshort-ad-unlock-prompt.webp\"\n  alt=\"ReelShort ad unlock popup offering a free episode for watching a video, showing a daily counter at zero of ten\"\n  caption=\"The ad unlock prompt on Android, 9 October 2026, with its daily counter at 0/10 — ten episodes a day is the ceiling\"\n/>\n\n<h2 id=\"promo-series\">4. New-release coupons & rotating promos</h2>\n\nTwo mechanisms live in the app's tabs rather than its paywall:\n\n- **New-release coupons.** The NEW tab runs a \"Coming Soon\" banner offering a\n  free daily coupon for the 7 days before a new series launches. Check it if you\n  follow upcoming titles.\n- **Watch-time tasks.** The rewards page pays coins for minutes watched: 12 /\n  18 / 30 / 80 / 100 coins for 2 / 5 / 10 / 20 / 30 minutes — up to 340 coins a\n  day for someone who was going to watch anyway. This is the largest renewable\n  free-coin source in the app.\n\nThere is also a Today's Benefits section of ad tasks (up to 17 per day, each\npaying a small coin reward). Between watch-time and ad tasks, an active free\nuser can realistically pull in several hundred coins a day — roughly five\nepisodes — without paying.\n\nThis is the most under-used part of the app. People search for coin hacks while\nignoring a rewards page that pays them for viewing they were doing regardless.\n\n<h2 id=\"what-does-not-work\">What does not work — and what to avoid</h2>\n\n<Callout kind=\"alert\" title=\"Sites promising a redeem code or a free coin tool\">\nWe have not verified any working public redeem code for this app, and no\nlegitimate service hands out free coins. Sites offering either typically want\none of two things: your account credentials, or a payment for a \"tool\" that does\nnothing. Both are ways to lose money or an account.\n</Callout>\n\nSpecifically, these are dead ends:\n\n- **Coin generators and hacks.** They do not exist. The coin balance is held\n  server-side.\n- **Modified or tampered app builds.** These are a copyright violation, they get\n  accounts banned, and they are a common vector for malware. They are also the\n  fastest way to get a site deindexed if you ever write about them.\n- **Third-party code lists.** Unverified, usually expired, and often used purely\n  to harvest email addresses.\n\n<h2 id=\"best-strategy\">The strategy we actually use</h2>\n\n<ol class=\"steps\">\n  <li>\n    <strong>Sample five series before spending anything.</strong>\n    Use the per-series free tier across different genres. This tells you whether\n    the catalogue is worth paying for at all, at zero cost.\n  </li>\n  <li>\n    <strong>Run the passive sources while you sample.</strong>\n    Check in daily, let the watch-time tasks accrue while you watch your free\n    episodes, and grab new-release coupons. After a week of normal usage you\n    will have several hundred coins banked at zero cost.\n  </li>\n  <li>\n    <strong>Price coins against VIP for your specific shortlist.</strong>\n    Finishing one series with coins and finishing two or more with a\n    subscription are different purchases with very different economics. Our\n    <a href=\"/guides/reelshort-price-explained\">full price breakdown</a> works\n    through the comparison.\n  </li>\n  <li>\n    <strong>Set a reminder before any trial or subscription renews.</strong>\n    Renewal is where most people lose money on these apps, not the initial\n    purchase. See\n    <a href=\"/guides/how-to-cancel-reelshort-subscription\">how to cancel</a>\n    before you subscribe, not after.\n  </li>\n</ol>\n\n<AffiliateCTA\n  appName=\"ReelShort\"\n  href=\"https://r.reelsgo.tv/1vwtyh4hj9R3\"\n  sub=\"Free to download · free opening episodes on every series\"\n  buttonLabel=\"Open ReelShort\"\n/>\n\n<h2 id=\"limitations\">When this approach does not work</h2>\n\nBe clear about the boundaries of what is written above, because they are real:\n\n- **If you watch more than a couple of series a month, this does not work.**\n  The free routes are capped by design — the daily ceiling is a handful of\n  episodes. At that volume you are going to pay, and the useful question becomes\n  which payment shape is cheapest — see\n  <a href=\"/apps/reelshort\">our full ReelShort review</a> for that comparison.\n- **All figures here are from Android, October 2026.** Caps, coin amounts and\n  coupon mechanics are exactly the kind of thing apps tune monthly. Re-check in\n  the app before relying on any specific number.\n- **If you are outside the app's supported regions**, promotional series and ad\n  unlocks may simply not appear.\n- **If you expect these methods to stay static**, they will not. Promotions\n  rotate, ad unlocks change, and free-episode counts move.\n\n<h2 id=\"bottom-line\">Bottom line</h2>\n\nYou can watch a real amount of ReelShort for free — 10–16 episodes per series,\nplus a few hundred coins a day from check-ins, watch-time tasks and ads. You\ncannot watch a whole series for free, and no tool will change that.\n\nThe people who get the most out of these apps are the ones who sample widely on\nthe free tier, decide deliberately, and then manage the renewal. Everyone else\npays a premium for a decision they did not make consciously.","src/content/guides/how-to-get-free-coins-on-reelshort.mdx","54ae5c339bbb0b98",{id:67,data:185,body:228,filePath:229,digest:230,deferredRender:74},{title:186,description:187,app:16,targetKeyword:188,intent:18,shortAnswer:189,publishedOn:26,updatedOn:27,priceVerifiedOn:27,toc:194,faqs:212,relatedGuides:225},"ReelShort Price Explained: Coins vs VIP, and What a Full Series Really Costs","The two paid layers on ReelShort — coins vs VIP — with prices verified in-app on Android in October 2026, and which is cheaper for your habit.","reelshort price",[190,191,192,193],"ReelShort has two separate paid layers: coins (per-episode unlocks) and VIP (a time-based subscription).","Verified on Android, 8–9 October 2026: a single episode costs 60 coins — roughly $0.60 at the cheapest pack.","VIP renews at $5.99–$19.99 per week depending on tier, and the discounted first week changes from day to day.","The break-even question is simple: how many series will you finish this month?",[195,198,201,204,207,210],{id:196,label:197},"two-layers","The two paid layers",{id:199,label:200},"coin-economics","Coin economics",{id:202,label:203},"vip-economics","VIP economics",{id:205,label:206},"break-even","The break-even rule",{id:208,label:209},"hidden-costs","Where the cost actually hides",{id:48,label:211},"What we cannot price for you",[213,216,219,222],{q:214,a:215},"How much does ReelShort cost per month?","There is no single monthly price, because the app sells coins for per-episode unlocks and VIP passes on weekly and annual terms. Verified in-app on Android (October 2026): coins run $4.99–$49.99 per pack at roughly $0.0067–$0.0100 per coin, one episode costs 60 coins, and VIP renews at $5.99–$19.99 per week depending on tier.",{q:217,a:218},"Is it cheaper to buy coins or VIP?","Coins are cheaper if you finish about one series per month or less. At 60 coins per episode, a 60-episode series costs roughly $24–36 in coins, while one week of VIP at the observed $5.99–$11.99 renewal prices can cover several series. VIP becomes cheaper once you finish two or more series a month.",{q:220,a:221},"Are the prices on this page verified?","Yes — we checked them inside the app on an Android phone with a US Google Play account on 8–9 October 2026, and the screenshots on this page are from those sessions. Two caveats: these are Android prices (iOS can differ), and the discounted first week of VIP changed between our two visits a day apart, so treat any intro price you see as temporary.",{q:223,a:224},"Why is ReelShort more expensive than other short-drama apps?","It films its own English-language originals with real casts instead of licensing and dubbing existing productions. Original production costs more per title, which is reflected in both the coin packs and the VIP tiers.",[226,69,11,177,227,180],"reelshort-cost-per-episode","why-short-drama-app-prices-differ","import Callout from '../../components/Callout.astro';\nimport PriceTable from '../../components/PriceTable.astro';\nimport Screenshot from '../../components/Screenshot.astro';\nimport AffiliateCTA from '../../components/AffiliateCTA.astro';\n\n<h2 id=\"two-layers\">The two paid layers, and why mixing them up is expensive</h2>\n\nMost coverage of this app describes \"the price\" as if there were one. There are\ntwo, they solve different problems, and confusing them is the main reason people\nspend more than they intended.\n\n**Coins** are an unlock currency. You spend them to open episodes beyond the free\nblock. They are consumed as you go, so the cost scales with how much you watch.\n\n**VIP** is a time-based pass. It removes most of the per-episode paywall for as\nlong as it lasts. The cost is fixed regardless of how much you watch.\n\nThat distinction produces the entire pricing strategy: coins reward light\nviewers and punish heavy ones. VIP does the opposite.\n\n<PriceTable\n  verifiedOn=\"2026-10-09\"\n  caption=\"ReelShort pricing, verified in-app on Android (US Google Play account), 8–9 October 2026\"\n  col1=\"Item\"\n  col2=\"Price / detail\"\n  rows={[\n    { label: 'Download', value: 'Free', note: 'Coins and VIP are the paid layers' },\n    { label: 'Single episode unlock', value: '60 coins ≈ $0.60', note: 'At the $4.99 / 500-coin pack rate. The exact free/paid boundary differs by series.' },\n    { label: 'Coin packs', value: '$4.99 – $49.99', note: 'Five tiers: $4.99/500, $9.99/1,100, $19.99/2,400, $29.99/3,900, $49.99/7,500. Unit price falls from ~$0.0100 to ~$0.0067 per coin.' },\n    { label: 'VIP weekly (renewal)', value: '$5.99 – $19.99 per week', note: 'With-ads tier renewed at $5.99/week when observed; top tiers reach $19.99/week. All prices plus tax.' },\n    { label: 'VIP intro week', value: 'Rotates daily — $1.99 to $15.99 observed', note: 'We saw a 67%-off offer one day and a 21%-off offer the next. Never assume the intro price is the real price.' },\n    { label: 'VIP annual', value: '$199.99 per year', note: 'Roughly the price of 10–33 weeks of the weekly tiers, depending on which tier you compare against.' },\n  ]}\n/>\n\n<Screenshot\n  src=\"/screenshots/reelshort-coin-packs.webp\"\n  alt=\"ReelShort unlock popup showing coin packs at $4.99 for 500 coins, $9.99 for 1,100 coins and $19.99 for 2,400 coins, with a 60-coin price for the locked episode\"\n  caption=\"Coin packs as shown in the unlock popup on Android, 9 October 2026. The smallest packs only appear here — the main store page starts at $19.99.\"\n/>\n\n<h2 id=\"coin-economics\">Coin economics: fine for one series, bad for a habit</h2>\n\nOne episode costs 60 coins. At the smallest pack ($4.99 for 500 coins) that\nworks out to roughly **60 cents per episode** — and a full-length series here\nruns 50 to 80 episodes, so finishing one with coins costs in the region of\n**$25–45**. The largest pack ($49.99 for 7,500 coins) drops the unit price by a\nthird, but you would need to finish two to three series to burn through it.\n\nOne detail worth knowing before you buy: the store page only advertises the\nthree large packs ($19.99 and up). The $4.99 and $9.99 packs exist, but they\nsurface in the unlock popup when you tap a locked episode. If you only want one\nseries, go looking for the small packs — do not let the store page talk you\ninto the $19.99 tier by hiding the alternatives.\n\n<Callout kind=\"info\" title=\"The one-line test\">\nIf you can name the exact series you want to finish and you will not start\nanother one this month, coins are the right purchase. If you cannot name a\nsingle series, you are about to pay per episode for browsing.\n</Callout>\n\n<h2 id=\"vip-economics\">VIP economics: a ceiling, if you use it</h2>\n\nThe weekly tiers renew at $5.99 (with ads) up to $19.99 per week — the highest\nrenewal prices in the category, which is the single most important thing to know\nabout them. The annual tier changes the maths completely: at $199.99 a year it\nworks out to roughly $3.85 per week, well under any weekly renewal price.\n\nOne thing we confirmed the hard way, by checking on two consecutive days: **the\ndiscounted first week is not a fixed offer**. On 8 October our account was\nshown a $1.99 first week (marketed as 67% off); on 9 October the same device\nand account were shown $15.99 first week (21% off, with a 24-hour countdown).\nThe renewal prices stayed consistent — it is the hook price that moves. So when\na screenshot or advert shows you a bargain first week, assume that number was\ntrue for someone, once.\n\n<Screenshot\n  src=\"/screenshots/reelshort-vip-plans.webp\"\n  alt=\"ReelShort store subscription screen showing VIP tiers with weekly and monthly renewal prices\"\n  caption=\"VIP tiers as shown in the in-app store on 8 October 2026. The intro prices here had changed by our next visit a day later — the renewal prices are the ones to compare.\"\n/>\n\n<h2 id=\"break-even\">The break-even rule</h2>\n\nWe reduce this to one question, because everything else is a detail:\n\n<ol class=\"steps\">\n  <li>\n    <strong>How many series will you finish this month?</strong>\n    Write down a number before you look at any price. Most people overestimate\n    this by a wide margin.\n  </li>\n  <li>\n    <strong>Zero or one:</strong> buy coins for that specific series. Do not\n    subscribe. One series at 60 coins per episode is roughly $25–45 depending on\n    length — less than a single month of the top weekly tier.\n  </li>\n  <li>\n    <strong>Two or more:</strong> the subscription route wins. Even the $11.99\n    weekly renewal covers more viewing than two coin-finished series, and the\n    annual tier at $199.99 beats buying the weekly one repeatedly.\n  </li>\n  <li>\n    <strong>Unsure:</strong> start with the free episodes and coins for a single\n    series. You can always subscribe later — there is no discount for committing\n    early, so there is no reason to guess.\n  </li>\n</ol>\n\n<h2 id=\"hidden-costs\">Where the cost actually hides</h2>\n\nThe published prices are not where people lose money. These are:\n\n<ul>\n  <li><strong>Renewal drift.</strong> A weekly tier renews roughly 52 times a\n  year. \"I'll cancel next week\" is the most expensive sentence in this app.\n  The Google Play confirmation screen states plainly that the subscription\n  \"automatically renews until cancelled\".</li>\n  <li><strong>Intro-price whiplash.</strong> The discounted first week rotates —\n  we documented a 67%-off offer and a 21%-off offer on consecutive days. Judge\n  the app by its renewal price, which is what you will actually pay most weeks.</li>\n  <li><strong>Paying per episode for browsing.</strong> Spending coins to sample\n  something you then abandon. The free episodes exist precisely so you don't\n  have to do this — see\n  <a href=\"/guides/how-to-get-free-coins-on-reelshort\">how far the free tier gets you</a>.</li>\n  <li><strong>Hidden small packs.</strong> The $4.99 and $9.99 packs are only\n  shown inside the episode unlock popup. Buying from the store page alone means\n  paying $19.99 minimum.</li>\n</ul>\n\n<Screenshot\n  src=\"/screenshots/reelshort-purchase-confirmation.webp\"\n  alt=\"Google Play purchase confirmation screen for ReelShort weekly subscription showing $1.99 for the first week and $5.99 per week starting October 15\"\n  caption=\"The Google Play confirmation screen, 8 October 2026: $1.99 for the first week, then $5.99 per week from 15 October, plus tax. The renewal line is the number most people miss.\"\n/>\n\n<Callout kind=\"alert\" title=\"Before you subscribe to any tier\">\nKnow three things: the exact renewal period, the price after any introductory\noffer, and how you will cancel. Our\n<a href=\"/guides/how-to-cancel-reelshort-subscription\">cancellation walkthrough</a>\ncovers the third one — read it before you subscribe, not after the first charge.\n</Callout>\n\n<AffiliateCTA\n  appName=\"ReelShort\"\n  href=\"https://r.reelsgo.tv/1vwtyh4hj9R3\"\n  sub=\"Free to download · confirm current pricing in-app before you pay\"\n  buttonLabel=\"Open ReelShort\"\n/>\n\n<h2 id=\"limitations\">What we cannot price for you</h2>\n\n- **We cannot give you a single monthly figure.** Anyone who does is guessing at\n  your viewing habit. The number that matters is cost per finished series.\n- **These are Android prices.** We verified every figure on an Android phone\n  with a US Google Play account. Apple's App Store tiers, the web player, and\n  non-US accounts can all differ. Check the price on the platform you will\n  actually pay on.\n- **The intro price you see will probably differ from ours.** It rotated between\n  our two visits a day apart. The renewal prices held steady across both days,\n  which is why we anchor every comparison to those.\n- **The comparison with other apps is a shape comparison, not a price promise.**\n  Our <a href=\"/guides/reelshort-vs-dramabox\">ReelShort vs DramaBox</a> breakdown\n  explains why a subscription-first app is structurally cheaper per series —\n  that conclusion holds even when the exact figures move.\n\n<h2 id=\"bottom-line\">Bottom line</h2>\n\nCoins are the pay-per-episode route and VIP is the ceiling — pick the shape that\nmatches your actual habit, not your aspirational one. Name the number of series\nyou will finish this month, then buy accordingly. That single decision is worth\nmore than any discount you will find.","src/content/guides/reelshort-price-explained.mdx","81add808ea4319eb",{id:177,data:232,body:276,filePath:277,digest:278,deferredRender:74},{title:233,description:234,app:16,targetKeyword:235,intent:236,shortAnswer:237,publishedOn:26,updatedOn:27,priceVerifiedOn:27,toc:243,faqs:260,relatedGuides:273},"ReelShort vs DramaBox: Which Is Cheaper, and Which Should You Actually Pick?","Polish vs volume. ReelShort wins on original English production; DramaBox on cost per series by a wide margin. Both apps price-tested on Android in October 2026.","reelshort vs dramabox","mid",[238,239,240,241,242],"Verified on Android, 8–9 October 2026: DramaBox costs $9.99/week for the first 3 weeks then $12.99/week for unlimited viewing; ReelShort VIP renews at $5.99–$19.99/week and its coins work out to about $0.60 per episode.","DramaBox is far cheaper per finished series — one week of subscription versus roughly $25–45 in ReelShort coins for the same series.","ReelShort has native English originals with Western casts; DramaBox leans on dubbed and subtitled titles.","DramaBox starts charging earlier: we hit its paywall at episode 12 of one series, while ReelShort series ran 10–16 free episodes.","Pick by habit: finish about one series a month → ReelShort coins. Two or more → DramaBox subscription.",[244,246,249,252,255,258],{id:90,label:245},"The 30-second answer",{id:247,label:248},"side-by-side","Side by side",{id:250,label:251},"cost","The cost gap is the whole story",{id:253,label:254},"quality","Where production quality differs",{id:256,label:257},"decide","How to decide",{id:48,label:259},"Where this comparison breaks down",[261,264,267,270],{q:262,a:263},"Is ReelShort or DramaBox cheaper?","DramaBox is substantially cheaper for finishing a series. Verified in-app on Android (October 2026): DramaBox unlimited membership is $9.99/week for the first 3 weeks then $12.99/week ($119.99/year, about $2.31/week), and one week covers multiple full series. Finishing the same series with ReelShort coins costs roughly $25–45 at 60 coins per episode.",{q:265,a:266},"Which has better content quality?","ReelShort has more consistent per-title production quality because it commissions English-language originals with real casts. DramaBox has a much larger catalogue, but quality varies more between titles and most audio is dubbed rather than performed in English.",{q:268,a:269},"Which has more shows?","DramaBox claims 16,000+ series with 100+ new titles every week (stated on its own membership page). ReelShort keeps a smaller, more curated catalogue with a higher average production standard.",{q:271,a:272},"Can I use both?","Yes, and for some viewers that is the sensible answer — use the free tiers on both to sample broadly, then pay only on the one whose catalogue actually holds your attention.",[67,69,68,274,275],"dramabox-subscription-cost","is-dramabox-legit","import Callout from '../../components/Callout.astro';\nimport PriceTable from '../../components/PriceTable.astro';\nimport Screenshot from '../../components/Screenshot.astro';\nimport AffiliateCTA from '../../components/AffiliateCTA.astro';\n\n<h2 id=\"short-version\">The 30-second answer</h2>\n\nThis comparison does not resolve cleanly, and anyone who tells you otherwise is\nselling something.\n\n**Cost:** DramaBox wins by a wide margin. Unlimited membership is $9.99/week for\nthe first 3 weeks then $12.99/week (verified in-app on Android, 9 October 2026),\nand one week covers as many series as you can watch. Finishing a single series\nwith ReelShort coins costs roughly $25–45.\n\n**Production:** ReelShort wins on a taste judgement that is widely shared — it\nfilms English-language originals with Western casts, so there is no dubbing to\nget wrong.\n\nThe decision comes down to one habit question: how many series do you finish a\nmonth?\n\n<Screenshot\n  src=\"/screenshots/reelshort-dramabox-apps-together.webp\"\n  alt=\"Android device app screen showing the ReelShort and DramaBox icons installed side by side\"\n  caption=\"Both apps installed on the same device — the setup we used for every price check on 8–9 October 2026\"\n/>\n\n<h2 id=\"side-by-side\">Side by side</h2>\n\n<PriceTable\n  verifiedOn=\"2026-10-09\"\n  caption=\"ReelShort vs DramaBox — both verified in-app on Android (US Google Play account), 8–9 October 2026\"\n  col1=\"Dimension\"\n  col2=\"ReelShort vs DramaBox\"\n  rows={[\n    { label: 'Payment model', value: 'ReelShort: coins first, VIP available. DramaBox: subscription first, coins optional.' },\n    { label: 'Entry to unlimited', value: 'ReelShort: VIP renews $5.99–$19.99/week. DramaBox: $9.99/week × 3 weeks, then $12.99/week.' },\n    { label: 'Annual option', value: 'ReelShort: $199.99/year. DramaBox: $119.99/year (marketed as $2.31/week).', note: 'DramaBox undercuts ReelShort by $80/year on the annual tier' },\n    { label: 'Cost per episode', value: 'ReelShort: 60 coins ≈ $0.60. DramaBox: 50 coins ≈ $0.50.', note: 'Almost identical once you convert coins to dollars — the \"cheaper coins\" are a rounding error' },\n    { label: 'Cost to finish one season', value: 'ReelShort: roughly $25–45 in coins. DramaBox: one week of membership ($9.99–$12.99).', note: 'The single biggest difference between the two apps' },\n    { label: 'Where the paywall starts', value: 'ReelShort: 10–16 free episodes depending on series. DramaBox: we hit it at episode 12.', note: 'Both vary by title — neither publishes the boundary' },\n    { label: 'Free-coin ceiling', value: 'ReelShort: 17 ad tasks/day, 10 ad unlocks/day. DramaBox: 15 video tasks/day, 8 ad unlocks/day.' },\n    { label: 'Catalogue size', value: 'ReelShort: narrow and curated. DramaBox: 16,000+ series claimed, 100+ new a week.' },\n    { label: 'Language handling', value: 'ReelShort: original English, no dub needed. DramaBox: dubbed and subtitled in many languages.' },\n  ]}\n/>\n\n<Screenshot\n  src=\"/screenshots/reelshort-vs-dramabox-pricing.webp\"\n  alt=\"Side by side screenshots of ReelShort coin packs and VIP tiers next to the DramaBox membership page showing weekly and annual prices in dollars\"\n  caption=\"Both pricing screens, verified 9 October 2026: ReelShort sells coins per episode (left); DramaBox sells a weekly membership that covers everything (right).\"\n/>\n\n<h2 id=\"cost\">The cost gap is the whole story</h2>\n\nStrip away everything else and the difference is this: on one app you pay per\nepisode, and on the other you pay per week.\n\nPer-episode pricing has no ceiling. At 60 coins per episode and roughly a\ncent per coin, a 60-episode ReelShort series costs $25–45 to finish. That is\nnot a pricing accident — coin economies are designed to convert the moment of\nmaximum narrative investment into a purchase. We work through that mechanism in\ndetail in\n<a href=\"/guides/reelshort-price-explained\">our price breakdown</a>.\n\nSubscription-first pricing has a ceiling but a different failure mode: it charges\nyou whether you watch or not. DramaBox's own tips screen states that Google Play\nwill auto-charge within 24 hours before each period ends.\n\nOne thing the headline numbers hide: the per-episode prices are nearly\nidentical once converted. ReelShort's 60 coins ≈ $0.60; DramaBox's 50 coins ≈\n$0.50 at its smallest $2.99 pack. If you plan to finish series with coins,\nDramaBox saves you ten cents an episode — the real difference is that DramaBox\nmakes the subscription the obvious path, and the subscription is where the gap\nwidens to $20–30 per series.\n\nSo the two apps are actually optimised for opposite viewers:\n\n- **Occasional viewer** (one series a month) — coins on ReelShort are a clean,\n  bounded purchase. A subscription would keep charging between series.\n- **Regular viewer** (two or more a month) — DramaBox's subscription structure is\n  dramatically cheaper per series, and the ceiling protects you.\n\nThere is a second-order effect worth naming, because it is where most of the\nmoney actually goes. A subscription you forget to cancel costs more than an\nexpensive purchase you made deliberately. Coin purchases end when you stop\nbuying them; subscriptions do not. That asymmetry means the \"expensive\" app can\nend up cheaper if you are bad at cancelling, and the \"cheap\" app can end up\ncosting more if you are not. Our\n<a href=\"/guides/how-to-cancel-reelshort-subscription\">cancellation walkthrough</a>\ncovers the mechanics for anyone who wants to neutralise that risk.\n\n<Callout kind=\"info\" title=\"The mistake to avoid\">\nChoosing by catalogue size or production quality before working out your viewing\nvolume. Both of those are secondary to the pricing shape, because the pricing\nshape is what determines whether a habit costs you $6 a week or $40 a month.\n</Callout>\n\n<h2 id=\"quality\">Where production quality actually differs</h2>\n\nThe difference is not \"good\" versus \"bad\" — it is consistency versus volume.\n\nReelShort commissions a smaller number of English-language originals shot with\nreal casts. Fewer titles, higher and more even production standard, and no\ndubbing mismatch because there is no dub.\n\nDramaBox runs the opposite strategy: a much larger catalogue (16,000+ series\nclaimed on its own membership page) with a very fast refresh rate, priced far\nlower. The trade-off is variance — production quality differs more between\ntitles, and most audio is dubbed rather than performed in English.\n\nThe paywall timing differs too, and it matters more than people expect. In our\ntesting, ReelShort series ran 10–16 free episodes before charging (it varies by\ntitle, and neither app publishes the boundary). DramaBox hit its paywall at\n**episode 12** of the first series we opened. If you binge before you commit,\nReelShort gives you a longer free sample; DramaBox starts monetising sooner but\ncharges less once it does.\n\n<Screenshot\n  src=\"/screenshots/reelshort-vs-dramabox-catalogue.webp\"\n  alt=\"Side by side screenshots of a ReelShort episode list with locked episodes and a DramaBox series page showing its episode grid\"\n  caption=\"Where the free runs end: the ReelShort series on the left locked around episode 15; the DramaBox series hit its paywall at episode 12.\"\n/>\n\n<h2 id=\"decide\">How to decide</h2>\n\n<ol class=\"steps\">\n  <li>\n    <strong>Use the free tiers on both first.</strong>\n    Both give you free opening episodes. Sample the same genre on each and see\n    which one you actually keep watching. This costs nothing and answers the\n    question better than any comparison table. We break down how far each free\n    tier gets you:\n    <a href=\"/guides/how-to-get-free-coins-on-reelshort\">ReelShort</a> and\n    <a href=\"/guides/dramabox-free-coins\">DramaBox</a>.\n  </li>\n  <li>\n    <strong>Count how many series you finish a month.</strong>\n    Be honest — most people overestimate this significantly.\n  </li>\n  <li>\n    <strong>Zero to one series:</strong> ReelShort with coins for that specific\n    series — but buy the small packs from the unlock popup, not the store page.\n    Bounded spend, no renewals to manage.\n  </li>\n  <li>\n    <strong>Two or more series:</strong> DramaBox. The subscription structure is\n    the cheaper shape for that habit, and the annual tier ($119.99) is $80\n    cheaper than ReelShort's if you last that long.\n  </li>\n  <li>\n    <strong>Watch on a television:</strong> neither as a first choice — though\n    DramaBox's bigger grid tolerates a living-room screen better than\n    ReelShort's portrait originals.\n  </li>\n</ol>\n\n<AffiliateCTA\n  appName=\"ReelShort\"\n  href=\"https://r.reelsgo.tv/1vwtyh4hj9R3\"\n  sub=\"Free to download · best for one or two series a month\"\n/>\n\n<AffiliateCTA\n  appName=\"DramaBox\"\n  href=\"https://r.reelsgo.tv/uR3A7JBLdipd\"\n  sub=\"Free to download · cheapest per finished series\"\n/>\n\n<h2 id=\"limitations\">Where this comparison breaks down</h2>\n\n- **The price gap is structural, the figures are not.** Subscription-first versus\n  coin-first is a permanent difference in shape; the exact dollar amounts are\n  not — both apps run rotating intro offers with 24-hour countdowns. Treat the\n  direction of the gap as reliable and the numbers as a snapshot of 8–9 October 2026.\n- **These are US-account Android prices.** DramaBox additionally prices by your\n  IP region: the same device and account showed Japanese yen prices when our\n  connection exited in Japan, and dollar prices when it exited in the US. What\n  you see may differ from what we saw.\n- **Neither is a good television option.** If a TV is your main screen, this\n  whole comparison is largely irrelevant.\n- **We cannot judge whether you will like either catalogue.** Genre coverage\n  differs as much as volume does, and no table captures that.\n- **We earn a commission on both apps.** That is why we have written down which\n  one is worse for a given viewer — a comparison that always recommends one app\n  is not a comparison.\n\n<h2 id=\"bottom-line\">Bottom line</h2>\n\nDramaBox is cheaper and bigger; ReelShort is better made and better performed in\nEnglish. Neither is the wrong answer, but picking before you know your monthly\nviewing volume is. Sample both on the free tiers, count your habit honestly, and\nthe choice makes itself.","src/content/guides/reelshort-vs-dramabox.mdx","b739a8b6c2afb70b",{id:274,data:280,body:327,filePath:328,digest:329,deferredRender:74},{title:281,description:282,app:283,targetKeyword:284,intent:18,shortAnswer:285,publishedOn:27,updatedOn:27,priceVerifiedOn:27,toc:291,faqs:312,relatedGuides:325},"DramaBox Subscription Cost (2026): Weekly, Annual and the Coin Route, Verified","Verified DramaBox prices: $9.99/week for three weeks then $12.99/week, or $119.99 a year — plus the coin route, worked out per episode on Android.","dramabox","dramabox subscription cost",[286,287,288,289,290],"Weekly Membership costs <strong>$9.99 a week for the first three weeks</strong> (shown as 23% off $12.99), then renews at <strong>$12.99 a week</strong>.","Annual Membership costs <strong>$119.99 a year</strong> — the app markets it as \"only $2.31/week\".","Coins are the alternative: packs run <strong>$2.99 for 300 coins</strong> up to <strong>$24.99 for 3,500</strong>, and one locked episode costs 50 coins — roughly $0.50 at the smallest pack.","DramaBox prices by country. The same device showed Japanese yen and US dollars on different days, so make sure you are actually seeing USD before you compare anything.","For finishing one series, coins are usually cheaper. For two or more series a month, the annual plan wins by a wide margin.",[292,295,298,301,304,307,310],{id:293,label:294},"two-ways","The two ways DramaBox charges",{id:296,label:297},"weekly","Weekly Membership: the three-week intro",{id:299,label:300},"annual","Annual Membership",{id:302,label:303},"coins","Coins: the pay-per-episode route",{id:305,label:306},"coins-vs-membership","Coins vs membership: where the line sits",{id:308,label:309},"regional","Prices change by country — check your currency",{id:48,label:311},"What this cost breakdown does not cover",[313,316,319,322],{q:314,a:315},"How much does DramaBox cost per week?","In our in-app test on Android (October 2026), Weekly Membership was $9.99 a week for the first three weeks — displayed as 23% off the $12.99 list price — and then renews at $12.99 a week. A $3.00-off coupon popup appeared on top of the intro price on one day, but that kind of stacked discount rotates, so treat it as a snapshot rather than a promise.",{q:317,a:318},"Is the DramaBox annual plan worth it?","At $119.99 a year (about $2.31 per week as the app itself calculates), the annual plan is far cheaper per week than the $12.99 renewal rate. If you finish two or more series a month, annual is the cheapest legitimate route we measured. If you watch less than that, it is paying for content you will not open.",{q:320,a:321},"How many coins does one episode cost on DramaBox?","One locked episode costs 50 coins. Against the smallest coin pack ($2.99 for 300 coins), that works out to roughly $0.50 per episode. Note that the app spends reward coins first when you unlock, so your paid coins last longer if you have been collecting free ones.",{q:323,a:324},"Why did DramaBox show me prices in a different currency?","DramaBox prices by the country your connection appears to come from, not by your store account. On our test device the app showed Japanese yen through one connection and US dollars through another, and its own help text says to restart the app to refresh localized pricing. If the currency looks wrong, that is why.",[326,177,67,69,227],"dramabox-vs-goodshort","import Callout from '../../components/Callout.astro';\nimport Screenshot from '../../components/Screenshot.astro';\nimport AffiliateCTA from '../../components/AffiliateCTA.astro';\n\n<h2 id=\"two-ways\">The two ways DramaBox charges</h2>\n\nDramaBox sells the same catalogue two ways, and the right answer depends almost\nentirely on how many series you finish:\n\n- **Membership** — a weekly or annual subscription that unlocks everything\n- **Coins** — a pay-per-episode balance, 50 coins per locked episode\n\nEvery price below was read inside the app on an Android phone with a US Google\nPlay account, on 9 October 2026. All figures in USD. We also captured the same\npages in Japanese yen a day earlier, which turns out to matter — see the\nregional pricing section.\n\n<Screenshot\n  src=\"/screenshots/dramabox-membership-plans.webp\"\n  alt=\"DramaBox membership page on Android showing Weekly Membership at $9.99 for the first three weeks and Annual Membership at $119.99 per year\"\n  caption=\"The membership page on Android, 9 October 2026: $9.99/week intro against a $12.99 list price, with the annual plan pitched as $2.31/week\"\n/>\n\n<h2 id=\"weekly\">Weekly Membership: the three-week intro</h2>\n\nThe weekly plan is priced as a hook: **$9.99 per week for the first three\nweeks**, displayed against a crossed-out $12.99 and labelled 23% off, with a\n24-hour countdown. After week three it renews at **$12.99 per week**.\n\nThree things to know before you tap Join:\n\n- **The intro price is temporary in every sense.** Like ReelShort, DramaBox\n  rotates its discount (we saw a $3.00-off coupon popup layered on top on the\n  same day). The number you see tomorrow may not be the number we saw.\n- **Google Play charges 24 hours before each period ends**, and the renewal\n  rate is nearly 30% above the intro rate. This gap is where most people\n  overspend — see\n  <a href=\"/guides/how-to-cancel-dramabox-subscription\">how to cancel a DramaBox\n  subscription</a> for the mechanics, step by step.\n- **\"Cancel anytime\" is real but it lives in Google Play**, not in the app.\n  Cancelling keeps your access until the period you already paid for ends.\n\n<h2 id=\"annual\">Annual Membership</h2>\n\nThe annual plan is **$119.99 per year**, and the app does the division for you:\n\"Only $2.31/week\". That is the honest comparison to the $12.99 weekly renewal —\nthe annual plan costs less than a fifth per week.\n\nMembership includes unlimited access to a catalogue the app counts at 16,000+\nseries with 100+ new dramas a week, downloads, 1080p playback, members-only\ntitles, and a member points system.\n\n<Callout kind=\"info\" title=\"The points system is a retention hook, not a bonus\">\nMember points can only be earned by paying members, and 500 points buys one\nextra day of membership. It is a discount on a subscription you already have —\nworth taking, but it should not factor into whether you subscribe.\n</Callout>\n\n<h2 id=\"coins\">Coins: the pay-per-episode route</h2>\n\nIf you do not want a subscription at all, coins unlock individual episodes at\n50 coins each. The packs we recorded:\n\n| Pack | Price | Coins | Cost per coin |\n|---|---|---|---|\n| Starter | $2.99 | 300 | ~$0.0100 |\n| Popular | $6.99 | 770 (700 + 70 bonus) | ~$0.0091 |\n| Value | $12.99 | 1,600 (1,300 + 300 bonus) | ~$0.0081 |\n| Best value | $24.99 | 3,500 (2,500 + 1,000 bonus) | ~$0.0071 |\n\nAt the starter pack's rate, one episode costs about **$0.50**. A 43-episode\nseries with roughly 11 free opening episodes therefore costs around **$16 in\ncoins** to finish with the smallest pack, or about **$11** if you buy the\nlargest pack.\n\n<Screenshot\n  src=\"/screenshots/dramabox-store-plans.webp\"\n  alt=\"DramaBox store page showing coin packs and membership offers priced in US dollars\"\n  caption=\"The store view where both routes are sold side by side — coins on one screen, membership one tap away\"\n/>\n\nFree coins do exist, and they are worth collecting before you buy anything:\nthe check-in calendar pays up to 50 coins on day seven, video tasks pay 20\ncoins each up to 15 times a day, and new accounts get one-time bonuses for\nsigning in and enabling notifications. We count every source and its daily cap\nin <a href=\"/guides/dramabox-free-coins\">DramaBox free coins</a>.\n\n<Screenshot\n  src=\"/screenshots/dramabox-checkin-rewards.webp\"\n  alt=\"DramaBox reward coins page showing a seven day check-in calendar from 10 to 50 coins and task bonuses\"\n  caption=\"The free route on Android, 9 October 2026: check-ins from 10 up to 50 coins, plus 20 coins per video task, 15 tasks a day\"\n/>\n\n<h2 id=\"coins-vs-membership\">Coins vs membership: where the line sits</h2>\n\nThe crossover is easy to compute once you know your own habits:\n\n- **One series a month or less:** coins. Finishing a typical series costs\n  $11–16 in coins, against $9.99 for the first week of membership — close\n  enough that the subscription only wins if you finish within a week and\n  cancel on time.\n- **Two or more series a month:** the annual plan. At roughly $10 a month\n  equivalent, it undercuts coin spending decisively.\n- **Binge-heavy months:** a single week of membership covers a full short\n  series if you watch intensively and cancel before renewal. This is the\n  cheapest paid route of all — but it depends on you actually cancelling,\n  which is exactly the step people forget.\n\nFor the head-to-head numbers against ReelShort, see\n<a href=\"/guides/reelshort-vs-dramabox\">our direct comparison</a> — the short\nversion is that DramaBox's entry coin pack is cheaper ($2.99 vs $4.99) while\nits largest pack is slightly worse value, and its weekly renewal sits inside\nReelShort's observed range.\n\n<h2 id=\"regional\">Prices change by country — check your currency</h2>\n\nThis is the finding that most price-writeups miss. DramaBox displays prices\nbased on the country your connection appears to come from, and its own store\npage says to restart the app to refresh localized pricing.\n\nWe proved it accidentally: the same phone, same Google account, showed the\nfull price list in **Japanese yen** one day and **US dollars** the next after\nthe network path changed.\n\n<Screenshot\n  src=\"/screenshots/dramabox-paywall-regional-pricing.webp\"\n  alt=\"DramaBox paywall on episode 12 showing coin packs and membership priced in Japanese yen\"\n  caption=\"The same paywall viewed through a Japanese connection: 300 coins for ¥410 and weekly membership at ¥1,480 — regional pricing in action\"\n/>\n\nPractically: if you are comparing prices across sites, first confirm the\ncurrency on your own screen matches the article you are reading. A yen price\nis not a dollar price, and a review that mixes them is wrong on arrival.\n\n<h2 id=\"limitations\">What this cost breakdown does not cover</h2>\n\n- **These are Android, US-account prices from 9 October 2026.** DramaBox\n  rotates discounts and adjusts regional pricing often; the shape of the table\n  will outlast the specific numbers. Re-check in the app before you buy.\n- **We did not test iOS pricing.** Apple's commission sometimes produces\n  different in-app prices, and we will not claim a number we have not seen.\n- **The coin estimates assume 50 coins per episode**, which held across the\n  titles we opened. Some promotional or members-only series may price\n  differently, and series length varies widely, so per-series figures are\n  worked examples rather than a guarantee.\n- **This page will not tell you whether DramaBox is worth watching** — only\n  what it costs. For that, see <a href=\"/apps/dramabox\">our full DramaBox\n  review</a>, including where its paywall lands compared with ReelShort.\n\n<h2 id=\"bottom-line\">Bottom line</h2>\n\nDramaBox costs $9.99 a week for three weeks, then $12.99 a week — or $119.99\na year, which is about $2.31 a week. Coins price out at roughly $0.50 per\nepisode from the smallest pack and less from bigger ones.\n\nOne series a month: coins, or a single well-timed subscription week. Two or\nmore: annual. And whichever route you pick, confirm you are looking at USD —\nthe app will happily show you a different currency and a different discount\ntomorrow.\n\n<AffiliateCTA\n  appName=\"DramaBox\"\n  href=\"https://r.reelsgo.tv/uR3A7JBLdipd\"\n  sub=\"Free to download · check the current intro price in-app before you join\"\n  buttonLabel=\"Open DramaBox\"\n/>","src/content/guides/dramabox-subscription-cost.mdx","e5f1ea25af875467",{id:178,data:331,body:371,filePath:372,digest:373,deferredRender:74},{title:332,description:333,app:334,targetKeyword:335,intent:18,shortAnswer:336,publishedOn:27,updatedOn:139,priceVerifiedOn:27,toc:341,faqs:357,relatedGuides:370},"How to Stop Paying for Short Drama Apps (2026): A Playbook That Actually Cuts the Bill","Cancel the renewal first, then re-plan: free episodes, check-ins, ad unlocks and deliberate coin buys cut most short-drama bills. Here is the working playbook.","general","how to stop paying for short drama apps",[337,338,339,340],"<strong>Step one is always the same: cancel the auto-renewal</strong> in your phone&apos;s subscription settings (Google Play or the App Store) — not inside the app. Cancelling in the app does nothing on most platforms.","After that, the free tier is bigger than people think: the series we tested ran <strong>10–16 free episodes</strong> each, and check-ins, watch-time tasks and ad unlocks add up to a few hundred coins a day.","Buy coins below roughly two series a month; subscribe (annually) above it. The middle ground — a single week of membership per binge — is the cheapest paid route of all, but only if you cancel on time.","The bill is not driven by prices, which barely differ between apps. It is driven by renewals you forgot and coin packs you bought to finish one scene. Both are decision problems, not price problems.",[342,345,348,351,354,355],{id:343,label:344},"step-one","Step one: kill the renewal",{id:346,label:347},"free-maths","Step two: re-learn what the free tier covers",{id:349,label:350},"pick-shape","Step three: pick your payment shape on purpose",{id:352,label:353},"reminder","Step four: the reminder that saves the most money",{id:156,label:157},{id:48,label:356},"When this playbook does not work",[358,361,364,367],{q:359,a:360},"Do I have to pay to keep watching short dramas?","No, but you will hit a ceiling. In our testing every major app opens each series with a block of free episodes (roughly 10–16 before the paywall) and pays a few hundred coins a day through check-ins, watch-time tasks and ad unlocks. That is enough to sample widely and finish the occasional short series. It is not enough to binge continuously — the caps are the business model.",{q:362,a:363},"Will cancelling my subscription delete the episodes I already paid for?","No. Cancelling stops the next charge; you keep access until the end of the period you already paid for. Coins you purchased remain in your balance. What you lose is the unlimited-access privilege once the period expires.",{q:365,a:366},"Why did I get charged even though I stopped watching?","Because watching and paying are not linked. These subscriptions renew automatically until cancelled, and Google Play charges up to 24 hours before the new period starts. The fix is a calendar reminder one or two days after you subscribe — before the renewal, not after the charge.",{q:368,a:369},"Are coin packs cheaper than subscriptions?","Depends entirely on volume. Coins priced out at roughly $0.50–0.60 per episode at the smallest packs in our tests, so finishing one series costs about $11–16. One week of a subscription covers a full series for less. Below about two finished series a month, coins or single weeks win; above it, an annual plan does.",[69,67,11,123,227],"import Callout from '../../components/Callout.astro';\nimport Screenshot from '../../components/Screenshot.astro';\nimport AffiliateCTA from '../../components/AffiliateCTA.astro';\n\n<h2 id=\"step-one\">Step one: kill the renewal — in the right place</h2>\n\nAlmost everyone who \"stops paying\" starts here, and almost everyone does it\nwrong once. The subscription is not managed inside the app. It lives in your\nphone's subscription list:\n\n- **Android:** Google Play → your profile → Payments & subscriptions →\n  Subscriptions\n- **iPhone:** Settings → your name → Subscriptions\n\nFind the app, tap cancel, and you keep access until the period you already\npaid for runs out. Nothing you bought disappears; coins stay in your balance.\n\n<Callout kind=\"alert\" title=\"Cancelling inside the app usually does nothing\">\nThe apps show \"Cancel anytime\" buttons that open a web page or a help article.\nThe actual control is in your phone's subscription settings. If you only\n\"cancelled\" in the app, check your subscription list now — that is the single\nmost common way people keep getting charged.\n</Callout>\n\nOne timing detail that costs people money: Google Play bills **up to 24 hours\nbefore** each period ends, and subscription pages on these apps frequently\nadvertise a renewal rate well above the intro price. On the account we tested,\na weekly plan renewed at a higher rate than the discounted first week, and all\nprices were subject to tax on top.\n\n<Screenshot\n  src=\"/screenshots/reelshort-purchase-confirmation.webp\"\n  alt=\"Google Play purchase confirmation for a weekly short drama subscription showing the renewal date and the cancel anytime line\"\n  caption=\"The purchase screen that matters: renewal date, renewal price, tax on top, and the cancellation path — read it before you confirm, not after\"\n/>\n\n<h2 id=\"free-maths\">Step two: re-learn what the free tier actually covers</h2>\n\nPeople who feel trapped by these apps are usually using the free tier far\nbelow its actual capacity. Here is what it covered in our October 2026\ntesting on two of the biggest apps:\n\n- **Free opening episodes: 10–16 per series.** The boundary is not published\n  and it differs from title to title, so check the episode list of the series\n  you actually want before assuming.\n- **Daily check-ins:** a seven-day streak across the two apps we measured paid\n  between 165 and 375 coins in week one.\n- **Watch-time tasks:** up to roughly 300–340 coins a day for minutes you were\n  going to watch anyway.\n- **Ad unlocks:** 8–10 episodes a day on selected titles, paid in advertising\n  time rather than money.\n\n<Screenshot\n  src=\"/screenshots/reelshort-episode-free-boundary.webp\"\n  alt=\"Episode list inside a short drama app showing unlocked early episodes and the first locked paid episode\"\n  caption=\"The free block ends somewhere in the early teens of every series — ten to sixteen episodes per title adds up quickly across series\"\n/>\n\nThe honest arithmetic: one locked episode costs 50–60 coins, and the passive\nsources generate a few hundred coins a day. That is roughly five episodes a\nday of effort-free viewing, forever, at zero dollars. It will not support\nbingeing three series a week — but it will support watching more than most\npeople realise.\n\n<Screenshot\n  src=\"/screenshots/dramabox-checkin-rewards.webp\"\n  alt=\"Short drama app rewards page showing a seven day check-in calendar and video task bonuses\"\n  caption=\"Check-ins and video tasks on DramaBox — the amounts are small individually and stack up over a week\"\n/>\n\n<h2 id=\"pick-shape\">Step three: pick your payment shape on purpose</h2>\n\n\"Stop paying\" does not have to mean \"pay zero\". It means paying for a decision\nyou made, instead of a renewal you forgot. Three shapes cover everyone:\n\n<ol class=\"steps\">\n  <li>\n    <strong>Under two finished series a month: buy coins.</strong>\n    At $0.50–0.60 an episode, finishing a series costs $11–16 from the smallest\n    pack, less from bigger ones. No renewal exists to forget.\n  </li>\n  <li>\n    <strong>Binge months: buy a single week of membership and cancel it the\n    same day.</strong>\n    One week of unlimited access covers a full short series. This is the\n    cheapest paid route that exists on these apps — and it only works if the\n    cancellation from step one actually happens.\n  </li>\n  <li>\n    <strong>Two or more series every month: subscribe annually.</strong>\n    The weekly renewal rates we observed ($5.99–$19.99 across two apps)\n    dwarf the annual equivalents. If you are a regular viewer, annual is the\n    adult decision — see\n    <a href=\"/guides/dramabox-subscription-cost\">the DramaBox cost breakdown</a>\n    for the worked numbers.\n  </li>\n</ol>\n\n<Screenshot\n  src=\"/screenshots/dramabox-membership-plans.webp\"\n  alt=\"Short drama app membership page showing a weekly intro price and an annual plan price side by side\"\n  caption=\"The two shapes side by side: an intro weekly price designed to convert, and an annual plan designed to keep you — pick deliberately\"\n/>\n\n<h2 id=\"reminder\">Step four: the reminder that saves the most money</h2>\n\nThis is unglamorous and it is the highest-value step on the page. When you\nstart any trial or discounted subscription, set a phone reminder for **two\ndays later** — before the first renewal, not after the first charge.\n\nDo the same for the day you plan to finish a series. Most coin purchases we\nsee people regret were bought at midnight to finish one more scene. A\nreminder that asks \"did I actually finish it?\" converts impulse spending into\na decision.\n\n<h2 id=\"what-does-not-work\">What does not work</h2>\n\n- **Coin generators, redeem-code sites and \"unlimited coins\" tools.** Balances\n  are held server-side; these sites harvest logins or sell nothing.\n- **Modified or tampered app builds.** They violate the terms of service, get\n  accounts banned, and are a common malware vector. They also poison the well:\n  any account credit you earned legitimately can be wiped with the ban.\n- **Subscription-hopping.** Buying a week on one app, then another, then\n  another sounds frugal and behaves like five forgotten renewals. Same rule as\n  step one, every time.\n- **Ignoring the free tier because it feels slow.** The per-series free\n  episodes are the largest allowance these apps give. Skipping them is paying\n  for content that was on offer.\n\n<h2 id=\"limitations\">When this playbook does not work</h2>\n\n- **If you watch more than about ten episodes a day, every day**, the free\n  tier's caps will not cover you, and no legitimate trick will. The useful\n  question becomes which paid shape is cheapest, not whether to pay.\n- **The numbers here are from Android with a US account, October 2026.**\n  Caps, coin amounts and intro prices rotate constantly on these apps. The\n  playbook outlasts the figures; the figures will not survive the quarter.\n- **iOS pricing can differ** from Android for the same app, and we tested on\n  Android only. Verify on your own device before relying on a specific number.\n- **If your goal is to watch specific premium titles the day they drop**,\n  free routes will not carry them. That is a legitimate reason to pay — it is\n  just a decision, not a trap, when you make it consciously.\n\n<h2 id=\"bottom-line\">Bottom line</h2>\n\nCancel the renewal in your phone's settings, set a reminder two days after\nany subscription you start, and match your payment shape to how much you\nactually watch. Between the free episodes and the daily coin sources, most\nviewers can cut their bill by half or more without watching anything less —\nand the people who pay full freight are usually the ones who skipped step one.\n\n<AffiliateCTA\n  appName=\"ReelShort\"\n  href=\"https://r.reelsgo.tv/1vwtyh4hj9R3\"\n  sub=\"Free to download · sample the free episodes before you decide to pay\"\n  buttonLabel=\"Open ReelShort\"\n/>","src/content/guides/how-to-stop-paying-for-short-drama-apps.mdx","4c919aa0dcbbb468",{id:123,data:375,body:420,filePath:421,digest:422,deferredRender:74},{title:376,description:377,app:334,targetKeyword:378,intent:18,shortAnswer:379,publishedOn:27,updatedOn:27,priceVerifiedOn:27,toc:385,faqs:406,relatedGuides:419},"The Short Drama App Subscription Trap: How the Renewal Loop Actually Works","The trap is the renewal loop, not the price: rotating intro discounts, renewals billed 24 hours early, and coin tiers hidden behind the paywall — with screenshots.","short drama app subscription trap",[380,381,382,383,384],"The trap is not the sticker price. It is the <strong>renewal loop</strong>: a discounted intro week, a renewal rate up to three times higher, and a charge that lands <strong>24 hours before</strong> each period ends.","Intro pricing rotates by day and account. The same plan showed <strong>67% off one day and 21% off the next</strong> on the account we tested — so any \"official price\" you read anywhere is a snapshot.","The cheapest coin packs are often hidden <strong>behind the episode paywall</strong> instead of on the store page, so the first price you see is not the cheapest one available.","Independent review data completes the picture: store ratings of 4.7 and 3.8 versus <strong>1.3 on Trustpilot</strong>, where the most common complaint theme is unexpected payment and cancelled-too-late renewals.","The exit is unglamorous: cancel in your phone&apos;s subscription settings, set a reminder two days after subscribing, and decide your volume before you open the store page.",[386,389,392,395,398,401,404],{id:387,label:388},"anatomy","The anatomy of the trap",{id:390,label:391},"rotating","Part 1: intro prices that rotate daily",{id:393,label:394},"hidden-tiers","Part 2: the cheaper packs are hidden",{id:396,label:397},"renewal","Part 3: the renewal terms you confirm at midnight",{id:399,label:400},"complaints","Part 4: what the complaint data says",{id:402,label:403},"exit","How to opt out deliberately",{id:48,label:405},"Limits of this analysis",[407,410,413,416],{q:408,a:409},"Are short drama subscription apps a scam?","Not in the fraud sense — the content exists and the prices are disclosed before you confirm. But the design leans hard on friction and urgency: intro discounts that rotate daily, renewal rates up to three times the intro price, billing 24 hours before each period ends, and the cheapest coin packs kept off the main store page. It is a legal model that profits from inattention, which is why the cancellation mechanics matter more than the price list.",{q:411,a:412},"Why was I charged more than the price I signed up at?","Two common reasons. First, the intro price was a first-period discount and the renewal rate is higher — weekly plans we observed renewed at $5.99 to $19.99 after discounted first weeks. Second, tax is added on top of the listed price at checkout. Both are on the confirmation screen, which is easy to skim past at the moment you are trying to watch the next episode.",{q:414,a:415},"Can I get a refund on a short drama subscription?","On Android, request it through Google Play&apos;s purchase history — self-service refunds are usually granted for recent charges on an account with a clean history. On iOS, use reportaproblem.apple.com. The apps&apos; own support channels are consistently the slowest path, and independent review sites are full of complaints about exactly that.",{q:417,a:418},"How do I stop the charges without losing what I paid for?","Cancel in Google Play or the App Store subscription list. Cancelling stops future charges and keeps your access until the current period ends. Coins you bought stay in your balance. See our step-by-step cancellation guide for the exact screens.",[68,124,11,67,178,227],"import Callout from '../../components/Callout.astro';\nimport Screenshot from '../../components/Screenshot.astro';\nimport AffiliateCTA from '../../components/AffiliateCTA.astro';\n\n<h2 id=\"anatomy\">The anatomy of the trap</h2>\n\nNobody searches for \"subscription trap\" because a price felt high. The price\nof an episode on these apps is roughly what a vending machine charges. People\nsearch for it because they looked at their bank statement and found a charge\nthey did not remember approving, at a number they do not remember seeing.\n\nThat experience is manufactured, and it is worth taking apart — because once\nyou can name the four parts, you stop being the target market.\n\nEverything below comes from two of the largest apps, tested on Android with a\nUS account in October 2026, with screenshots taken at each step.\n\n<h2 id=\"rotating\">Part 1: intro prices that rotate daily</h2>\n\nThe first thing a new account sees is a discounted subscription with a\ncountdown — usually 24 hours, so the discount feels like it will disappear.\n\nHere is what the same device, same account, showed on two consecutive days:\n\n- **Day one:** weekly VIP at $1.99, labelled 67% off, renewing at $5.99/week\n- **Day two:** the same plan at $15.99 for the first week, labelled 21% off,\n  renewing at $19.99/week\n\n<Screenshot\n  src=\"/screenshots/reelshort-vip-plans.webp\"\n  alt=\"Short drama app subscription page showing a discounted weekly plan with a 24 hour countdown timer\"\n  caption=\"The rotating intro offer with its 24-hour countdown — on this account the same plan showed 67% off one day and 21% off the next\"\n/>\n\nThe lesson is not that the app is broken. The lesson is that **any published\n\"official price\" for these apps — including on this site — is a dated\nsnapshot**. The discount percentage, the intro price, and sometimes the plan\nlineup itself change per day and per account. When a renewal lands at a number\nyou do not recognise, this is usually why.\n\n<h2 id=\"hidden-tiers\">Part 2: the cheaper packs are hidden</h2>\n\nThe store page shows a coin section with packs starting around $9.99–$19.99.\nOpen a locked episode instead, and the same store reveals packs it did not\nshow before — including a **$4.99 starter pack** that was invisible from the\nmain store screen.\n\n<Screenshot\n  src=\"/screenshots/reelshort-coin-packs.webp\"\n  alt=\"In-app coin pack list opened from an episode paywall showing a small starter pack among larger bundles\"\n  caption=\"The pack list as seen from inside a locked-episode popup — the small tiers here do not appear on the main store page\"\n/>\n\nSame prices, same app, same day — different entry point. The design effect is\nsubtle: a user buying from the store page pays more per coin than a user who\nwent looking from the paywall. Nothing is hidden dishonestly, exactly. It is\njust that the cheap option requires knowing it exists.\n\n<Callout kind=\"info\" title=\"Practical takeaway\">\nNever buy coins from the store page without first opening a locked episode\nand checking the packs offered there. On both apps we tested, the paywall\nroute exposed cheaper tiers.\n</Callout>\n\n<h2 id=\"renewal\">Part 3: the renewal terms you confirm at midnight</h2>\n\nThe confirmation screen is where the model converts. It is also where nobody\nlooks, because the confirmation arrives at the exact moment you are trying to\nwatch the next episode of a cliffhanger.\n\nWhat it actually says, on the account we tested:\n\n- The renewal charge lands from **a specific date, 24 hours before** each new\n  period begins, at the **renewal rate** — not the intro rate\n- All prices are **plus tax**\n- Cancellation lives in **Google Play's subscription settings**, not the app\n\n<Screenshot\n  src=\"/screenshots/reelshort-purchase-confirmation.webp\"\n  alt=\"Google Play subscription confirmation screen showing renewal date, renewal pricing and the cancel anytime notice\"\n  caption=\"The screen that decides what you actually pay: renewal date, renewal price, tax, and where cancelling really happens\"\n/>\n\nNotice what is not here: there is no reminder before renewal, no usage-based\npause, no \"are you still watching\" check. The subscription continues on the\nassumption that you have forgotten it, and the numbers we found in independent\nreview data suggest many people have.\n\n<h2 id=\"complaints\">Part 4: what the complaint data says</h2>\n\nThe strongest evidence for the trap being structural rather than anecdotal is\nthe gap between rating ecosystems. On the same app:\n\n- **App Store:** 4.7 out of 5, from about 506,000 ratings\n- **Google Play:** 3.8, from about 1.9 million reviews\n- **Trustpilot:** 1.3 out of 5 — \"Bad\" — from 265 reviews, on a profile the\n  company has not claimed\n\n<Screenshot\n  src=\"/screenshots/reelshort-rating-comparison.webp\"\n  alt=\"Side by side comparison of an app store product page with a high rating and a Trustpilot page showing a bad rating\"\n  caption=\"Store ratings against the independent Trustpilot profile: 4.7 in one ecosystem, 1.3 in the other — the complaint themes are the tell\"\n/>\n\nThe complaint themes on the independent site are not about story quality or\nbuffering. The top topic is **payment**: repeated charges, subscriptions that\nsurvived attempted cancellation, and difficulty reaching support. That is the\nrenewal loop, described by the people it caught.\n\n<h2 id=\"exit\">How to opt out deliberately</h2>\n\nThe exit is the same whether or not you intend to keep watching:\n\n<ol class=\"steps\">\n  <li>\n    <strong>Cancel now, in your phone's settings.</strong>\n    Google Play → Payments & subscriptions, or iOS Settings → Subscriptions.\n    You keep access to the end of the paid period, and coins you bought stay\n    on your balance. See\n    <a href=\"/guides/how-to-cancel-reelshort-subscription\">the step-by-step cancellation guide</a>.\n  </li>\n  <li>\n    <strong>Check for stray charges.</strong>\n    Look at the last two billing cycles. Charges from these apps often hide\n    under the developer's name rather than the app's, which is a large part of\n    why people miss them.\n  </li>\n  <li>\n    <strong>Refund recent mistakes through the store, not the app.</strong>\n    Google Play self-service refunds and Apple's reportaproblem page both work\n    for recent charges and are faster than app support.\n  </li>\n  <li>\n    <strong>If you keep watching, choose the shape first.</strong>\n    Coins below two series a month, a single cancelled-on-time week per binge,\n    or an annual plan above that. The arithmetic is in\n    <a href=\"/guides/how-to-stop-paying-for-short-drama-apps\">our stop-paying playbook</a>.\n  </li>\n</ol>\n\n<h2 id=\"limitations\">Limits of this analysis</h2>\n\n- **Two apps, one platform, October 2026.** We tested ReelShort and DramaBox\n  on Android with a US account. iOS pricing and smaller apps may behave\n  differently, and every specific number here is a dated snapshot by design.\n- **We cannot see anyone's account but our own.** The rotating-discount\n  finding comes from one device over two days. It is consistent with the\n  countdown mechanics visible in the app, but individual experiences will vary.\n- **Trustpilot samples are self-selected.** 265 reviews skews negative by\n  nature — people with no problem rarely write reviews. The signal is the\n  <em>theme</em> of the complaints (payment, cancellation, support), not the\n  score itself.\n- **This page is not legal advice and not an accusation of fraud.** Every\n  mechanism described is disclosed on a screen the user confirms. The point is\n  that the disclosure is easy to miss, and knowing where it lives changes what\n  you pay.\n\n<h2 id=\"bottom-line\">Bottom line</h2>\n\nThe subscription trap in short drama apps is a renewal loop, not a hidden fee:\nintro prices that rotate daily, renewal rates up to three times higher, a\ncharge that lands 24 hours before each period ends, and cheaper coin packs\nkept off the main store page. None of it is hidden from someone who knows\nwhere to look — which is the point of knowing where to look.\n\n<AffiliateCTA\n  appName=\"ReelShort\"\n  href=\"https://r.reelsgo.tv/1vwtyh4hj9R3\"\n  sub=\"Free to download · decide your watching volume before the paywall asks\"\n  buttonLabel=\"Open ReelShort\"\n/>","src/content/guides/short-drama-app-subscription-trap.mdx","d21f6ab74c52fb9a",{id:227,data:424,body:478,filePath:479,digest:480,deferredRender:74},{title:425,description:426,app:334,targetKeyword:427,intent:236,shortAnswer:428,publishedOn:433,updatedOn:433,priceVerifiedOn:433,toc:434,faqs:461,relatedGuides:477},"Why Short Drama App Prices Disagree With Every Other Published Price","We found five different weekly prices for one app on one day. The apps are not lying — the price depends on day, account, region, checkout and entry point.","short drama app prices",[429,430,431,432],"Nobody is hiding the price. <strong>Several prices are live at the same moment</strong>, and which one you get depends on the day, the account, your region, the checkout you use, and which screen you opened it from.","On one app on one day we counted <strong>five weekly prices between $7.99 and $24.99</strong> — all on the same phone, minutes apart. Two different apps disagreed with each other over a figure we had already measured ourselves.","Two apps price by <strong>your exit IP country</strong>, not your store account. The same DramaBox account showed yen in one session and dollars in the next after nothing changed but the network route.","This is why comparing published prices is close to useless: <strong>any number you find is a dated snapshot of one screen</strong>, and ours are too. We publish ours with dates for exactly that reason.","2026-10-11",[435,438,441,444,447,450,453,456,458],{id:436,label:437},"not-lying","Nobody is hiding the price",{id:439,label:440},"five-prices","Five prices, one app, one day",{id:442,label:443},"three-checkouts","Reason one: the day and the account",{id:445,label:446},"region","Reason two: your region, not your account",{id:448,label:449},"entry-point","Reason three: the screen you opened it from",{id:451,label:452},"disagreement","Where the numbers actually disagree",{id:454,label:455},"what-to-do","How to compare prices honestly",{id:457,label:405},"limits",{id:459,label:460},"when-this-fails","When this guidance does not work",[462,465,468,471,474],{q:463,a:464},"Why does ReelShort cost different amounts on different days?","Because the intro rate is not a price — it is a rotating offer. On our account the same weekly plan showed $1.99 labelled 67% off on one day and $15.99 labelled 21% off the next, each with a 24-hour countdown. The renewal rate is a separate number again, and the plan list itself changes: the $1.99 tier disappeared the following day rather than being sold out.",{q:466,a:467},"Why does the price change when I change my VPN?","Two of the apps we tested price by the country your traffic exits from, not by your app store account. DramaBox rendered entirely in Japanese yen while the exit node was in Japan, and in US dollars on the same device and same account after switching to a US node. ReelShort also moved between prices when the route changed. If you use a VPN, your country of payment is not fixed.",{q:469,a:470},"Which short drama app is actually the cheapest?","There is no single answer, which is the honest version of this article. On the numbers we measured in October 2026, the cheapest weekly figure anywhere was a StardustTV coupon at $13.19 — but its per-episode coin price was 65, the highest of the apps that publish one, and finishing a series through ads took ten ads for five episodes. The cheapest entry point and the cheapest way to finish a series were different apps.",{q:472,a:473},"So why should I trust the prices on this site?","You should not treat them as current either — treat them as dated measurements, which is how we label them. Every price here carries the date and device it was recorded on, and we publish the contradictory readings rather than the prettiest one. The prices on your screen at the moment of purchase are the only ones that apply to you.",{q:475,a:476},"Can I get the same introductory price a review shows?","Not reliably. Introductory offers in these apps rotate by account as well as by day, and the ones we saw were labelled \"New Users Only\". A screenshot of someone else at $1.99 is evidence the offer exists, not evidence you will be offered it.",[67,274,123,177],"import Callout from '../../components/Callout.astro';\nimport Screenshot from '../../components/Screenshot.astro';\nimport AffiliateCTA from '../../components/AffiliateCTA.astro';\n\n<h2 id=\"not-lying\">Nobody is hiding the price</h2>\n\nSearch for the price of these apps and you will find figures that cannot all be\ntrue at once. One site says a weekly pass is $9.99. Another says $29.99. A\nthird says roughly $30 a week. All three are written confidently, and if you\nare unlucky enough to price your subscription off any one of them, you will\neither overpay or be surprised at the checkout.\n\nThe usual explanation — that sites are copying each other, or that the apps\nhide their prices — is wrong, or at least it is not the interesting part.\nWhat we found is simpler and more disorienting:\n\n<strong>The apps show several different prices at the same time.</strong>\n\nEvery one of them is real. Every one of them is shown to a real user. They\nsimply apply to different combinations of day, account, country, checkout and\nscreen. There is no single \"official price\" to look up, which is why no amount\nof searching converges on an answer.\n\nThis article is about why. And it ends with the only comparison method that\nsurvives this, which is not \"which app is cheapest\" — it is not a question with\na stable answer.\n\n<h2 id=\"five-prices\">Five prices, one app, one day</h2>\n\nHere is the cleanest example we have. NetShort, one day in October 2026, one\nAndroid device, one account, one afternoon:\n\n<ol class=\"steps\">\n  <li>\n    The <strong>Top Up page</strong> showed the weekly renewal at\n    <strong>$15.99</strong> for the first week, then <strong>$24.99</strong> after.\n  </li>\n  <li>\n    The <strong>Google Pay button</strong> on that same page read\n    <strong>$14.39</strong> — a promotional price for the same plan.\n  </li>\n  <li>\n    A <strong>new-user popup</strong> over the same screen offered\n    <strong>$7.99</strong> for the first week, then <strong>$14.99</strong> after.\n  </li>\n</ol>\n\n<Screenshot\n  src=\"/screenshots/price-mistake-netshort-two-prices.webp\"\n  alt=\"Two screens from the same short drama app on the same day showing a weekly subscription at 15.99 dollars and a new user offer at 7.99 dollars\"\n  caption=\"The same app on the same day: $15.99 on the Top Up page, $14.39 on the Google Pay button, $7.99 in the new-user popup, renewing at $24.99 or $14.99\"\n/>\n\nAdd the renewal figures and the range is <strong>$7.99 to $24.99 for one weekly\npass</strong>. No one in that screenshot is lying. The store is simply running\nthree offers at once, aimed at three different people: the user who has been\naround a while, the user who is about to tap a Google Pay button, and the user\nwho just installed the app.\n\nStardustTV runs the same pattern one step further. Its payment screen offered\na weekly pass at $17.99 with a 10% discount against a struck-through $19.99,\nwhile a coupon popup offered <strong>$13.19</strong> for the same weekly pass\nlabelled 40% off — on a one-hour countdown, with the base price never shown.\n\n<Screenshot\n  src=\"/screenshots/price-mistake-stardusttv-three-prices.webp\"\n  alt=\"Two screens from the same app showing a weekly VIP pass at 17.99 dollars and a membership coupon at 13.19 dollars\"\n  caption=\"The same weekly pass at $19.99 base, $17.99 with a 10% discount, and $13.19 through a coupon popup that never displays what it discounts\"\n/>\n\nThe arithmetic in that coupon does not work either: $13.19 is 40% off\n<strong>$21.99</strong>, not off the $19.99 the app shows elsewhere. The\ndiscount rate and the base price disagree, so \"40% off\" is not a statement\nabout the actual price. A second app in our test set made the same mistake with\na \"51% off\" popup whose base we could not establish at all.\n\nThis is worth dwelling on, because it means the price comparison most people\nperform is structurally broken. You cannot compare a site's reported $30 to a\npopup offering $7.99 and conclude that the site was wrong.\n\n<h2 id=\"three-checkouts\">Reason one: the day and the account</h2>\n\nThe offers above expire. Nearly all of them carried a countdown — usually 24\nhours, occasionally one hour — which is a clear statement that the price is\ntemporary by design.\n\nOn a ReelShort account we tracked over two consecutive days, the same weekly\nplan behaved like this:\n\n<ul>\n  <li>\n    <strong>Day one:</strong> $1.99 for the first week, labelled\n    <strong>67% off</strong>, renewing at $5.99/week.\n  </li>\n  <li>\n    <strong>Day two:</strong> $15.99 for the first week, labelled\n    <strong>21% off</strong>, renewing at $19.99/week. The $1.99 tier was no\n    longer on the page at all.\n  </li>\n</ul>\n\nTwo facts matter here. The discount percentage is not derived from a real base\nprice — 67% off and 21% off on consecutive days cannot both describe the same\nunderlying rate. And the cheap tier was <strong>withdrawn, not sold out</strong>,\nso \"while stocks last\" is not the explanation.\n\n<Callout kind=\"warning\" title=\"What this means for any published price\">\n  A screenshot of an introductory offer is evidence the offer exists, not\n  evidence you will be offered it. On the apps we tested, introductory pricing\n  rotated by account as well as by day, and the better offers were labelled\n  for new users only.\n</Callout>\n\n<h2 id=\"region\">Reason two: your region, not your account</h2>\n\nThis is the one that catches people who think they have controlled the\nvariable.\n\nDramaBox priced itself <strong>by the country our network traffic exited\nfrom</strong>. On the same device, with the same account, changing only the\nexit node switched the entire app from Japanese yen to US dollars. The app's\nown store page confirmed the mechanism in its help text, telling us to restart\nthe app if prices looked stale. Both currency screens are recorded in\n<a href=\"/apps/dramabox\">our DramaBox review</a>.\n\n<Screenshot\n  src=\"/screenshots/dramabox-paywall-regional-pricing.webp\"\n  alt=\"A paywall screen in one short drama app showing a per-episode coin price in a currency other than dollars\"\n  caption=\"The paywall price renders in the currency of your exit country — this is the same account that reads in dollars on a US route\"\n/>\n\nIf you use a VPN, or you travel, or your traffic takes a different route, your\nprice can change without you doing anything. Any comparison between two people\nis therefore also a comparison between two network routes, and most published\nprices do not record which route produced them.\n\nReelShort behaved the same way on our tests, though less completely.\n\n<h2 id=\"entry-point\">Reason three: the screen you opened it from</h2>\n\nThe last mechanism is the quietest and probably affects the most people.\n\nReelShort's store page showed coin packs starting around $9.99. Opening a\nlocked episode instead revealed the <strong>same store offering a $4.99\nstarter pack</strong> that did not appear on the main store screen.\n\n<Callout kind=\"info\" title=\"Why this matters more than it sounds\">\n  A user buying from the store page pays a higher price per coin than a user\n  who happened to open a locked episode first. Nothing is concealed — the\n  cheaper option simply requires knowing it exists. We found the same hidden\n  smaller tiers on more than one app.\n</Callout>\n\n<Screenshot\n  src=\"/screenshots/reelshort-coin-packs.webp\"\n  alt=\"An in-app coin pack list showing a small 4.99 dollar starter pack alongside larger bundles\"\n  caption=\"The pack list as seen from inside a locked-episode popup — the small tiers here do not appear on the main store page\"\n/>\n\nThere is a fourth reason, specific to the largest app, and it explains why\npeople comparing two ReelShort prices find a gap of several times rather than\na few dollars. <strong>ReelShort runs two separate checkouts</strong>, and they\ndo not agree.\n\nThe weekly plan priced at <strong>$1.99–$5.99 for the first week</strong>\nthrough Google Play in-app. The same plan on the app's own website checkout\ncame to <strong>$11.87 for the first week and $20.51 per week after</strong>,\ntax included, on the same account.\n\n<Screenshot\n  src=\"/screenshots/price-mistake-reelshort-two-checkouts.webp\"\n  alt=\"Two checkout screens for the same weekly plan showing a discounted price in the Play store and a higher price on the app website\"\n  caption=\"Two live checkouts for one weekly plan on one account — the Play route and the app's own website route\"\n/>\n\nThat matters beyond the price. A subscription bought through the website is\nnot listed in your Play or App Store subscription settings, so the cancellation\ninstructions in this site's\n<a href=\"/guides/how-to-cancel-reelshort-subscription\">cancel guide</a> do not\nreach it, and the store's refund tooling does not cover it either.\n\n<h2 id=\"disagreement\">Where the numbers actually disagree</h2>\n\nWe think the useful thing to publish is not our numbers but the\n<strong>conflicts</strong>, because a conflict survives the passage of time in\na way a single price does not. Three we can document:\n\n<table class=\"data-table\">\n  <thead>\n    <tr><th>What</th><th>One source</th><th>Our measurement</th></tr>\n  </thead>\n  <tbody>\n    <tr>\n      <td>Single-episode coin cost</td>\n      <td>A competitor site states 18 coins</td>\n      <td>ReelShort charged <strong>60</strong> — a 3.3× difference</td>\n    </tr>\n    <tr>\n      <td>DramaBox annual plan</td>\n      <td>A competitor site states $49.99</td>\n      <td><strong>$119.99</strong> in our checkout, with the app itself\n      displaying \"Only $2.31/week\"</td>\n    </tr>\n    <tr>\n      <td>NetShort weekly pass</td>\n      <td>A competitor site states about $30/week</td>\n      <td>$15.99 intro, <strong>$24.99</strong> renewal — the $30 figure\n      matched nothing we could see</td>\n    </tr>\n  </tbody>\n</table>\n\nWe are not claiming the other sites are defrauding anyone. More likely they\nrecorded a different day, a different account tier, or a different region and\nthen wrote it down without a date. That is exactly the failure mode this\narticle is about: <strong>a price without a date, a region and an account type\nis not information.</strong>\n\n<h2 id=\"what-to-do\">How to compare prices honestly</h2>\n\nThere is no shortcut, but there is a method. Ours has four steps:\n\n<ol class=\"steps\">\n  <li>\n    <strong>Compare the renewal rate, never the intro rate.</strong> The intro\n    rate is a promotion with a countdown; the renewal rate is what you pay for\n    every week after. Across our apps, renewal weekly rates ranged from $5.99\n    to $24.99 — a range four times wider than the intro prices on offer.\n  </li>\n  <li>\n    <strong>Compare per-episode cost, not pack price.</strong> Divide the pack\n    price by the coins you actually receive including bonuses. This is where\n    ranking inverts: DramaBox's entry pack is $2.99 against ReelShort's $4.99,\n    but ReelShort's large pack is the cheapest per coin of anything we sold.\n  </li>\n  <li>\n    <strong>Compare on the same day, from the same route.</strong> A\n    cross-day comparison is invalid for these apps by construction.\n  </li>\n  <li>\n    <strong>Assume your number will differ from ours.</strong> Ours were\n    recorded on specific dates, on Android, on two physical devices and one\n    emulator. Treat them as measurements, not quotes.\n  </li>\n</ol>\n\nAnd if you want the cheapest way to finish a specific series rather than the\ncheapest subscription overall, the maths is different again — per-episode coin\nprices in our tests ranged from 50 coins to 98, and the free episode allowance\nranged from episode 7 to episode 11 before the paywall, depending on the\nseries. Our\n<a href=\"/guides/how-to-stop-paying-for-short-drama-apps\">stop-paying guide</a>\nworks through the arithmetic.\n\n<h2 id=\"limits\">Limits of this analysis</h2>\n\n- **One platform, mostly Android, October 2026.** Six apps tested on Android\n  with US Google Play accounts, plus one payment taken on a physical phone. iOS\n  pricing uses Apple's billing and may not rotate identically.\n- **The rotation findings come from short observation windows.** The ReelShort\n  day-one/day-day pair is two days on one account. It matches the countdown\n  mechanics visible in the apps, but we are not claiming to have characterised\n  their rotation schedule.\n- **Competitor figures in the conflict table are as published, not verified.**\n  We have not tested those sites' methodologies and are not accusing them of\n  error — the point is that an undated, unattributed price cannot be checked.\n- **Region pricing was tested by changing the exit node, not by travelling.**\n  Other inputs — billing address, store account country, tax jurisdiction —\n  may matter too and we did not isolate them.\n- **This is not an accusation of price manipulation.** Every price described\n  here is disclosed on a screen the user confirms. The design leans on urgency\n  and entry-point discovery; that is a legal model, and the reason it works is\n  that most people never see more than one number at a time.\n\n<h2 id=\"when-this-fails\">When this guidance does not work for you</h2>\n\nThis article explains why prices disagree. It does not tell you which app is\ncheapest for you, and in several common situations it cannot:\n\n- **If you only intend to watch one series.** The whole analysis is built on\n  subscription and coin-pack prices. Finishing a single show is usually a\n  coin problem, and the cheapest entry point and the cheapest way to finish\n  were different apps in our testing.\n- **If you subscribe from iOS.** Apple's billing is a different system and we\n  have not measured whether these offers rotate the same way there. Our iOS\n  knowledge in this project comes from Apple's official documentation, not\n  from testing.\n- **If you are outside the US.** We measured on US routes, which is the most\n  crowded case. In other regions the entry price may be lower and the\n  rotation may behave differently, and we have no data on that.\n- **If you are reading this months from now.** Every figure here is a snapshot\n  from October 2026 and the mechanism will outlive it. Check the live screen,\n  not this page.\n- **If your issue is being charged after cancelling.** None of this explains\n  that, and it is a different problem — see\n  <a href=\"/guides/short-drama-app-subscription-trap\">the renewal loop</a> for\n  the billing mechanics, and expect to deal with the store, not the app.\n\n<AffiliateCTA\n  appName=\"ReelShort\"\n  href=\"https://r.reelsgo.tv/1vwtyh4hj9R3\"\n  sub=\"Free to download — open it, then check what your own screen actually charges\"\n  buttonLabel=\"Open ReelShort\"\n/>","src/content/guides/why-short-drama-app-prices-differ.mdx","962eb71a5a99c1e2","cheapest-short-drama-app",{id:481,data:483,body:527,filePath:528,digest:529,deferredRender:74},{title:484,description:485,app:334,targetKeyword:486,intent:236,shortAnswer:487,publishedOn:433,updatedOn:433,priceVerifiedOn:433,toc:492,faqs:513,relatedGuides:526},"The Cheapest Short Drama App Is Not the One With the Lowest Price","We ranked six short drama apps four ways — weekly renewal, entry price, per-episode cost and free episodes. The cheapest app changes every time.","cheapest short drama app",[488,489,490,491],"There is no single cheapest app. Ranked by <strong>weekly renewal</strong> the answer is DramaBox at $12.99; by <strong>intro price</strong> it is ReelShort at $1.99–$5.99; by <strong>entry coin pack</strong> it is DramaBox at $2.99.","The ranking <strong>inverts completely</strong> once you include free episodes. StardustTV gives ten free episodes and GoodShort seven, while DramaBox starts charging at episode 12 — the app with the lowest sticker price has among the shortest free run.","We tested six apps on Android in October 2026 and recorded <strong>every price with the date it was measured</strong>. All of these figures move; treat them as snapshots, not quotes.","The honest answer is that <strong>the cheapest app depends on how many episodes you actually intend to watch</strong> — and that number is usually small.",[493,496,499,502,505,508,510],{id:494,label:495},"by-weekly","Cheapest by weekly renewal",{id:497,label:498},"by-entry","Cheapest to start",{id:500,label:501},"by-episode","Cheapest per episode",{id:503,label:504},"by-free","Cheapest once free episodes count",{id:506,label:507},"verdict","The verdict, by viewing habit",{id:457,label:509},"Limits of this comparison",{id:511,label:512},"when-fails","When this ranking does not apply",[514,517,520,523],{q:515,a:516},"What is the cheapest short drama app right now?","It depends which price you measure. By weekly renewal it was DramaBox at $12.99/week in our October 2026 tests; by introductory price it was ReelShort at $1.99–$5.99 for a first week; by smallest first coin purchase it was DramaBox at $2.99. The introductory price is a discounted first period and is not what you pay ongoing, which is why we rank by renewal.",{q:518,a:519},"Which short drama app has the most free episodes?","In our testing StardustTV gave ten free episodes before the paywall, the widest opening of the six. GoodShort gave seven, ShortMax six, NetShort nine, ReelShort sixteen on one series but only ten on another, and DramaBox was charging by episode 12. The number varies by series, so check the specific show rather than the app.",{q:521,a:522},"Are these prices accurate right now?","They are measurements from Android in October 2026, and these apps rotate introductory pricing by day and account. The one thing that has stayed stable across everything we measured is the structure: intro price below renewal price, coin packs cheaper per coin in larger sizes, and a free allowance that varies by series.",{q:524,a:525},"Should I buy an annual plan to save money?","Only if you will still be watching in twelve months. The annual prices we recorded were $149.99 on ShortMax and GoodShort, and $99.99 on NetShort, against weekly rates of $19.99 and $24.99. NetShort annual was the only one that worked out clearly cheaper per week. If your interest is likely to fade, a cancelled weekly subscription costs less in total even at a higher unit price.",[326,227,123,177,178,179,275],"import Callout from '../../components/Callout.astro';\nimport Screenshot from '../../components/Screenshot.astro';\nimport AffiliateCTA from '../../components/AffiliateCTA.astro';\n\n<h2 id=\"by-weekly\">Cheapest by weekly renewal</h2>\n\nIf you want the number that decides whether a subscription is affordable, it is\nthe <strong>renewal rate</strong> — the price you pay every week after the\nfirst one. Introductory prices are marketing; renewal rates are arithmetic.\n\nHere is what six apps charged on renewal, all measured on Android with a US\nGoogle Play account in October 2026:\n\n<table class=\"data-table\">\n  <thead>\n    <tr><th>App</th><th>Weekly renewal</th><th>Annual, if offered</th><th>About</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>DramaBox</td><td><strong>$12.99</strong></td><td>$119.99</td><td>$1.86/week on annual</td></tr>\n    <tr><td>StardustTV</td><td><strong>$19.99</strong> base<br/>$13.19 via coupon</td><td>None offered</td><td>No annual tier in the payment flow</td></tr>\n    <tr><td>ReelShort</td><td><strong>$19.99</strong><br/>(also saw $5.99 / $11.99 tiers)</td><td>$199.99</td><td>Three weekly tiers observed</td></tr>\n    <tr><td>ShortMax</td><td><strong>$19.99</strong></td><td>$149.99</td><td>$0.41/day on annual</td></tr>\n    <tr><td>GoodShort</td><td><strong>$19.99</strong></td><td>$149.99</td><td>Identical to ShortMax</td></tr>\n    <tr><td>NetShort</td><td><strong>$24.99</strong></td><td>$99.99</td><td>Cheapest annual by far</td></tr>\n  </tbody>\n</table>\n\nBy that measure <strong>DramaBox wins outright at $12.99/week</strong>, roughly\n35% below the $19.99 cluster and well below NetShort's $24.99.\n\nBut notice how little this ranking tells you. NetShort has the most expensive\nweekly rate <em>and</em> by far the cheapest annual plan at $99.99 — about $1.92\na week if you keep it a year. Whether that is the cheapest option depends\nentirely on whether you would still be watching in March.\n\n<Callout kind=\"info\" title=\"The annual trap in reverse\">\n  Three apps priced their annual plans at exactly $149.99 and one at $199.99,\n  which works out to $2.86 and $3.85 per week. Buying a year to save money on\n  an app you will abandon in six weeks is the more expensive mistake, not the\n  cheaper one.\n</Callout>\n\n<h2 id=\"by-entry\">Cheapest to start</h2>\n\nThe first purchase is a different question. If you are going to buy coins rather\nthan subscribe, this is what the smallest pack cost:\n\n- <strong>DramaBox — $2.99</strong> for 300 coins\n- ReelShort — $4.99 for 500 coins (and this pack was only visible from inside a\n  locked episode, not on the store page)\n- GoodShort — $4.99 for 500\n- ShortMax — $4.99 for 500\n- StardustTV — $5.99 for 600\n- NetShort — coin packs were not displayed in-app at all\n\n<Screenshot\n  src=\"/screenshots/shortmax-store-plans.webp\"\n  alt=\"An in-app coin purchase screen showing a coin pack priced at 4.99 dollars among larger bundles\"\n  caption=\"A typical coin store — the entry pack sits at $4.99 while the large bundles look like the better deal per coin\"\n/>\n\nDramaBox is cheapest to start <em>and</em> cheapest by weekly renewal. That is\nthe one clean sweep in this whole comparison — the caveats are in\n<a href=\"/apps/dramabox\">our full DramaBox review</a>.\n\n<h2 id=\"by-episode\">Cheapest per episode</h2>\n\nThis is the measure that matters if you are paying per episode, and it is where\nthe ranking stops looking like a price list.\n\nPer-episode coin cost, worked out from the smallest available pack:\n\n<table class=\"data-table\">\n  <thead>\n    <tr><th>App</th><th>Coins per episode</th><th>Approx. cost</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>DramaBox</td><td>50</td><td><strong>≈ $0.50</strong></td></tr>\n    <tr><td>ShortMax</td><td>50</td><td>≈ $0.50</td></tr>\n    <tr><td>GoodShort</td><td>50</td><td>≈ $0.50</td></tr>\n    <tr><td>ReelShort</td><td>60</td><td>≈ $0.60</td></tr>\n    <tr><td>StardustTV</td><td>65</td><td><strong>≈ $0.65</strong></td></tr>\n    <tr><td>NetShort</td><td>98 N coins</td><td><strong>Most expensive</strong> — and it also required watching 2 ads per episode</td></tr>\n  </tbody>\n</table>\n\nNow the inversion: <strong>DramaBox's weekly renewal is the cheapest, and its\nper-episode coin cost is mid-table.</strong> If you buy coins rather than\nsubscribe, the app that looked most expensive on a subscription basis is not the\nmost expensive way to watch.\n\n<Screenshot\n  src=\"/screenshots/dramabox-store-plans.webp\"\n  alt=\"An in-app coin purchase screen showing a small coin pack and larger bundles with dollar prices\"\n  caption=\"DramaBox's coin store: a $2.99 entry pack, and the per-coin cost falls as the pack grows\"\n/>\n\n<Screenshot\n  src=\"/screenshots/netshort-store-plans.webp\"\n  alt=\"A subscription page showing a weekly renewal price with a promotional Google Pay button price\"\n  caption=\"NetShort's Top Up page: $15.99 on the plan, $14.39 on the Google Pay button — two prices for one subscription\"\n/>\n\n<Screenshot\n  src=\"/screenshots/reelshort-coin-packs.webp\"\n  alt=\"A coin pack list showing several bundle sizes with the smallest pack priced at 4.99 dollars\"\n  caption=\"ReelShort's packs: $4.99 for 500 coins, $49.99 for 7,500 — the same coins are a third cheaper in the large bundle\"\n/>\n\nThere is a further wrinkle in coin pricing that only shows up if you divide\nproperly. The small pack is always the worst value per coin. ReelShort's $4.99\nfor 500 works out at $0.0100 a coin, while its $49.99 for 7,500 works out at\n$0.0067 — <strong>the same coins are 33% cheaper when you buy more of them</strong>,\nwhich is the opposite of how these stores are laid out, with the small pack most\nprominent.\n\n<h2 id=\"by-free\">Cheapest once free episodes count</h2>\n\nFor most people the honest answer is that you will not pay for many episodes at\nall, because every one of these apps gives some away first.\n\nHow many episodes you got before the paywall, on the series each app showed us:\n\n<table class=\"data-table\">\n  <thead>\n    <tr><th>App</th><th>Free episodes</th><th>Note</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>StardustTV</td><td><strong>10</strong></td><td>Widest opening we measured</td></tr>\n    <tr><td>NetShort</td><td>9</td><td>But 2 ads per episode, and 98 coins to buy</td></tr>\n    <tr><td>GoodShort</td><td>7</td><td>Only 5 ad-unlocks a day, and ads failed for us</td></tr>\n    <tr><td>ShortMax</td><td>6</td><td></td></tr>\n    <tr><td>DramaBox</td><td>~11</td><td>Charging by episode 12 on the series we opened</td></tr>\n    <tr><td>ReelShort</td><td><strong>10 or 16</strong></td><td>Varies by series — 10 on a 54-episode show, 16 on an 81-episode one</td></tr>\n  </tbody>\n</table>\n\nTwo things fall out of this. First, <strong>the free allowance varies within the\nsame app</strong> — ReelShort gave sixteen free episodes on one series and ten\non another, so any app-level claim about free episodes is unreliable. Second,\nReelShort's number looked the best on paper and was beaten in practice by\nStardustTV, because ReelShort's ads run ten per day while GoodShort's run five.\nAnd free episodes are only half the free allowance — the daily coin tasks are\nthe other half, and they vary just as much between apps\n(<a href=\"/guides/dramabox-free-coins\">DramaBox</a>,\n<a href=\"/guides/how-to-get-free-coins-on-reelshort\">ReelShort</a>).\n\n<Screenshot\n  src=\"/screenshots/stardusttv-episode-free-boundary.webp\"\n  alt=\"An episode list showing ten unlocked episodes followed by locked episodes\"\n  caption=\"StardustTV's free run: episodes 1 to 10 unlocked, episode 11 at 65 coins — the widest opening of the six apps\"\n/>\n\n<h2 id=\"verdict\">The verdict, by viewing habit</h2>\n\nThere is no single cheapest app, but the decision collapses to four habits:\n\n<ol class=\"steps\">\n  <li>\n    <strong>If you will watch under about five series a year</strong>, do not\n    subscribe at all. Free episodes plus ad-unlocks cover a casual viewer in\n    every one of these apps, and you pay nothing. NetShort and GoodShort are the\n    two to avoid on this route — NetShort demands two ads per episode, and\n    GoodShort's ad-unlocks failed outright when we tested them.\n  </li>\n  <li>\n    <strong>If you binge regularly and buy coins</strong>, target the mid-priced\n    per-episode apps: DramaBox, ShortMax and GoodShort at 50 coins. NetShort is\n    the expensive one on this route despite its low annual price.\n  </li>\n  <li>\n    <strong>If you subscribe weekly</strong>, DramaBox at $12.99/week is the\n    cheapest renewal we found, and it is also the cheapest entry pack at $2.99.\n  </li>\n  <li>\n    <strong>If you are confident you will still be watching in a year</strong>,\n    NetShort's $99.99 annual is the only one that clearly beats its own weekly\n    rate. Everyone else should skip annual plans.\n  </li>\n</ol>\n\n<Callout kind=\"warning\" title=\"Before you commit to any of these\">\n  These are the numbers your screen will probably not show. Introductory prices\n  rotate by day and by account, and two of the apps price by your network exit\n  country. Open the app, find your own numbers, and check them against\n  <a href=\"/guides/why-short-drama-app-prices-differ\">why published prices disagree</a>\n  before you decide.\n</Callout>\n\n<h2 id=\"limits\">Limits of this comparison</h2>\n\nA caveat that applies to every number below: this is a ranking, and rankings\ncarry their own failure mode. **The limitation of this comparison is that it\ndoes not work for anyone whose watching habits differ from the pattern we\nmeasured** — and we do not know your pattern. The further constraints:\n\n- **Six apps, one platform, October 2026.** All testing was on Android with a\n  US Google Play account. iOS billing differs, and we have not measured these\n  apps on iOS.\n- **Renewal rates move too.** We recorded DramaBox's weekly renewal at $12.99\n  on one day. The introductory prices are documented as rotating; the renewal\n  rates are simply what we were quoted, and we have less data on how stable they\n  are.\n- **Free episode counts are per series, not per app.** Two of the six apps gave\n  different free lengths on different shows, so treat any app-level free\n  episode claim as unreliable.\n- **Three of the apps priced annual at exactly $149.99.** That similarity is\n  worth watching — it may indicate shared ownership or a common pricing agency,\n  but we did not investigate and cannot say.\n- **NetShort's coin packs were never displayed in-app.** We could not price its\n  per-episode cost from a pack, so its position in the per-episode table is\n  based on the coin requirement alone and is the least certain row in this\n  article.\n- **This is not an endorsement.** All six are affiliate-linked on this site.\n  The rankings come from measured prices, and we name the trade-offs rather\n  than picking a favourite.\n\n<h2 id=\"when-fails\">When this ranking does not apply to you</h2>\n\n- **If you are outside the US.** These are US-route prices on US accounts. Your\n  local pricing may be lower, and at least two apps price by exit country.\n- **If you have found a better offer.** These apps rotate introductory pricing\n  aggressively. A $1.99 first week was genuinely available to us in October —\n  if you see something better, that beats anything written here.\n- **If your interest is casual and short.** The most common outcome for a\n  casual viewer is paying nothing at all, which no ranking in this article is\n  built around.\n- **If you care about the catalogue rather than the price.** Cost per episode\n  says nothing about whether a show is worth finishing, and app quality varies\n  far more than price does.\n- **If you are reading this months from now.** Every figure here will have\n  moved. The structure will not.\n\n<AffiliateCTA\n  appName=\"DramaBox\"\n  href=\"https://r.reelsgo.tv/uR3A7JBLdipd\"\n  sub=\"Cheapest weekly renewal and cheapest entry pack in our testing — but check your own screen first\"\n  buttonLabel=\"Open DramaBox\"\n/>","src/content/guides/cheapest-short-drama-app.mdx","72559dcba95b3dd2",{id:180,data:531,body:584,filePath:585,digest:586,deferredRender:74},{title:532,description:533,app:16,targetKeyword:534,intent:18,shortAnswer:535,publishedOn:541,updatedOn:139,priceVerifiedOn:541,toc:542,faqs:567,relatedGuides:583},"ReelShort Coins vs VIP: Which One Is Cheaper for How Many Episodes","Coins, VIP or ads? We did the arithmetic on all three unlock routes and found the break-even point is about 5 episodes — plus the coin math nobody explains.","reelshort coins vs vip",[536,537,538,539,540],"The break-even point is roughly <strong>five episodes</strong>. Under that, coins are cheaper. Over it, VIP wins — and the free daily coins cover part of the coin route for free.","One ReelShort episode costs <strong>60 coins</strong>, and the smallest coin pack is $4.99 for 500, so <strong>a single episode is about $0.60</strong>. The large $49.99 pack drops that to $0.40.","VIP renewal started at <strong>$5.99–$19.99 per week</strong> depending on the tier we saw. That only beats coins if you will unlock <strong>more than about 8–10 episodes</strong> in that week.","Coins are usually the better first choice because they <strong>do not auto-renew</strong>. VIP charges you again whether or not you open the app.","The free route is more generous than most people use: <strong>50 coins on first login</strong>, up to 200 on day 7 of daily check-ins, and <strong>10 ad-unlocks a day</strong>.","2026-10-13",[543,546,549,552,555,558,561,564,565],{id:544,label:545},"three-routes","Three ways to unlock one episode",{id:547,label:548},"coin-math","What one episode actually costs",{id:550,label:551},"vip-math","What VIP actually costs",{id:553,label:554},"breakeven","Where the break-even point is",{id:556,label:557},"free-first","Do this before paying anything",{id:559,label:560},"numbers","The three numbers that decide this",{id:562,label:563},"decision","Which to pick",{id:457,label:509},{id:511,label:566},"When this calculation does not apply",[568,571,574,577,580],{q:569,a:570},"Is it cheaper to buy coins or subscribe to VIP on ReelShort?","Below roughly five episodes, coins. Above that, VIP. A single ReelShort episode costs 60 coins, which is about $0.60 at the smallest pack or $0.40 in the largest. VIP renewal ran $5.99 to $19.99 per week depending on the tier, so it only works out cheaper if you unlock more than about 8 to 10 episodes that week. Coins also do not auto-renew, so they are the lower-risk choice for a casual viewer.",{q:572,a:573},"How many coins is one episode on ReelShort?","60 coins. The paywall states the price directly, so it is not a hidden number. Be aware that DramaBox and several other apps charge 50 coins per episode while NetShort charges 98, so a coin balance is not portable between apps.",{q:575,a:576},"Is it worth buying the big coin pack?","Only if you finish the series. Per-coin cost falls as the pack grows: $4.99 for 500 coins works out at about $0.0100 a coin, while $49.99 for 7,500 works out at about $0.0067, roughly a third cheaper. The small packs sit at the top of the store page precisely because they are the worst value.",{q:578,a:579},"Can I watch ReelShort without paying at all?","More often than the apps suggest. We recorded 50 coins for first login, a seven-day check-in sequence reaching 200 coins on day 7, watch-time tasks worth up to 340 coins a day, and 10 ad-unlocks per day. The free episodes before the paywall ranged from 10 to 16 depending on the series. That is often enough for a casual viewer to never pay.",{q:581,a:582},"What happens if I subscribe and stop watching?","The renewal charge lands 24 hours before each period ends, at the renewal rate rather than the intro rate, which can be up to three times higher. Coins do not carry that risk because they do not renew. If you are unsure, coins are the safer route.",[67,69,227,123],"import Callout from '../../components/Callout.astro';\nimport Screenshot from '../../components/Screenshot.astro';\nimport AffiliateCTA from '../../components/AffiliateCTA.astro';\n\n<h2 id=\"three-routes\">Three ways to unlock one episode</h2>\n\nWhen an episode locks, ReelShort offers three buttons, and they cost very\ndifferent amounts:\n\n- <strong>60 coins</strong> — priced directly on the paywall\n- <strong>Watch an advert</strong> — limited to 10 per day\n- <strong>Go VIP</strong> — unlocks everything, auto-renewing\n\nMost people try the first two, then subscribe without checking the arithmetic.\nHere is the arithmetic.\n\nEverything below comes from one Android account in October 2026, US Google\nPlay billing, with screenshots at each step. Prices rotate, so treat these as\ndated measurements.\n\n<h2 id=\"coin-math\">What one episode actually costs</h2>\n\nOne episode is <strong>60 coins</strong>. The coin packs we recorded:\n\n<table class=\"data-table\">\n  <thead>\n    <tr><th>Pack</th><th>Price</th><th>Coins received</th><th>Cost per coin</th><th>Per episode</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>Starter</td><td>$4.99</td><td>500</td><td>$0.0100</td><td><strong>$0.60</strong></td></tr>\n    <tr><td>Small</td><td>$9.99</td><td>1,100 (1,000 + 100)</td><td>$0.0091</td><td>$0.55</td></tr>\n    <tr><td>Medium</td><td>$19.99</td><td>2,400 (2,000 + 400)</td><td>$0.0083</td><td>$0.50</td></tr>\n    <tr><td>Large</td><td>$29.99</td><td>3,900 (3,000 + 900)</td><td>$0.0077</td><td>$0.46</td></tr>\n    <tr><td>Bulk</td><td>$49.99</td><td>7,500 (5,000 + 2,500)</td><td>$0.0067</td><td><strong>$0.40</strong></td></tr>\n  </tbody>\n</table>\n\nTwo things this table exposes that the store screen does not:\n\n<Callout kind=\"info\" title=\"The small pack is a trap\">\n  The $4.99 pack costs <strong>50% more per coin</strong> than the $49.99 pack —\n  $0.0100 against $0.0067. Yet the small pack is what you see first when you open\n  a locked episode. You pay 49% more per episode by buying the pack that is\n  easiest to find.\n</Callout>\n\n<Callout kind=\"warning\" title=\"And the small packs are hidden\">\n  The store page does not show the $4.99 tier at all. It appears only when you\n  open a locked episode and choose to top up from there. A user who buys from the\n  store page without checking pays the worst rate available.\n</Callout>\n\n<Screenshot\n  src=\"/screenshots/reelshort-coin-packs.webp\"\n  alt=\"An in-app coin pack list showing the smallest pack at 4.99 dollars and larger bundles going up to 49.99 dollars\"\n  caption=\"The pack list reached from a locked episode — the $4.99 tier is here but not on the main store page\"\n/>\n\n<h2 id=\"vip-math\">What VIP actually costs</h2>\n\nThis is where most comparisons go wrong, because they use the intro price. The\nweekly VIP rates we recorded <strong>after the first discounted week</strong>:\n\n| Tier | Renewal price |\n|---|---|\n| Weekly VIP (with Ads) | $5.99/week |\n| Weekly VIP (Ad-Free) | $11.99/week |\n| Weekly VIP (Standard) | $19.99/week |\n\nAt $0.60 per episode on coins, a week of VIP works out as:\n\n- **$5.99 plan** breaks even at about **10 episodes** a week\n- **$11.99 plan** at about **20 episodes** a week\n- **$19.99 plan** at about **33 episodes** a week\n\n<h2 id=\"breakeven\">Where the break-even point is</h2>\n\nPulling it together, and using the middle case ($11.99/week against coins at\n$0.55 each):\n\n- **1–5 episodes**: coins, clearly. The subscription costs more before you have\n  watched anything.\n- **5–8 episodes**: close enough that the deciding factor becomes risk, not\n  price — coins do not auto-renew.\n- **8+ episodes in a week**: VIP, clearly.\n\n<Callout kind=\"info\" title=\"The honest framing\">\n  The break-even point is not a fixed number, because the VIP rate you get is\n  whatever intro offer your account lands on, and the same account saw 67% off\n  one day and 21% off the next. What is stable is the structure: <strong>coins are\n  cheaper for casual viewing, VIP is cheaper for bingeing</strong>.\n</Callout>\n\n<h2 id=\"free-first\">Do this before paying anything</h2>\n\nBefore spending anything, exhaust what is free. On the account we tested:\n\n<table class=\"data-table\">\n  <thead>\n    <tr><th>Source</th><th>Amount</th><th>Notes</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>First login bonus</td><td>50 coins</td><td>One-time, new accounts</td></tr>\n    <tr><td>Daily check-in, day 7</td><td>200 coins</td><td>Full week totals about 375</td></tr>\n    <tr><td>Watch-time tasks</td><td>Up to 340 coins/day</td><td>2, 5, 10, 20 and 30 minute tiers</td></tr>\n    <tr><td>Ad-unlocks</td><td><strong>10 episodes/day</strong></td><td>Free, costs only your time</td></tr>\n    <tr><td>Free episodes</td><td>10 to 16</td><td>Varies by series, not disclosed in advance</td></tr>\n  </tbody>\n</table>\n\n<Screenshot\n  src=\"/screenshots/reelshort-checkin-calendar.webp\"\n  alt=\"A seven day daily check-in reward calendar showing coin amounts for each day with day seven awarding the most\"\n  caption=\"The seven-day check-in sequence — day 7 alone pays 200 coins, more than three episodes\"\n/>\n\nTen ad-unlocks a day is the number most people leave on the table. At 60 coins\nper episode, the free daily check-in plus those ads covers a surprising amount of\na casual viewing habit — and the adverts are skippable, so the real cost is time.\n\n<h2 id=\"numbers\">The three numbers that decide this</h2>\n\nEverything else follows from these. They are the only figures worth memorising\nbefore opening the app:\n\n<table class=\"data-table\">\n  <thead>\n    <tr><th>Figure</th><th>Value</th><th>What it means for you</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>Coins per episode</td><td><strong>60</strong></td><td>Shown on the paywall, not hidden</td></tr>\n    <tr><td>Best per-coin price</td><td><strong>$0.0067</strong></td><td>Only reachable in the $49.99 pack</td></tr>\n    <tr><td>Ad-unlock cap</td><td><strong>10/day</strong></td><td>Equals 600 coins free per day</td></tr>\n  </tbody>\n</table>\n\n<Screenshot\n  src=\"/screenshots/reelshort-ad-unlock-prompt.webp\"\n  alt=\"An ad-unlock prompt showing a daily counter starting at zero of ten episodes unlocked by watching adverts\"\n  caption=\"The ad-unlock prompt with its daily counter — ten per day is 600 coins a week, or ten episodes watched for free\"\n/>\n\n<Screenshot\n  src=\"/screenshots/reelshort-vip-plans.webp\"\n  alt=\"A subscription screen showing a discounted weekly VIP plan with a 24 hour countdown timer\"\n  caption=\"The weekly VIP plans — the countdown is on the discounted rate, but the renewal rate is a different and higher number\"\n/>\n\n<Screenshot\n  src=\"/screenshots/reelshort-purchase-confirmation.webp\"\n  alt=\"A Google Play subscription confirmation screen showing the renewal date, renewal price and tax notice\"\n  caption=\"The confirmation that decides what you actually pay: renewal date, renewal rate, tax, and where cancelling really happens\"\n/>\n\n<h2 id=\"decision\">Which to pick</h2>\n\n<ol class=\"steps\">\n  <li>\n    <strong>Watch the free episodes first.</strong> Ten to sixteen before the\n    paywall, and the free allowance varies by series, so check the specific show.\n  </li>\n  <li>\n    <strong>Run the daily loop for a week.</strong> Check-ins plus watch-time\n    tasks plus ten ad-unlocks produces more coins than most casual viewers use.\n    Do this before deciding anything.\n  </li>\n  <li>\n    <strong>Under about eight episodes a week: buy coins, and buy a large pack.</strong>\n    Not the $4.99 tier you will see first — work out which pack size matches\n    your remaining episode count.\n  </li>\n  <li>\n    <strong>Bingeing weekly: VIP is cheaper</strong>, but only once you are past\n    roughly eight episodes in that week. If your bingeing is intermittent, coins\n    still win because they do not charge you for the weeks you do not watch.\n  </li>\n  <li>\n    <strong>Never let a subscription run untouched</strong> — the renewal lands 24\n    hours before the period ends at the renewal rate, not the intro rate.\n  </li>\n</ol>\n\n<h2 id=\"limits\">Limits of this comparison</h2>\n\nA caveat that applies to every number here: **this comparison assumes you watch\non Android with US Google Play billing, and if you do not, it does not work for\nyou.** It does not hold on iOS, where Apple's billing and pricing differ, and it\ndoes not hold in other regions — two of the apps we tested price by the country\nyour traffic exits from. The further limits:\n\n- **One account, one region, October 2026.** The renewal rates we recorded came\n  from that week's intro offer. We have less data on how stable renewal rates are\n  than on how stable the coin prices are.\n- **Watch-time tasks and ad limits are the kind of thing that changes without\n  notice.** We confirmed 10 ad-unlocks twice, on two separate days, but that cap\n  is set by the app and can be altered at any time.\n- **We did not test whether ad-unlocks can be farmed.** The daily cap makes\n  repeated attempts pointless, but we only observed the limit, we did not try to\n  push against it.\n- **The advert quality is part of the real cost.** On our account the ads served\n  were a fake insurance offer and a TikTok install prompt. If that matters to\n  you, the \"free\" route is not really free.\n- **This is not an endorsement.** ReelShort is affiliate-linked on this site, and\n  the recommendation to start with coins and exhaust the free route is the one\n  that costs us the least commission.\n\n<h2 id=\"when-fails\">When this calculation does not apply</h2>\n\n- **If you are on iOS.** Apple's billing is a different system. Our iOS knowledge\n  in this project comes from Apple's documentation, not from testing.\n- **If you are outside the US.** These are US-route prices. Your local pricing may\n  be lower, and ReelShort's prices moved with our exit country in testing.\n- **If you only want one series and it has 12 episodes left.** Then the maths is\n  trivial: multiply by 60 coins and buy the pack that covers it. No subscription\n  logic needed.\n- **If you are reading this months from now.** The structure will still hold —\n  intro below renewal, cheaper per coin in bigger packs, free episodes varying by\n  series — but every specific number will have moved.\n- **If you care about catalogue size more than cost.** VIP unlocks 16,000-plus\n  titles on some apps; a coin balance buys you one series. That is not a cost\n  comparison.\n\n<AffiliateCTA\n  appName=\"ReelShort\"\n  href=\"https://r.reelsgo.tv/1vwtyh4hj9R3\"\n  sub=\"Free to download — check what your own screen actually charges before you buy anything\"\n  buttonLabel=\"Open ReelShort\"\n/>","src/content/guides/reelshort-coins-vs-vip.mdx","8d391f6a32d496f9",{id:179,data:588,body:633,filePath:634,digest:635,deferredRender:74},{title:589,description:590,app:334,targetKeyword:591,intent:236,shortAnswer:592,publishedOn:598,updatedOn:599,priceVerifiedOn:598,toc:600,faqs:620,relatedGuides:632},"Which Short Drama App Gives You the Most Free Episodes","We counted free episodes on six short drama apps. The widest opening was 10 episodes, but free daily coins and ad unlocks matter more than that number.","short drama app with most free episodes",[593,594,595,596,597],"<strong>StardustTV gave 10 episodes free — the widest opening we measured.</strong> NetShort gave 9 on the same series; ReelShort matched 10 on one series but gave 16 on another.","The headline number matters much less than people assume. <strong>Ad-unlocks add up to a further 5 to 10 episodes a day</strong>, which is more than any app gives away up front.","<strong>GoodShort and StardustTV are the stingiest with ads</strong> — 5 ad-unlocks a day. ReelShort and ShortMax give 10.","The real differentiator is <strong>free coins</strong>: ReelShort pays 200 coins for reaching check-in day 7, which covers 3 episodes on its own.","Every figure here is from one Android account in October 2026, and <strong>the free allowance varies by series</strong> — two apps gave different numbers on different shows.","2026-10-14","2026-10-17",[601,604,607,610,613,615,617,618],{id:602,label:603},"counted","What we actually counted",{id:605,label:606},"table","The free episode count on six apps",{id:608,label:609},"varies","Why the same app gives different numbers",{id:611,label:612},"ads","Ad-unlocks add up to more than the opening",{id:302,label:614},"Free coins are the real allowance",{id:506,label:616},"Which app is most generous",{id:457,label:509},{id:511,label:619},"When this comparison does not apply",[621,623,626,629],{q:518,a:622},"StardustTV gave ten free episodes in our testing and NetShort nine. ReelShort also gave ten on one series but sixteen on another, so its free allowance depends on the show. ShortMax gave six and GoodShort seven, the narrowest openings of the six. Treat these as measured samples rather than fixed rules, because the count varies by series.",{q:624,a:625},"Do ads actually let you watch more for free?","More than the opening suggests. ReelShort and ShortMax each allow ten ad-unlocks a day, which is more episodes than some apps give away before the paywall. GoodShort and StardustTV allow only five. NetShort asks for two ads per episode, so five episodes costs ten ad views. We found the advert quality varied, including a fake insurance offer and a TikTok install prompt, so the real cost is your time and your patience.",{q:627,a:628},"Are free coins worth chasing in these apps?","More than the free episode count, yes. ReelShort pays 50 coins on first login, a seven-day check-in sequence reaching 200 coins on day 7 and about 375 in total, and up to 340 coins a day from watch-time tasks. At 60 coins an episode, the day-7 check-in alone covers more than three episodes. DramaBox gave a seven-day sequence worth about 165 coins in total.",{q:630,a:631},"Can I watch a whole series without paying anything?","A short one, yes, if you use the ad unlocks and daily coins together. A long one, no. A 50-episode series with 10 free plus 5 ad-unlocks a day still needs coins or a subscription once the unlocks run out, and ad-unlock limits reset daily rather than accumulating.",[69,481,180,227],"import Callout from '../../components/Callout.astro';\nimport Screenshot from '../../components/Screenshot.astro';\nimport AffiliateCTA from '../../components/AffiliateCTA.astro';\n\n<h2 id=\"counted\">What we actually counted</h2>\n\n\"Most free episodes\" sounds like a simple number, and most comparisons get it\nwrong in one of two ways. They quote the marketing number rather than what the\napp actually showed us, or they treat the figure as fixed when it moves by\nseries.\n\nSo here is what we did. On one Android account, with US Google Play billing, in\nOctober 2026, we opened a series on each of six apps, recorded the exact episode\nwhere the lock first appeared, and recorded the ad-unlock counter next to it.\n\n<table class=\"data-table\">\n  <thead>\n    <tr><th>App</th><th>Series tested</th><th>Episodes</th><th>Free boundary</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>StardustTV</td><td>The God-King Returns: Too Late to Beg</td><td>50</td><td><strong>EP.1–10 free</strong></td></tr>\n    <tr><td>NetShort</td><td>The God-King Returns: Too Late to Beg</td><td>50</td><td><strong>EP.1–9 free</strong></td></tr>\n    <tr><td>ReelShort</td><td>two different series</td><td>54 / 81</td><td><strong>10 free / 16 free</strong></td></tr>\n    <tr><td>DramaBox</td><td>Condemn Me, My President</td><td>43</td><td><strong>EP.1–11 free</strong></td></tr>\n    <tr><td>GoodShort</td><td>—</td><td>—</td><td>7 free</td></tr>\n    <tr><td>ShortMax</td><td>—</td><td>—</td><td>6 free</td></tr>\n  </tbody>\n</table>\n\n<h2 id=\"table\">The free episode count on six apps</h2>\n\nTaking the opening episode count alone, ranked:\n\n<ol class=\"steps\">\n  <li><strong>DramaBox — 11 episodes free</strong> before the paywall</li>\n  <li><strong>StardustTV — 10 episodes</strong></li>\n  <li><strong>NetShort — 9 episodes</strong></li>\n  <li><strong>ReelShort — 10 or 16</strong>, depending on the series</li>\n  <li><strong>GoodShort — 7 episodes</strong></li>\n  <li><strong>ShortMax — 6 episodes</strong>, the narrowest opening</li>\n</ol>\n\n<Screenshot\n  src=\"/screenshots/stardusttv-episode-free-boundary.webp\"\n  alt=\"An episode list showing ten episodes with open lock icons followed by episode 11 marked with a price of 65 coins\"\n  caption=\"StardustTV: episodes 1 to 10 open, episode 11 locked at 65 coins — the widest opening of the six\"\n/>\n\n<Callout kind=\"info\" title=\"The gap between best and worst is small\">\n  Six episodes versus eleven is a difference of five episodes. At roughly $0.50 to\n  $0.65 per episode, that gap is about **three dollars** across a whole series. The\n  free episode count is a weak signal on its own, which is why the next two\n  sections matter more.\n</Callout>\n\n<h2 id=\"varies\">Why the same app gives different numbers</h2>\n\nThe most useful thing we recorded was not a number, it was an inconsistency.\n\n**ReelShort gave us 10 free episodes on a 54-episode series and 16 on an\n81-episode series.** Same app, same day, same account. Longer series gave more\nfree episodes — which means the opening scales with total length, roughly a\nfifth of the way in.\n\nThat has a practical consequence: **any app-level claim about free episodes is\nunreliable.** If you are deciding where to start, check the specific series\nrather than trusting a review that says \"ten free episodes\", because you might\nget sixteen.\n\n<Screenshot\n  src=\"/screenshots/reelshort-episode-free-boundary.webp\"\n  alt=\"A ReelShort episode list showing unlocked episodes before the first locked episode marked with a price of 60 coins\"\n  caption=\"ReelShort's paywall: the price per episode is stated on the screen, and the free run ahead of it varies by series\"\n/>\n\n<h2 id=\"ads\">Ad-unlocks add up to more than the opening</h2>\n\nThis is where the \"free episode count\" question gets reframed. Every app lets\nyou keep going by watching adverts, and the daily limits are large relative to\nthe opening:\n\n<table class=\"data-table\">\n  <thead>\n    <tr><th>App</th><th>Ad-unlocks per day</th><th>Ad views needed per episode</th><th>Episodes/day from ads</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>ReelShort</td><td><strong>10</strong></td><td>1</td><td><strong>10</strong></td></tr>\n    <tr><td>ShortMax</td><td><strong>10</strong></td><td>1</td><td><strong>10</strong></td></tr>\n    <tr><td>DramaBox</td><td>8</td><td>1</td><td>8</td></tr>\n    <tr><td>GoodShort</td><td>5</td><td>1</td><td>5</td></tr>\n    <tr><td>StardustTV</td><td>5</td><td>1</td><td>5</td></tr>\n    <tr><td>NetShort</td><td>5</td><td><strong>2</strong></td><td>5 (10 ad views)</td></tr>\n  </tbody>\n</table>\n\n<Callout kind=\"warning\" title=\"Two apps price an episode in ads, not unlocks\">\n  NetShort asks for <strong>two adverts per episode</strong>, and its ad ran a\n  <strong>3-minute countdown</strong> — the longest forced advert we saw on any of\n  the six. Five free episodes therefore cost ten ad views. The daily caps also\n  <strong>reset rather than accumulate</strong>, so unused unlocks do not roll over.\n</Callout>\n\nNetlify aside: we also saw ReelShort serve a fake insurance advert on one day\nand a TikTok install prompt the next. The unlock count is real; the adverts\nthemselves are worth tolerating carefully.\n\n<h2 id=\"coins\">Free coins are the real allowance</h2>\n\nThe free coin systems are more generous than the free episode counts, and\nalmost nobody uses them properly.\n\nReelShort, measured across a week:\n\n| Source | Coins |\n|---|---|\n| First login bonus | 50 |\n| Daily check-in, day 7 alone | <strong>200</strong> |\n| Full seven-day check-in sequence | ~375 |\n| Watch-time tasks (2/5/10/20/30 min tiers) | up to 340/day |\n\nAt 60 coins an episode, the day-7 check-in **alone pays for more than three\nepisodes**. Run the loop for a week and you have roughly 1,000 coins — 16\nepisodes — before buying anything.\n\nDramaBox runs a shorter seven-day sequence — about 165 coins in total — against\na 50-coin episode cost. Under half the coins at a lower per-episode price: the\nReelShort check-in still covers roughly twice as many episodes. Where DramaBox\ndoes beat ReelShort is the welcome: its one-time sign-up tasks pay 450 coins\nagainst 50. See\n<a href=\"/guides/dramabox-free-coins\">its full free-coin breakdown</a>.\n\n<Screenshot\n  src=\"/screenshots/reelshort-checkin-calendar.webp\"\n  alt=\"A seven day daily check-in reward calendar with coin amounts increasing towards day seven\"\n  caption=\"ReelShort's seven-day check-in: day 7 alone pays 200 coins, which is over three episodes\"\n/>\n\n<h2 id=\"verdict\">Which app is most generous</h2>\n\nIf the question is strictly \"which app lets me watch the most for free\", the\nanswer changes depending on what you count:\n\n<ol class=\"steps\">\n  <li>\n    <strong>Most free episodes before the paywall: DramaBox (11)</strong>, then\n    StardustTV (10).\n  </li>\n  <li>\n    <strong>Most free episodes per day from ads: ReelShort and ShortMax (10 each)</strong>,\n    with one advert each. NetShort needs two adverts per episode, which makes it\n    the most expensive free route in practice.\n  </li>\n  <li>\n    <strong>Most free coins: ReelShort</strong>, by a wide margin — 200 coins for\n    check-in day 7, plus up to 340 a day from watch-time tasks.\n  </li>\n  <li>\n    <strong>Worst overall for free viewing: ShortMax and GoodShort.</strong> Six\n    and seven free episodes, and only five ad-unlocks a day between them. If you\n    want to avoid paying, they are the two to skip.\n  </li>\n  <li>\n    <strong>Best answer if you only open one app occasionally: any of them, for\n    ten days.</strong> Between the opening episodes and the daily ad unlocks, a\n    casual viewer rarely needs to pay at all — which is why the cheapest-app\n    question and this one have different answers.\n  </li>\n</ol>\n\n<Callout kind=\"info\" title=\"The honest summary\">\n  Free episode counts differ by five across six apps — worth about three dollars.\n  Free coins and ad unlocks differ far more, and those are the numbers that\n  decide whether a casual viewer ever pays. **Optimise for coins, not for the\n  opening episode count.**\n</Callout>\n\n<h2 id=\"limits\">Limits of this comparison</h2>\n\nA caveat that applies to every number here: **this comparison assumes you are\ncounting free episodes on a specific series on Android with US Google Play\nbilling, and if you are doing anything else the numbers will not transfer to\nyou.** The free allowance is not a property of the app — it is a property of the\napp on a given series. The further limits:\n\n- **One account, one region, October 2026.** All testing was on Android with US\n  Google Play billing. We have not measured iOS, and at least two of the apps\n  price by the country your traffic exits from.\n- **The free episode count is per series, not per app.** ReelShort gave us 10 on\n  one series and 16 on another, so a second session could produce a different\n  table entirely.\n- **We tested one series per app for most of them.** Only ReelShort was tested on\n  two series, and that is precisely where the inconsistency showed up — so our\n  numbers for the other five are single samples.\n- **Ad-unlock caps can change without notice.** They are set by the app, and we\n  confirmed ReelShort's 10/day twice on two separate days rather than assuming.\n- **We did not test whether ad-unlocks can be farmed or reset.** The daily caps\n  make repeated attempts pointless, but we only observed the limit.\n- **The advert quality is part of the real cost.** One ReelShort ad was a fake\n  insurance offer; NetShort forced a 3-minute countdown. If that matters to you,\n  the \"free\" route is not free.\n- **This is not an endorsement.** All six are affiliate-linked on this site. The\n  recommendation to run the daily coin loop before spending anything is the one\n  that earns us the least.\n\n<h2 id=\"when-fails\">When this comparison does not apply</h2>\n\nPut plainly: this ranking <strong>does not work</strong> as a general rule, because\nthe number it is built on moves per series.\n\n- **If you are deciding where to watch a specific series.** Free counts move by\n  series and by length. Open the show, count the locks, and decide from that.\n- **If you are outside the US.** These are US-route observations on a US account.\n- **If you are on iOS.** Different billing platform, and we have not measured it.\n- **If you want to finish a long series.** None of these figures gets you past\n  about 20 episodes for free; past that you are buying coins or subscribing.\n- **If you are reading this months from now.** The structure will likely hold —\n  an opening allowance, a daily ad cap that resets, and a coin economy — but the\n  specific numbers will have moved.\n- **If you care about catalogue size rather than cost.** Free episodes are a\n  sample. A 10-episode free opening on a 500-episode library is a different\n  proposition from the same opening on a 40-episode one.\n\n<AffiliateCTA\n  appName=\"ReelShort\"\n  href=\"https://r.reelsgo.tv/1vwtyh4hj9R3\"\n  sub=\"Best on free coins — check what your own screen actually offers before you buy anything\"\n  buttonLabel=\"Open ReelShort\"\n/>","src/content/guides/short-drama-app-most-free-episodes.mdx","7842ba492e9308bc",{id:275,data:637,body:682,filePath:683,digest:684,deferredRender:74},{title:638,description:639,app:283,targetKeyword:640,intent:18,shortAnswer:641,publishedOn:598,updatedOn:598,priceVerifiedOn:598,toc:647,faqs:669,relatedGuides:681},"Is DramaBox Legit? What We Checked Before Recommending It","We checked DramaBox the same way we would check a bank: publisher identity, rating volume, download count, data policy, regional pricing and what the complaints are.","is dramabox legit",[642,643,644,645,646],"Yes, DramaBox is a real, operating app — <strong>4.6 stars from 5.53 million Google Play reviews and 100M+ downloads</strong>, with a publisher that also runs ReelShort.","The company is <strong>ReelShort’s own operator</strong>, not a third party. That explains why the two apps feel similar and price alike.","Two things worth knowing before you subscribe: it <strong>prices by your network exit country</strong>, and the <strong>annual plan works out to $2.31/week</strong> against a $12.99/week renewal.","The most legitimate complaint pattern we found is not about the app being fake — it is about <strong>the free allowance shrinking on some series</strong> and the weekly renewal being higher than the first week.","As always: this is an affiliate-linked app, and the checks below are what we verified ourselves, not a promise about your experience.",[648,649,652,655,657,660,662,665,667],{id:506,label:91},{id:650,label:651},"store-check","The store listing check",{id:653,label:654},"publisher","Who is behind it",{id:308,label:656},"It prices by your exit country",{id:658,label:659},"pricing","What you actually pay",{id:399,label:661},"What the complaints are actually about",{id:663,label:664},"checklist","The checklist we used",{id:457,label:666},"Limits of this assessment",{id:511,label:668},"When this verdict does not apply",[670,673,676,679],{q:671,a:672},"Is DramaBox a safe app?","It is a real, operating app rather than a throwaway. The Google Play listing shows 4.6 stars from 5.53 million reviews and over 100 million downloads, and it publishes a data safety section. That is a large enough public footprint that the safety question is not really about fraud. We could not verify the app outside Google Play, so we only checked it in the Play Store version.",{q:674,a:675},"Is DramaBox owned by the same company as ReelShort?","Yes. The DramaBox listing names ReelShort as its operator, which is why the two apps share a subscription pattern, a catalogue style and a pricing structure that rotates discounts the same way. If you already know how ReelShort behaves, DramaBox will feel familiar. If you dislike one of those traits, you are unlikely to find them fixed in the other.",{q:677,a:678},"Why do DramaBox prices change when I travel?","Because it prices by the country your network traffic exits from, not by your account. The app itself states that prices are displayed in USD and tells you to restart to refresh localized pricing. On the same device and the same account we saw Japanese yen on a Japanese exit and US dollars on a US exit on the same day. The pack prices were not the same either.",{q:317,a:680},"It depends on whether you would still be watching in a year. The annual plan is $119.99, advertised as $2.31 a week, against a weekly renewal of $12.99. That is a large difference, but buying twelve months to save money on an app you abandon in six weeks is the more expensive mistake.",[177,481,124,123,227],"import Callout from '../../components/Callout.astro';\nimport Screenshot from '../../components/Screenshot.astro';\nimport AffiliateCTA from '../../components/AffiliateCTA.astro';\n\n<h2 id=\"verdict\">The short answer</h2>\n\nDramaBox is legitimate. It is a real app from a real operating company, with a\npublic footprint large enough that the safety question is not really about\nfraud.\n\nBut \"legit\" is not the same as \"good deal\", and there are two behaviours here\nworth knowing about before you subscribe: **it prices by your network exit\ncountry**, and **the first week costs less than every week after it**.\n\nThis page is the checklist we ran, written down so you can run it yourself on\nany app in this category.\n\n<h2 id=\"store-check\">The store listing check</h2>\n\nThe fastest legitimacy test is the store listing, before you install anything.\nFor DramaBox on 8 October 2026:\n\n<table class=\"data-table\">\n  <thead>\n    <tr><th>Signal</th><th>What we found</th><th>Why it matters</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>Google Play rating</td><td><strong>4.6 / 5</strong></td><td>High enough that a mass complaint campaign would have moved it</td></tr>\n    <tr><td>Review count</td><td><strong>5.53 million</strong></td><td>Volume matters more than the average — 5.53M is not a small sample</td></tr>\n    <tr><td>Downloads</td><td><strong>100M+</strong></td><td>A large install base means bugs and complaints surface publicly</td></tr>\n    <tr><td>Contains ads</td><td>Yes, declared</td><td>Declared rather than hidden</td></tr>\n    <tr><td>Data safety section</td><td>Present</td><td>Required by Google; its absence would be a red flag</td></tr>\n  </tbody>\n</table>\n\n<Callout kind=\"info\" title=\"Review count is the number that carries the signal\">\nA 4.6 average over 500 reviews means very little. The same 4.6 over\n<strong>5.53 million</strong> means the app has been downloaded, used and rated by\nenough people that a systematically bad experience would show up in the\ndistribution. Volume is what makes the average trustworthy.\n</Callout>\n\n<h2 id=\"publisher\">Who is behind it</h2>\n\nThe DramaBox listing names **ReelShort as the operator**. This is the single most\nuseful fact on this page, because it explains almost everything you will notice:\n\n- Why the two apps feel like the same product with different artwork\n- Why both rotate introductory discounts by the day\n- Why both put a 24-hour countdown on the paywall\n\n<Screenshot\n  src=\"/screenshots/reelshort-vs-dramabox-catalogue.webp\"\n  alt=\"The DramaBox home feed showing rows of vertical-format short drama posters with episode counts\"\n  caption=\"DramaBox's catalogue layout — deliberately the same shape as ReelShort's, because they are the same operator\"\n/>\n\n**What this means in practice:** if you have already used ReelShort, you know how\nthis one behaves, including the parts that irritate people. If you disliked\nthose parts in ReelShort, they are not fixed here.\n\n**What it does not tell you:** anything about content quality or whether you will\nlike the dramas. Same operator does not mean same shows.\n\n<h2 id=\"regional\">It prices by your exit country</h2>\n\nThis is the most unusual thing we found, and it is worth knowing because it\nchanges what you pay without any notice.\n\nWhile testing DramaBox we changed only the network exit, keeping the same device\nand the same account:\n\n| Network exit | Currency shown | 300-coin pack |\n|---|---|---|\n| Japan | Japanese yen | ¥410 |\n| United States | US dollars | **$2.99** |\n\nThe app confirms it in its own store copy: *\"The current product prices are\ndisplayed in USD. Please restart DramaBox to refresh the localized pricing.\"*\n\n<Screenshot\n  src=\"/screenshots/dramabox-paywall-regional-pricing.webp\"\n  alt=\"A DramaBox coin purchase screen showing a total in Japanese yen with an address bar showing prices in USD\"\n  caption=\"Same account, same device, Japanese network exit — the totals are in yen while the app notes prices are shown in USD\"\n/>\n\n<Callout kind=\"warning\" title=\"This one is not scammy, it is just regional\">\nRegional pricing is standard practice and not in itself a warning sign. What\nmatters is that <strong>your price depends on your network, not your account</strong>.\nIf you travel or use a VPN, check the price again — it may not be the price you\npaid last time.\n</Callout>\n\n<h2 id=\"pricing\">What you actually pay</h2>\n\nThe DramaBox subscription is the cheaper of the two we measured, but the shape\nis the same trap as everywhere else in this category:\n\n| Plan | First period | Renewal | Worked out |\n|---|---|---|---|\n| Weekly membership | **$9.99/week × 3 weeks** (was $12.99, 23% off, 24h countdown) | **$12.99/week** | — |\n| Annual membership | **$119.99/year** | same | advertised as **$2.31/week** |\n\nThere is also a **$3.00 off coupon popup** stacked on top of the first three\nweeks, with its own 23:59 countdown. Membership includes 16,000+ titles,\ndownloads, daily member points, 1080p and three gifts a week.\n\n<Screenshot\n  src=\"/screenshots/dramabox-membership-plans.webp\"\n  alt=\"A DramaBox subscription screen showing the weekly plan at 9.99 dollars for three weeks and the annual plan at 119.99 dollars\"\n  caption=\"The two DramaBox plans side by side — $12.99 a week after the discount window, or $2.31 a week billed annually\"\n/>\n\nThe useful comparison, using the same accounting as our\n<a href=\"/guides/cheapest-short-drama-app\">cheapest-app ranking</a>:\n\n- **$12.99/week is the cheapest weekly renewal** of any app we measured — about\n  35% under the $19.99 cluster and well under ReelShort's tiers\n- **$2.31/week on annual is roughly a fifth of the weekly rate** (5.6× cheaper\n  per week), which is the largest gap between the two plans anywhere in the six\n  apps we tested\n- Per episode, DramaBox costs **$0.50 at 50 coins per episode** — cheaper than\n  ReelShort's $0.60 at 60 coins\n\nSo DramaBox is genuinely cheaper than its closest competitor on weekly renewal,\nper-episode cost and annual terms. The catch is entirely in whether a year-long\ncommitment suits how long you will actually keep watching.\n\n<h2 id=\"complaints\">What the complaints are actually about</h2>\n\nThe complaint pattern we found is not \"this app is fake\". It is three specific\nthings:\n\n<ol class=\"steps\">\n  <li>\n    <strong>The free run varies by series.</strong> DramaBox gave us 11 free\n    episodes on one show and charged from episode 12, but the free length moves\n    between series. Anyone who hits a short opening after a long one will\n    reasonably feel misled, even though nothing on the app promised a number.\n    What it does hand out predictably is coins — see\n    <a href=\"/guides/dramabox-free-coins\">every free-coin source</a>.\n  </li>\n  <li>\n    <strong>The renewal is higher than the first week.</strong> $9.99 for three\n    weeks, then $12.99. The 24-hour countdown is attached to the discounted\n    price, which is the number most people act on.\n  </li>\n  <li>\n    <strong>Price changes when you travel.</strong> Covered above. Not a scam,\n    but it is the thing most likely to make someone feel misled.\n  </li>\n</ol>\n\n<Callout kind=\"info\" title=\"Our read\">\nNone of these are signs of an illegitimate app. They are signs of a\nsubscription app with aggressive introductory pricing, which is what this entire\ncategory is. Knowing that in advance is most of what this page is for.\n</Callout>\n\n<h2 id=\"checklist\">The checklist we used</h2>\n\nYou can run this on any app in this category, including ones we have not\ncovered:\n\n<table class=\"data-table\">\n  <thead>\n    <tr><th>#</th><th>Check</th><th>What a bad result looks like</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>1</td><td>Download count and review volume</td><td>High rating, tiny review count</td></tr>\n    <tr><td>2</td><td>Who is the named operator?</td><td>Unrelated shell company, or no name at all</td></tr>\n    <tr><td>3</td><td>Does it do anything other than short drama?</td><td>A shell that is really a casino or loan app</td></tr>\n    <tr><td>4</td><td>Do the prices move by region?</td><td>Charging more for the same account in a different country</td></tr>\n    <tr><td>5</td><td>What is the renewal rate, not the intro?</td><td>Intro price used everywhere in the UI, renewal buried</td></tr>\n    <tr><td>6</td><td>Is cancelling possible outside the app?</td><td>No cancellation path anywhere</td></tr>\n    <tr><td>7</td><td>Does the free allowance match what is implied?</td><td>Promising \"10 free episodes\" on a page that gives 3</td></tr>\n  </tbody>\n</table>\n\nDramaBox passes 1 through 6 cleanly and is arguable on 7.\n\n<h2 id=\"limits\">Limits of this assessment</h2>\n\nA caveat that applies to everything here: <strong>this assessment does not work for\nthe app you are actually reading about, if that app is not the Play Store\nversion on a US account.</strong> The further limits:\n\n- **We only checked the Google Play Android version.** We did not test iOS, and\n  we did not test any version outside the Play Store.\n- **This is a store-listing and pricing review, not a security audit.** We did\n  not inspect the app binary, request permissions, or test the data safety\n  section's claims against actual behaviour. Read it as \"this is a real product\"\n  rather than \"this is verified safe in every sense\".\n- **We have not used a paid tier for long enough to test billing edge cases.**\n  Duplicate charges, failed renewals and refund handling are untested.\n- **Prices are from one day.** We captured them in October 2026 and this app\n  rotates discounts daily, so treat every figure as dated.\n- **We did not review content quality, dubbing accuracy or episode update\n  cadence**, beyond what is visible in the catalogue.\n- **Complaint analysis is not systematic.** We read what was visible; we did not\n  analyse review corpora.\n- **This is not an endorsement.** DramaBox is affiliate-linked on this site. The\n  verdict \"legit\" is about legitimacy, not endorsement.\n\n<h2 id=\"when-fails\">When this verdict does not apply</h2>\n\n- **If you are on iOS.** We did not test the iOS app, and the billing goes\n  through Apple, not Google Play.\n- **If you are outside the US.** The prices change by country, so the numbers\n  here will not be yours.\n- **If a specific show is the reason you are choosing.** This page says nothing\n  about whether the dramas are good.\n- **If you have already been charged and want a refund.** Refund handling is a\n  separate process we did not test, and it varies by store and region.\n- **If you are reading this months from now.** The structure — named operator,\n  regional pricing, discounted intro, higher renewal — will probably still hold.\n  The specific numbers will not.\n\n<AffiliateCTA\n  appName=\"DramaBox\"\n  href=\"https://r.reelsgo.tv/uR3A7JBLdipd\"\n  sub=\"Legit app — but check what your own screen charges, especially if you are travelling\"\n  buttonLabel=\"Open DramaBox\"\n/>","src/content/guides/is-dramabox-legit.mdx","e59bbdff83704ff6","reelshort-cost-per-season",{id:685,data:687,body:736,filePath:737,digest:738,deferredRender:74},{title:688,description:689,app:16,targetKeyword:690,intent:18,shortAnswer:691,publishedOn:139,updatedOn:139,priceVerifiedOn:27,toc:697,faqs:719,relatedGuides:735},"ReelShort Cost Per Season: What One Full Series Really Costs","A full ReelShort series finished with coins works out to roughly $20–50. Here is the per-season arithmetic, verified in-app on Android in October 2026.","reelshort cost per season",[692,693,694,695,696],"There is no separate \"season\" to buy — one series <em>is</em> the season. The two we measured ran <strong>54 and 81 episodes</strong>, so the episode count, not the label, sets the cost.","The formula is: <strong>(total episodes − free episodes) × 60 coins</strong>, then convert coins to dollars at your pack rate.","Two series we measured came out at <strong>$19.99</strong> (54 episodes) and <strong>roughly $35–50</strong> (81 episodes) on the coin route.","The free allowance absorbs a surprising share: <strong>10 advert-unlocks a day</strong> is 10 episodes, plus about 375 coins from the 7-day check-in.","VIP only beats coins per season if you finish that season in <strong>under two weeks</strong>. Slower than that, coins win.",[698,701,704,707,710,713,716],{id:699,label:700},"season-meaning","What \"a season\" means here",{id:702,label:703},"formula","The per-season formula",{id:705,label:706},"worked","Three worked examples",{id:708,label:709},"cheapest","The cheapest route, in order",{id:711,label:712},"vip-per-season","When VIP wins per season",{id:714,label:715},"where-breaks","Where this breaks down",{id:717,label:718},"bottom-line","Bottom line",[720,723,726,729,732],{q:721,a:722},"How much does one full season of a ReelShort series cost?","Between roughly $20 and $50, depending on how many episodes the series has and which coin pack you buy. Two series we measured: a 54-episode title needed 2,400 coins to finish, which is exactly the $19.99 pack; an 81-episode title needed 3,960 coins, which comes to about $35–50 depending on the pack combination. One episode costs 60 coins, verified in-app on Android in October 2026.",{q:724,a:725},"Why is ReelShort priced per season rather than per month?","Because there is no monthly price. The app sells coins for per-episode unlocks and VIP passes on weekly and annual terms. The useful unit of cost for a viewer is cost per finished series, which is what this page calculates. Anyone quoting a single monthly figure is guessing at your viewing habit.",{q:727,a:728},"Is it cheaper to buy VIP than coins for one season?","Only if you finish that season fast. Weekly VIP renewed at $5.99–$19.99 per week when we checked. A 60-episode season watched over two weeks costs $12–$40 on VIP, which can beat the coin route. Watched over a month, the same season costs $24–$80 on VIP while the coins still cost about $20–50 in total. The coin route has a ceiling; VIP does not.",{q:730,a:731},"Do the free episodes change the cost per season?","Yes, and by more than people expect. The free block before the paywall is not fixed: we recorded an 81-episode series with 15 free episodes and a 54-episode series with 14. On top of that, 10 advert-unlocks a day and a 7-day check-in worth about 375 coins are free. A patient viewer can finish a season without paying at all.",{q:733,a:734},"Does ReelShort charge the same price everywhere?","No. We recorded two separate checkout channels on the same day — Google Play billing and the reelshort.com web checkout — quoting different totals for the same weekly VIP tier. Our exit country also changes what the app shows. Treat any price you read online, including ours, as a dated measurement rather than a fixed rate.",[226,67,180,69,179,177],"import Callout from '../../components/Callout.astro';\nimport PriceTable from '../../components/PriceTable.astro';\nimport Screenshot from '../../components/Screenshot.astro';\nimport AffiliateCTA from '../../components/AffiliateCTA.astro';\n\n<p class=\"lede\">\n\"Cost per season\" is the question people actually have about ReelShort, and it is\nthe one nobody answers. The app does not publish a monthly price, does not\npublish a per-series price, and rotates its discounts daily. So we measured it\ninstead: watched the paywalls, counted the episodes, and did the arithmetic on\ntwo real series.\n</p>\n\n<h2 id=\"season-meaning\">What \"a season\" means here</h2>\n\nFirst, a correction that saves you money. Short-drama apps do not sell seasons\nthe way a television show does. **One series is the season.** That series might\nrun 54 episodes or 81 — those are the two we opened and counted — but there is\nno \"Season 3\" waiting to be sold to you separately.\n\nThat matters for search results, because the phrase \"cost per season\" returns\nvery little that is accurate. It also matters for your budget: the number to\nplan around is **cost per finished series**, not cost per month.\n\nEvery figure below comes from an Android phone with a US Google Play account,\nchecked in-app on 8–9 October 2026, with screenshots at each step. The prices\nrotate — we saw a 67%-off offer one day and a 21%-off offer the next — so treat\nthem as dated measurements, not a rate card.\n\n<h2 id=\"formula\">The per-season formula</h2>\n\nThree steps, and you can run them for any series in under a minute:\n\n<ol class=\"steps\">\n  <li>\n    <strong>Find the episode count.</strong> It is on the series page. Count the\n    episodes, not the parts.\n  </li>\n  <li>\n    <strong>Subtract the free block.</strong> Roughly 10–16 episodes play before\n    the paywall, and the exact number <em>varies by series and is not disclosed\n    in advance</em>. Open the series, scroll to the first locked episode, and\n    note which one it is.\n  </li>\n  <li>\n    <strong>Multiply the remainder by 60 coins</strong> — the verified per-episode\n    price — then convert to dollars at the pack rate you would actually buy at.\n  </li>\n</ol>\n\n<PriceTable\n  verifiedOn=\"2026-10-09\"\n  caption=\"The numbers this page is built on — verified in-app on Android, 8–9 October 2026\"\n  col1=\"Figure\"\n  col2=\"Measured value\"\n  rows={[\n    { label: 'Coins per locked episode', value: '60 coins', note: 'Stated on the paywall itself, not hidden' },\n    { label: 'Coin packs', value: '$4.99 – $49.99', note: '$4.99/500, $9.99/1,100, $19.99/2,400, $29.99/3,900, $49.99/7,500' },\n    { label: 'Cost per coin', value: '$0.0100 → $0.0067', note: 'Falls by a third from the smallest to the largest pack' },\n    { label: 'Free block before the paywall', value: '10 – 16 episodes', note: 'Varies by series. We measured 14 and 15 on two titles.' },\n    { label: 'Free advert-unlocks', value: '10 per day', note: 'Confirmed on two separate days — 10 episodes a day, free' },\n    { label: '7-day check-in total', value: 'about 375 coins', note: 'Day 7 alone pays 200 coins, more than three episodes' },\n  ]}\n/>\n\n<h2 id=\"worked\">Three worked examples</h2>\n\nThese use the two series we actually opened, so the episode counts are real\nrather than illustrative.\n\n<h3>Example 1 — a 54-episode series: about $19.99</h3>\n\nThe title we measured had 54 episodes and the paywall arrived at episode 15, so\n**40 episodes needed unlocking**. At 60 coins each that is 2,400 coins — which\nis exactly the $19.99 pack. A full season, start to finish, for the price of one\nmonth of a streaming service and no auto-renewal attached.\n\n<h3>Example 2 — an 81-episode series: roughly $35–50</h3>\n\nThe longer title ran 81 episodes with the paywall at episode 16, leaving **66\nlocked episodes**, or 3,960 coins. Coins are sold in fixed packs, so the total\ndepends on how you assemble it:\n\n| Pack combination | Cost | Coins | Covers the season? |\n|---|---|---|---|\n| $19.99 × 2 | $39.98 | 4,800 | Yes, with 840 left over |\n| $29.99 + $4.99 | $34.98 | 4,400 | Yes, with 440 left over |\n| $49.99 × 1 | $49.99 | 7,500 | Yes, with 3,540 left over |\n\nThe third option is the worst per season and the best per coin. That is the\ntrap in this pricing: **the pack that offers the best rate is only the best\nvalue if you finish another season.**\n\n<Screenshot\n  src=\"/screenshots/reelshort-episode-free-boundary.webp\"\n  alt=\"ReelShort episode list for an 81-episode series showing free episodes, an advert-tagged episode at 15, and locked episodes from 16 onwards\"\n  caption=\"The episode list is the only place the free block is visible. Here it runs to episode 15; on a 54-episode series we measured, it ran to 14.\"\n/>\n\n<Screenshot\n  src=\"/screenshots/reelshort-coin-packs.webp\"\n  alt=\"ReelShort unlock popup listing coin packs from 4.99 dollars for 500 coins up to 49.99 dollars for 7500 coins, with the episode priced at 60 coins\"\n  caption=\"The coin packs, reached from a locked episode. Note that the $4.99 and $9.99 tiers do not appear on the main store page at all.\"\n/>\n\n<h2 id=\"cheapest\">The cheapest route, in order</h2>\n\nIf the goal is to pay as little as possible per season, do these in order and\nstop whenever the series is finished:\n\n1. **Watch the free block.** 10–16 episodes at no cost. No action needed.\n2. **Use the 10 daily advert-unlocks.** This is the single most under-used free\n   allowance in the app. Ten episodes a day, and a 60-episode season is\n   finishable in under a week without spending anything. The honest cost is\n   time and the advert quality, which on our account was a fake insurance offer\n   and a TikTok install prompt.\n3. **Run the check-in for a week.** About 375 coins, with day 7 alone paying\n   200. That is more than three episodes free.\n4. **Then buy coins — and buy them from the unlock popup, not the store page.**\n   The store page starts at $19.99. The $4.99 and $9.99 packs exist only inside\n   the popup, so buying from the store costs you the worst available rate.\n\n<Callout kind=\"info\" title=\"What that means in practice\">\nA viewer who runs the free loop for a week collects <strong>about 375 coins plus\nup to 70 advert-unlocked episodes</strong>. Most series we measured do not have that\nmany locked episodes. The paid path exists for impatience, not for access.\n</Callout>\n\n<Screenshot\n  src=\"/screenshots/reelshort-vip-plans.webp\"\n  alt=\"ReelShort subscription screen showing weekly VIP tiers with a discounted introductory rate and a 24 hour countdown\"\n  caption=\"The weekly VIP screen. The countdown applies to the discounted first week; the renewal rate — the one you would pay most weeks — is a higher number.\"\n/>\n\n<h2 id=\"vip-per-season\">When VIP wins per season</h2>\n\nVIP is a time-based pass, so its cost per season depends entirely on how fast\nyou watch. Using the renewal rates we recorded:\n\n| VIP tier | Cost per week | One season in 1 week | In 2 weeks | In 4 weeks |\n|---|---|---|---|---|\n| Weekly (with Ads) | $5.99 | $5.99 | $11.98 | $23.96 |\n| Weekly (Ad-Free) | $11.99 | $11.99 | $23.98 | $47.96 |\n| Weekly (Standard) | $19.99 | $19.99 | $39.98 | $79.96 |\n\nCompare that to the coin route, which is **$19.99 to about $50 per season and\ndoes not care how long you take**. The rule that falls out of the two tables:\n\n- **Finish a season in under about two weeks** → VIP is cheaper, and much\n  cheaper if you are bingeing several series at once.\n- **Take a month or more** → coins are cheaper, because they do not charge you\n  for the weeks you do not open the app.\n- **Cannot say how fast you watch** → coins, because they have a ceiling and VIP\n  does not.\n\nThe annual tier changes the shape again: at $199.99 for a year it works out at\nroughly $3.85 a week, which beats every weekly renewal price on the list. It\nonly makes sense if you are confident you will still be watching in twelve\nmonths — and it is the only tier where the per-season maths stops mattering.\n\n<Callout kind=\"alert\" title=\"Before you subscribe to a weekly tier\">\nThe renewal charge lands 24 hours before each period ends, at the renewal rate\nrather than the intro rate. Our\n<a href=\"/guides/how-to-cancel-reelshort-subscription\">cancellation walkthrough</a>\ncovers how to stop it — read it before you subscribe, not after the first charge.\n</Callout>\n\n<AffiliateCTA\n  appName=\"ReelShort\"\n  href=\"https://r.reelsgo.tv/1vwtyh4hj9R3\"\n  sub=\"Free to download · check the episode count and the free block in your own app first\"\n  buttonLabel=\"Open ReelShort\"\n/>\n\n<h2 id=\"where-breaks\">Where this breaks down</h2>\n\nThis is a limitation of the method, not a hedge:\n\n- **The free block is not published, so you cannot compute the cost before you\n  start watching.** Every calculation here needs the first locked episode\n  number, and the only way to get it is to open the series. This does not work\n  as a spreadsheet exercise; it is a two-minute check inside the app.\n- **These are Android prices from a US-route account.** ReelShort's prices moved\n  with our exit country during testing, and iOS billing is a different system we\n  have not measured. If you pay on Apple or outside the US, your numbers differ.\n- **The intro price rotates, so any figure you read online is a snapshot.** We\n  documented 67% off and 21% off on consecutive days from the same account.\n  Anchor everything to the renewal price and the coin pack rates.\n- **Even the checkout channel changes the total.** On 10 October we recorded the\n  app quoting US$10.99 for a weekly tier while the web checkout quoted $11.87\n  including tax for the same tier on the same day — two parallel payment routes\n  with different totals.\n- **\"Cost per season\" is not a comparison between apps.** Apps with a cheaper\n  season may have a smaller catalogue or shorter episodes. Our\n  <a href=\"/guides/reelshort-vs-dramabox\">ReelShort vs DramaBox breakdown</a>\n  covers why an annual-fee app can be structurally cheaper per hour even when\n  its headline price looks higher.\n\n<Screenshot\n  src=\"/screenshots/reelshort-purchase-confirmation.webp\"\n  alt=\"Google Play subscription confirmation screen for ReelShort showing the first week price, the renewal price and the renewal date\"\n  caption=\"The confirmation screen is where the real per-season cost is decided: the renewal line and the renewal date, not the headline discount.\"\n/>\n\n<Screenshot\n  src=\"/screenshots/reelshort-web-checkout.webp\"\n  alt=\"ReelShort web checkout page showing a weekly VIP total with tax, alongside the web payment methods it accepts\"\n  caption=\"The second payment channel. Same weekly tier, different total from the in-app price — one of the reasons this page quotes ranges rather than a single number.\"\n/>\n\n<h2 id=\"bottom-line\">Bottom line</h2>\n\nOne full ReelShort series costs **$19.99 to about $50 in coins**, and nothing on\nthe coin route changes that number based on how long you take. The free\nallowances — 10–16 free episodes, 10 advert-unlocks a day, about 375 coins a week\nfrom check-ins — are large enough that a patient viewer can finish a season for\nnothing.\n\nIf you want the number for your specific series, you can have it in two minutes:\nopen the series, find the first locked episode, subtract it from the total,\nmultiply by 60 coins, and pick the smallest pack combination that covers it.\nThat is the whole method, and it is more accurate than anything this page — or\nany price comparison site — can tell you about your own screen.\n\nIf your habit turns out to be more than one season a month, the arithmetic\nchanges in a way that is worth checking before you commit to a weekly tier: see\n<a href=\"/guides/reelshort-coins-vs-vip\">coins vs VIP</a> for the break-even\npoints, and <a href=\"/guides/how-to-get-free-coins-on-reelshort\">how to get free\ncoins</a> for the free loop in full detail.\n\n<AffiliateCTA\n  appName=\"DramaBox\"\n  href=\"https://r.reelsgo.tv/uR3A7JBLdipd\"\n  sub=\"Watching more than a season a month? An annual pass is the structurally cheaper shape — verify current pricing in-app\"\n  buttonLabel=\"Open DramaBox\"\n/>","src/content/guides/reelshort-cost-per-season.mdx","35c5e671ce296367","dramabox-free-coins",{id:739,data:741,body:794,filePath:795,digest:796,deferredRender:74},{title:742,description:743,app:283,targetKeyword:744,intent:18,shortAnswer:745,publishedOn:139,updatedOn:139,priceVerifiedOn:27,toc:751,faqs:777,relatedGuides:793},"DramaBox Free Coins (2026): Every Method, With Daily Caps","Every way to earn DramaBox coins free — sign-up tasks, check-ins, video tasks and ad unlocks — with the daily caps we counted in the app on Android.","dramabox free coins",[746,747,748,749,750],"Free opening episodes are the biggest allowance: the series we tested unlocked about 11 episodes before the paywall, and the boundary moves from title to title.","The one-time sign-up tasks pay <strong>450 coins</strong> in total (150 for signing in, 150 for enabling notifications, 50 each for Telegram, YouTube and TikTok) — the largest single free source in the app, and the one most people skip.","Daily check-ins pay <strong>165 coins across seven days</strong>, rising to 50 on day 7; watching an ad after check-in adds 30 more.","Video tasks pay <strong>20 coins each, up to 15 a day</strong> — 300 coins daily, which is the largest renewable free source and roughly six episodes.","Ad unlocks are capped at <strong>8 episodes per day</strong>. One locked episode costs 50 coins, so 300 coins is about six episodes.",[752,753,754,757,760,763,765,768,771,774,775,776],{id:90,label:142},{id:144,label:145},{id:755,label:756},"signup-bonus","2. The one-time sign-up bonuses",{id:758,label:759},"checkin","3. Daily check-in coins",{id:761,label:762},"video-tasks","4. Video tasks: 300 coins a day",{id:150,label:764},"5. Ad unlocks, capped at 8",{id:766,label:767},"what-they-buy","What the free coins actually buy",{id:769,label:770},"points","Member points are not free coins",{id:772,label:773},"reward-coins-first","Reward coins are spent first",{id:156,label:157},{id:159,label:160},{id:48,label:162},[778,781,784,787,790],{q:779,a:780},"Can you get unlimited free coins on DramaBox?","No. Every free source is capped per day. We counted them on Android in October 2026: video tasks at 20 coins each up to 15 a day (300 coins), a seven-day check-in worth 165 coins, 30 coins for watching an ad after check-in, and 8 ad unlocks a day. One locked episode costs 50 coins, so the ceiling is roughly a dozen episodes a day of active effort — never an unlimited supply.",{q:782,a:783},"Does DramaBox give you free coins for signing up?","Yes, and it is the biggest single free source in the app. The task page pays 150 coins for signing in with any account, 150 for enabling push notifications, and 50 each for joining Telegram and following the app on YouTube and TikTok — 450 coins in total, which buys nine episodes at 50 coins each. It is one-time, and it requires linking social accounts, so it is a real trade rather than a freebie.",{q:785,a:786},"How many episodes can you watch free on DramaBox before paying?","It varies by series and DramaBox does not publish the number. In our October 2026 test, a 43-episode title was free from episode 1 and hit the paywall at episode 12 — roughly 11 free episodes. On another title we still had an ad-unlock option at episode 20. Open the episode list of the series you want and scroll to the first padlock before you commit.",{q:788,a:789},"Do DramaBox check-in coins expire?","The check-in coins we accrued added to our balance rather than resetting each day, and we did not see an expiry notice on them. The mechanic that does matter is spending order: DramaBox states that reward coins are used first when you unlock an episode, so the coins you collected free are consumed before the ones you paid for.",{q:791,a:792},"Is there a DramaBox redeem code for free coins?","We have not verified any working public redeem code for DramaBox. The genuine free sources are all inside the app and are listed on this page. Any site asking for your login details, or a payment, in exchange for coins is a red flag — the coin balance is held server-side and no outside tool can add to it.",[274,70,69,177,275,178,179],"import Callout from '../../components/Callout.astro';\nimport Screenshot from '../../components/Screenshot.astro';\nimport AffiliateCTA from '../../components/AffiliateCTA.astro';\n\n<h2 id=\"short-version\">The short version</h2>\n\nDramaBox has five genuine free-coin sources, and they stack. Read the numbers\nbelow before you assume the usual thing — that free routes are always smaller\non the app with the bigger price tag. DramaBox charges less per episode than\nReelShort (50 coins against 60) and hands out a larger one-time bonus, so\npound for pound its free tier buys you more viewing than its rival's does.\n\nWhat it will not do is let you finish a series for nothing. Every source is\ncapped per day, and the paywall arrives earlier here than on some competitors.\n\nHere is the honest framing: **the free tier is a sampler with unusually\ngenerous sign-up terms.** The maths is worked out in full further down.\n\n<Callout kind=\"info\" title=\"Where these numbers come from\">\nEvery figure on this page was read inside the DramaBox app on an Android\ndevice with a US Play account on 9 October 2026, and is recorded in our\n<a href=\"/guides/dramabox-subscription-cost\">DramaBox price log</a>. The\ncurrency was US dollars throughout. Caps and coin amounts change often —\nre-check in the app before relying on any single number.\n</Callout>\n\n<h2 id=\"free-episodes\">1. Free opening episodes — the biggest allowance</h2>\n\nEvery series opens with a block of free episodes before the paywall appears.\nThis is the largest free allowance on the platform, and because it applies per\nseries rather than per account, it works across many different titles.\n\nThe boundary is not fixed. In our October 2026 test a 43-episode title ran free\nfrom episode 1 and charged from **episode 12** — roughly 11 free episodes. On a\ndifferent title we still had an ad-unlock option as late as episode 20. DramaBox\ndoes not publish the number anywhere, which is why every article that states a\nfixed figure is guessing.\n\n<Callout kind=\"warn\" title=\"DramaBox charges earlier than ReelShort\">\nCompare like with like and the difference is real: an 81-episode series on\nReelShort ran 16 free episodes, while our 43-episode DramaBox title locked at\n12. Nothing further down this page changes that — budget for the paywall\narriving sooner here, however generous the coin tasks turn out to be.\n</Callout>\n\nThe per-series block is also worth far more than any coin trick. Suppose you\nsample five series and average 11 free episodes each: that is 55 episodes of\nviewing for nothing, against the 300 coins a day the hardest-working free route\npays out. Spend the evening on the free episodes, not on coins.\n\n<Screenshot\n  src=\"/screenshots/dramabox-paywall-regional-pricing.webp\"\n  alt=\"DramaBox paywall on episode 12 of a series, showing coin packs priced in Japanese yen alongside membership options in the same panel\"\n  caption=\"Where the free block ends on Android, 9 October 2026: episode 12 is the first locked episode on this 43-episode series. The prices read as yen because this capture came through a Japanese connection\"\n/>\n\n<h2 id=\"signup-bonus\">2. The one-time sign-up bonuses — 450 coins</h2>\n\nThis is the most valuable free source on DramaBox, and the one almost nobody\nfinishes. The task page pays out in five chunks:\n\n- **+150 coins** for signing in with any account\n- **+150 coins** for enabling push notifications\n- **+50 coins** for joining the app's Telegram channel\n- **+50 coins** for following the app on YouTube\n- **+50 coins** for following the app on TikTok\n\nThat is **450 coins** in total — nine episodes at 50 coins each, from a single\nsitting. For scale, that is nearly three times what a full week of check-ins\npays you.\n\nThe trade is honest and worth stating: you are handing over a notification\nchannel and a social follow for each block. If you are not comfortable with\nthat, the signing-in task alone is still 150 coins for nothing but a login.\n\n<Callout kind=\"info\" title=\"The order to do these in\">\nDo the sign-in task first — it needs no third-party account and is the single\nlargest chunk. Then decide, task by task, whether the notification and social\nfollows are worth 50 coins apiece to you. Nothing here is required to use the\napp.\n</Callout>\n\n<h2 id=\"checkin\">3. Daily check-in coins — 165 coins a week</h2>\n\nThe check-in calendar is the part everyone knows about, and it is not\nDramaBox's strongest suit. The seven-day cycle we documented pays:\n\n**10 → 10 → 20 → 20 → 25 → 30 → 50 coins.** That is **165 coins across the\nweek**, or about three episodes.\n\nOne extra to know: after checking in, the app offers **+30 coins** for watching\nan advertisement. That single button is worth more than five of the seven\ncheck-in days, which tells you what the check-in calendar is really for.\n\nReelShort pays 375 coins over its equivalent week — more than double — with a\n200-coin day-7 payout against DramaBox's 50. If daily streaks are your main\nfree source, that app is the better one, and we break the comparison down in\n<a href=\"/guides/how-to-get-free-coins-on-reelshort\">our ReelShort free-coin guide</a>.\n\n<Screenshot\n  src=\"/screenshots/dramabox-checkin-rewards.webp\"\n  alt=\"DramaBox reward coins page showing a seven day check-in calendar rising from 10 coins to 50 coins on day seven, with task bonuses below\"\n  caption=\"The check-in calendar on Android, 9 October 2026: 165 coins for a full week, with day 7 at 50 — a third of ReelShort's day-7 payout\"\n/>\n\n<h2 id=\"video-tasks\">4. Video tasks — 300 coins a day</h2>\n\nThis is DramaBox's largest renewable free source, and it is buried under the\ncheck-in calendar where most people never scroll.\n\n**Video tasks pay 20 coins each, up to 15 tasks a day — 300 coins daily.** At\n50 coins an episode that is about **six episodes a day**, every day, without\npaying anything.\n\nPut the two sources side by side and the check-in calendar is decoration:\none day of video tasks (300 coins) is worth almost two full weeks of checking\nin (165 coins). If you only do one thing on this app for free coins, do this\none.\n\nThe honest cost is time and attention: fifteen tasks is fifteen videos you sit\nthrough. It is the best possible trade on the platform, but it is not passive.\n\n<h2 id=\"ad-unlocks\">5. Ad unlocks — capped at 8 episodes a day</h2>\n\nSelected titles let you unlock an episode by watching an advertisement instead\nof spending coins. This is the only free route that costs you no coins at all,\nwhich makes it the best value per episode when it is available.\n\nTwo hard limits we confirmed in the app:\n\n- The daily cap is **8 ad unlocks** — the popup carries your count and stops\n  at eight\n- It only appears on **selected titles**, so you cannot count on it for the\n  series you actually want\n\nFor comparison, ReelShort allows 10. Two episodes a day is a small gap, but it\nis a gap, and it means DramaBox's \"watch an ad instead of paying\" route runs out\nslightly sooner.\n\n<Screenshot\n  src=\"/screenshots/dramabox-ad-unlock.webp\"\n  alt=\"DramaBox episode paywall offering three routes at once: unlock with 50 coins, watch an ad to unlock free, or join membership, with a daily ad counter\"\n  caption=\"The three-way paywall on Android, 9 October 2026: coins, an ad, or a subscription. The ad route has its own daily counter and it runs out\"\n/>\n\n<h2 id=\"what-they-buy\">What the free coins actually buy</h2>\n\nIndividually the sources look small. Stacked, the first week adds up like this:\n\n| Source | Coins | Episodes at 50 coins |\n|---|---|---|\n| One-time sign-up tasks (all five) | 450 | 9.0 |\n| Seven-day check-in | 165 | 3.3 |\n| +30 ad after each check-in, seven days | 210 | 4.2 |\n| **First-week coin total** | **825** | **16.5** |\n\nTreat that bottom row as the ceiling, not the default. It assumes you clear all\nfive sign-up tasks and watch the post-check-in ad every single day. Do only the\nsign-in task and check in without the ads and the same week pays 315 coins —\nsix episodes. The 16.5 is what is available to someone willing to do the work,\nand it does not yet include the ~11 free opening episodes waiting on every\nseries you start.\n\n<Screenshot\n  src=\"/screenshots/dramabox-store-plans.webp\"\n  alt=\"DramaBox in-app store showing coin packs priced in US dollars from a small entry pack up to a large bundle, with membership offers alongside\"\n  caption=\"The coin packs those free coins compete with: $2.99 for 300 up to $24.99 for 3,500, verified 9 October 2026. The 825 coins available in your first week of tasks is more than the $6.99 pack holds\"\n/>\n\nAgainst ReelShort on the same basis the welcome gap is stark. Its new-account\nbonus is 50 coins and its documented check-in week is 375 — 425 coins in total,\nwhich at 60 coins an episode buys **about 7 episodes**, against DramaBox's 16.5.\n\nDay to day the two are much closer, and the advantage narrows. DramaBox settles\nat roughly **300 coins from video tasks, plus about 24 a day from check-ins, plus\n30 for the post-check-in ad — about 354 coins, or seven episodes**. ReelShort's\nrenewable ceiling is a 340-coin watch-time ladder plus its check-in week spread\nacross seven days, roughly 394 coins, which at 60 coins an episode is **about six\nand a half episodes**. DramaBox still edges ahead — but only because its episodes\ncost 50 coins rather than 60.\n\nWhich means the standard advice, that ReelShort is the more generous free app, is\nonly half right. It is more generous on streaks and ad unlocks. It is less\ngenerous where it counts most: the week you arrive.\n\n<Callout kind=\"warn\" title=\"But the paywall is closer\">\nNone of this changes the fact that DramaBox charges from around episode 11,\nwhile ReelShort's free block ran to 16 on the series we tested. More free coins\nand an earlier paywall can both be true, and here they are. Compare the\n<a href=\"/guides/reelshort-vs-dramabox\">two apps side by side</a> before\ndeciding which one to spend your first week on.\n</Callout>\n\n<h2 id=\"points\">Member points are not free coins</h2>\n\nDramaBox has a points system that is easy to mistake for another free-coin\nsource. It is not one. The app states plainly that **points can only be earned\nby paid members**, and that 500 points buys one extra day of membership.\n\nThat makes points a discount on a subscription you already have, not a route to\nwatching without one. It is worth collecting if you subscribe — and it should\nhave no bearing on whether you do.\n\n<h2 id=\"reward-coins-first\">The rule almost nobody knows: reward coins are spent first</h2>\n\nThis one is buried in the store page's own help text, and it changes how you\nshould think about buying coins.\n\n**DramaBox spends your reward coins first when you unlock an episode.** The\ncoins you collected from check-ins, video tasks and sign-up bonuses are consumed\nbefore the coins you paid for.\n\nTwo practical consequences:\n\n- **The free coins are never wasted by buying early.** Collection order is set\n  by the app, not by you, so there is no advantage in delaying a purchase to\n  \"use up\" the free balance.\n- **Your paid balance lasts longer than the receipt suggests.** Any free coins\n  earned between buying a pack and finishing a series still get used first.\n\nIt also means the 450-coin sign-up bonus is genuinely worth 9 episodes — not a\nsweetener that quietly expires while you spend real money.\n\n<h2 id=\"what-does-not-work\">What does not work — and what to avoid</h2>\n\n<Callout kind=\"alert\" title=\"Sites promising a redeem code or a free coin tool\">\nWe have not verified any working public redeem code for DramaBox, and no\nlegitimate service hands out free coins. Sites offering either typically want\none of two things: your account credentials, or a payment for a \"tool\" that\ndoes nothing. Both are ways to lose money or an account.\n</Callout>\n\nThe search term \"DramaBox free coins\" is itself a hunting ground for this, so\nthe list of dead ends is worth reading before you click anything:\n\n- **Coin generators and hacks.** They do not exist. The coin balance is held\n  server-side, which is exactly why no external tool can touch it.\n- **Modified or tampered app builds.** These are a copyright violation, they get\n  accounts banned, and they are a common vector for malware. They are also the\n  fastest way to get a site deindexed if you ever write about them.\n- **Third-party code lists.** Unverified, usually expired, and often used purely\n  to harvest email addresses.\n\n<Callout kind=\"info\" title=\"A note on what a code even is\">\nThe app has no input field for codes. There is nothing to redeem. If a site is\nshowing you a box to type a code into, that box is on that site, not in\nDramaBox — which tells you the code is decorative.\n</Callout>\n\n<h2 id=\"best-strategy\">The strategy we actually use</h2>\n\n<ol class=\"steps\">\n  <li>\n    <strong>Clear the five sign-up tasks on day one.</strong>\n    That is 450 coins — nine episodes — before you have watched anything. It is\n    the single largest free block on the platform and it takes minutes.\n  </li>\n  <li>\n    <strong>Run the video tasks while you sample series.</strong>\n    Twenty coins a task, fifteen a day. This is the largest renewable source and\n    it is the one people skip. Clear them every day for a week and you will have\n    banked around 2,000 coins without paying anything.\n  </li>\n  <li>\n    <strong>Count the free block on each series before you commit.</strong>\n    Scroll the episode list to the first padlock. It moves from title to title,\n    and knowing the number is what stops you spending coins on episodes you\n    could have had free.\n  </li>\n  <li>\n    <strong>Only then price coins against membership.</strong>\n    Finishing one series with coins and finishing two or more with a\n    subscription are different purchases with very different economics. Our\n    <a href=\"/guides/dramabox-subscription-cost\">DramaBox price breakdown</a>\n    works through where that line sits.\n  </li>\n  <li>\n    <strong>Set a reminder before any subscription renews.</strong>\n    Renewal is where people lose money on these apps, not the first payment.\n    The mechanics are the same as\n    <a href=\"/guides/how-to-cancel-dramabox-subscription\">cancelling\n    DramaBox</a>.\n  </li>\n</ol>\n\n<AffiliateCTA\n  appName=\"DramaBox\"\n  href=\"https://r.reelsgo.tv/uR3A7JBLdipd\"\n  sub=\"Free to download · 450 coins in sign-up tasks before you spend anything\"\n  buttonLabel=\"Open DramaBox\"\n/>\n\n<h2 id=\"limitations\">When this approach does not work</h2>\n\nBe clear about the boundaries, because they are real:\n\n- **If you watch more than a dozen episodes a day, this does not work.** The\n  free sources are capped by design, and the ceiling is roughly 300 coins plus\n  eight ad unlocks. Past that you are paying, and the only useful question left\n  is which payment shape is cheapest — see\n  <a href=\"/apps/dramabox\">our full DramaBox review</a>.\n- **All figures are Android, October 2026.** Coin amounts, task counts and caps\n  are exactly the kind of thing apps tune monthly.\n- **DramaBox prices by country.** The app showed us Japanese yen through one\n  connection and US dollars through another on consecutive days. Coin *prices*\n  clearly move with region; treat the coin *earn* rates above as the US-region\n  figures we measured rather than universal ones.\n- **If you expect these methods to stay static**, they will not. Tasks rotate\n  and caps change.\n\n<h2 id=\"bottom-line\">Bottom line</h2>\n\nDramaBox will hand you **450 coins in sign-up tasks, 165 coins for a week of\ncheck-ins and 300 coins a day from video tasks**, plus eight ad unlocks a day.\nEpisode 1 is free, roughly 11 episodes are free before the paywall, and one\nlocked episode costs 50 coins.\n\nThe free tier here is larger than its reputation suggests — roughly double\nReelShort's in episodes watched during your first week, because the one-time\nbonus is bigger and the per-episode cost is lower. What it does not have is a\ngenerous streak: ReelShort's 375-coin check-in week is more than twice\nDramaBox's 165.\n\nFor the side-by-side numbers, including which app is cheaper once you do start\npaying, see <a href=\"/guides/reelshort-vs-dramabox\">ReelShort vs DramaBox</a>.","src/content/guides/dramabox-free-coins.mdx","ca8b26713a8c82a8",{id:70,data:798,body:843,filePath:844,digest:845,deferredRender:74},{title:799,description:800,app:283,targetKeyword:801,intent:18,shortAnswer:802,publishedOn:139,updatedOn:139,priceVerifiedOn:27,toc:810,faqs:824,relatedGuides:842},"How to Cancel a DramaBox Subscription (iOS, Android and Web)","DramaBox subscriptions cancel through the store you bought them on, not inside the app. Step-by-step for iOS and Android, plus the renewal trap to check first.","how to cancel dramabox subscription",[803,804,805,806,807,808,809],"DramaBox subscriptions must be cancelled through the store you subscribed on — the app itself has no cancel button.","iOS: Settings → your name → Subscriptions → select DramaBox → Cancel Subscription.","Android: Play Store → profile icon → Payments & subscriptions → Subscriptions → DramaBox → Cancel.","The price almost certainly changes at renewal: DramaBox charges $9.99/week for three weeks, then $12.99/week. Read the renewal figure off before you confirm anything.","Coins are a one-off purchase with nothing to cancel — and DramaBox spends your free reward coins before your paid ones.","After cancelling, the subscription stays in the list but shows an access-until date instead of a billing date.","Access normally continues until the end of the period you already paid for.",[811,814,816,817,818,819,820,822,823],{id:812,label:813},"check-the-renewal-first","Check the renewal price first",{id:30,label:815},"Why there is no cancel button in the app",{id:33,label:34},{id:36,label:37},{id:39,label:40},{id:42,label:43},{id:302,label:821},"Coins: there is nothing to cancel",{id:45,label:46},{id:48,label:49},[825,828,831,833,836,839],{q:826,a:827},"Why can I not find a cancel button in the DramaBox app?","Because the app usually did not sell you the subscription. When you subscribe through the Apple App Store or Google Play, the store handles the payment and holds the renewal, so the only control that stops it lives in your store account settings. On Android, DramaBox says this itself in the app: cancellation is managed in Google Play subscriptions.",{q:829,a:830},"How much will I be charged when my DramaBox subscription renews?","Most likely more than you paid at the start. DramaBox lists Weekly Membership at $9.99 per week for the first three weeks — shown as 23% off $12.99 — and renews at $12.99 per week after that. If you subscribed during a discounted week, the amount your store shows as the renewal rate is the number that will be charged.",{q:55,a:832},"Normally no. Cancelling stops the next renewal and your access continues until the end of the period you already paid for. A refund is a separate request through the app store, not an automatic result of cancelling.",{q:834,a:835},"I cancelled but got charged again — what went wrong?","The two usual causes are cancelling in the wrong place (deleting the app, or signing out, cancels nothing) or cancelling after the renewal had already been processed. Open your store subscription list and check whether a future billing date is still shown. If it is, the cancellation did not register and you should run the steps again.",{q:837,a:838},"Does cancelling DramaBox delete my account or my coins?","No. Cancelling a subscription does not delete your account and your coin balance stays attached to it. You also lose access to member benefits — DramaBox member points can only be earned by paying members, so they stop accruing once the subscription ends.",{q:840,a:841},"Can I cancel DramaBox coins and get my money back?","Coins are a one-off purchase rather than a subscription, so there is nothing to cancel. Refunds on spent coins go through the app store refund process and are handled case by case, with no guarantee.",[274,275,11,739,123,178],"import Callout from '../../components/Callout.astro';\nimport Screenshot from '../../components/Screenshot.astro';\nimport AffiliateCTA from '../../components/AffiliateCTA.astro';\n\n<h2 id=\"check-the-renewal-first\">Read this before you cancel: the price changes at renewal</h2>\n\n<p>\n  DramaBox cancellation is the same two-minute job it is on every app store. The\n  part that catches people is not the mechanics — it is what they are cancelling\n  <em>into</em>. The introductory price is not the renewal price, and on this app\n  the gap is large enough to be the whole reason you are cancelling.\n</p>\n\n<p>\n  Weekly Membership is listed at <strong>$9.99 a week for the first three\n  weeks</strong>, shown in the app as 23% off $12.99 and carrying a 24-hour\n  countdown. After the three weeks it renews at <strong>$12.99 a week</strong> —\n  <strong>23% higher than the price you agreed to</strong>. If you signed up\n  during a promotional week and then quietly watched it roll over, the number\n  that charged you was not the number on screen when you tapped subscribe.\n</p>\n\n<Screenshot\n  src=\"/screenshots/dramabox-membership-plans.webp\"\n  alt=\"DramaBox membership plans page showing Weekly Membership at 9.99 dollars per week for the first three weeks against a struck-through 12.99 dollars, with Annual Membership priced at 119.99 dollars\"\n  caption=\"The DramaBox membership screen on Android, 9 October 2026. Read the weekly tier carefully: 9.99 dollars is the introductory rate and 12.99 struck through is what replaces it. The annual tier at 119.99 dollars is the only price here that does not change at renewal\"\n/>\n\n<p>\n  So before you tap anything, open your store's subscription list and read the\n  <strong>renewal amount</strong> on the DramaBox entry. That figure — not the\n  promotional price — is what your money situation actually looks like from here.\n</p>\n\n<Callout kind=\"warn\" title=\"The renewal price is the price that matters\">\nA cancelled subscription costs you nothing further, but a subscription you leave\nrunning at full rate costs you $12.99 a week — roughly $529 a year, for a week\nof bingeing you have already watched. If your reason for cancelling is cost, this\nis the number to do the arithmetic on. Our\n<a href=\"/guides/dramabox-subscription-cost\">DramaBox cost breakdown</a> works\nout where membership starts making financial sense against the coin route, which\nis a different question from whether you can stop the renewal.\n</Callout>\n\n<h2 id=\"why-in-app-does-not-work\">Why there is no cancel button inside DramaBox</h2>\n\n<p>\n  This is not a trick and it is not a dark pattern unique to DramaBox. When you\n  subscribe through the Apple App Store or Google Play, the store takes the\n  payment and holds the renewal instruction. The app is a tenant of that system,\n  not the landlord, so it genuinely cannot cancel the subscription for you.\n</p>\n\n<p>\n  DramaBox is unusually direct about this. The help text on its in-app store\n  page states that renewal is handled by Google Play, that Google Play charges\n  automatically within 24 hours of expiry, and that <strong>cancellation is\n  managed in Google Play subscriptions</strong>. That is the app telling you\n  where the control lives rather than hiding it.\n</p>\n\n<Callout kind=\"alert\" title=\"Three things that are not cancellations\">\n<strong>Deleting the app</strong> cancels nothing — the subscription survives and\nkeeps renewing. <br /><br />\n<strong>Signing out</strong> cancels nothing either, for the same reason. <br /><br />\n<strong>Cancelling a payment method</strong> is not a cancellation; it can leave\nyou in a failed-payment loop while the subscription is still live.\n</Callout>\n\n<p>\n  Delete-and-reinstall is the single most common route to a surprise charge, and\n  it is the one people are most confident about because the app really does\n  disappear. It disappears; the billing does not.\n</p>\n\n<h2 id=\"ios\">Cancel on iPhone or iPad</h2>\n\n<ol class=\"steps\">\n  <li>\n    <strong>Open Settings</strong> — the system Settings app on your device, not\n    the App Store.\n  </li>\n  <li>\n    <strong>Tap your name at the top.</strong> If it is not there, tap \"Sign in\n    to your iPhone\" first; the subscription list only appears for a signed-in\n    Apple ID.\n  </li>\n  <li>\n    <strong>Tap Subscriptions.</strong> This lists every active and recently\n    expired subscription on the account.\n  </li>\n  <li>\n    <strong>Select DramaBox.</strong> If it is missing, you subscribed with a\n    different Apple ID — a common issue on shared family devices.\n  </li>\n  <li>\n    <strong>Check the renewal price on the detail screen</strong> before you\n    commit to anything. On a discounted week this is where the jump from $9.99\n    to $12.99 is visible.\n  </li>\n  <li>\n    <strong>Tap Cancel Subscription.</strong> Apple will offer a retention\n    prompt with an alternative offer; continuing to cancel is fine, it does not\n    block you.\n  </li>\n</ol>\n\n<Callout kind=\"info\" title=\"How we checked the iPhone steps\">\nWe tested this flow end to end on Android, with screenshots. For iOS we had no\ndevice to capture, so the steps above follow Apple's own published cancellation\ndocumentation — we would rather say that than show you a picture we cannot stand\nbehind. The screen names are exactly as Apple labels them.\n</Callout>\n\n<h2 id=\"android\">Cancel on Android</h2>\n\n<ol class=\"steps\">\n  <li>\n    <strong>Open the Google Play Store</strong> and tap your profile icon in the\n    top right.\n  </li>\n  <li>\n    <strong>Open \"Payments &amp; subscriptions\", then \"Subscriptions\".</strong>\n    This is the authoritative list of what will renew.\n  </li>\n  <li>\n    <strong>Select DramaBox</strong> and read the subscription detail page\n    before tapping anything — it shows the exact renewal amount.\n  </li>\n  <li>\n    <strong>Tap Cancel subscription</strong> and work through the confirmation\n    screens, which usually include a retention offer.\n  </li>\n  <li>\n    <strong>Screenshot the confirmation.</strong> It is the fastest evidence to\n    have if a charge still appears.\n  </li>\n</ol>\n\n<p>\n  This is what a Google Play subscription confirmation looks like in practice,\n  and the price jump is printed in plain sight. The line marked <em>\"Today ·\n  1-week period\"</em> is the discounted first period. Beneath it, <em>\"Starting\n  Oct 16, 2026\"</em> is what you will actually pay from then on: <strong>$24.99\n  a week against the $15.99 you agreed to</strong>.\n</p>\n\n<Screenshot\n  src=\"/screenshots/netshort-gplay-subscription.webp\"\n  alt=\"A Google Play subscription confirmation screen showing a discounted first week at 15.99 dollars and the renewal rate of 24.99 dollars per week from a later date\"\n  caption=\"A real Google Play subscription confirmation, captured 8 October 2026 — from a sibling app in the same category, shown because the store's own layout is identical. Read the two price lines together: the discounted first period, and the renewal rate that replaces it\"\n/>\n\n<p>\n  The app name differs from ours, but the store screen does not — the\n  subscription confirmation, the renewal line and the cancellation terms are\n  Google's own, identical across every app sold through Play. It is also the\n  clearest example of the pattern DramaBox uses: a discounted first period that\n  quietly becomes the standard rate.\n</p>\n\n<Callout kind=\"info\" title=\"The store's wording is the honest part\">\nNote the two lines in the middle of that screenshot, in the store's own\nlanguage: <em>\"Cancel anytime in Subscriptions on Google Play\"</em> and <em>\"We'll\nsend you a reminder 2 days before your intro price ends.\"</em> You do get\nwarning. It is two days though, and people who subscribe on a discount routinely\ntreat that as the end of it rather than the start. If you subscribed on a\npromotional rate, act on the reminder.\n</Callout>\n\n<h2 id=\"web\">Cancel if you subscribed on the web</h2>\n\n<p>\n  If you subscribed through the desktop web player, neither app store holds the\n  subscription and neither store's list will show it. The cancellation route is\n  wherever you entered payment details — the account or billing page in a\n  browser.\n</p>\n\n<p>\n  Worth checking specifically, because a web subscription is easy to forget:\n  it will not appear in the store settings you are used to checking. If you are\n  unsure which route you used, our\n  <a href=\"/guides/is-dramabox-legit\">DramaBox legitimacy check</a> explains who\n  processes which payment.\n</p>\n\n<Callout kind=\"warn\" title=\"A DramaBox-specific wrinkle: prices move with your region\">\nThe same DramaBox account showed us Japanese yen through one connection and US\ndollars through another, on consecutive days. The app says as much itself:\n\"the current product prices are displayed in USD. Please restart DramaBox to\nrefresh the localized pricing.\" So a cancellation you make from a different\nregion, or a renewal processed while you are connected elsewhere, may not be\nhandling the same price you think it is. Check the currency on the receipt.\n</Callout>\n\n<h2 id=\"confirm\">Confirm it actually worked</h2>\n\n<p>\n  Do not stop at the confirmation screen. Do this:\n</p>\n\n<ul>\n  <li>Re-open the subscription list in the same place you cancelled from.</li>\n  <li>\n    Confirm the billing date is <strong>gone</strong>, or that the entry has\n    moved into an expired section.\n  </li>\n  <li>\n    Check the date it now shows. Access normally continues until the end of the\n    period you already paid for, then ends.\n  </li>\n  <li>Keep the screenshot until after that access-until date has passed.</li>\n</ul>\n\n<Callout kind=\"info\" title=\"How to tell\">\nThe entry does <strong>not</strong> disappear after cancelling — that is normal\nand not a sign of failure. A live subscription shows a next billing date; a\ncancelled one shows an access-until date instead. If a future billing date is\nstill there, the cancellation did not go through, and you should check your email\nfor a store confirmation. That email is the only reliable receipt — keep it.\n</Callout>\n\n<h2 id=\"coins\">Coins: there is nothing to cancel</h2>\n\n<p>\n  Coin packs in DramaBox are one-off purchases, not subscriptions. If you bought\n  a pack there is no recurring charge to stop, and nothing in your store\n  subscription list will ever mention it.\n</p>\n\n<p>\n  One rule matters here that is specific to this app: <strong>DramaBox spends\n  your reward coins first</strong> when you unlock an episode, as stated on the\n  in-app store page. The coins you earned from check-ins, video tasks and\n  sign-up bonuses are consumed before the coins you paid for. Practical\n  consequences: your free balance is not quietly expired by buying early, and a\n  refund request on spent coins is unlikely to succeed because part of what you\n  spent was never paid for. If you are weighing whether to cancel or just stop\n  subscribing, our\n  <a href=\"/guides/dramabox-free-coins\">free coins breakdown</a> shows what the\n  free tier covers on its own.\n</p>\n\n<Callout kind=\"info\" title=\"Coins you have not spent\">\nAny coin balance stays attached to your account if you cancel — cancelling a\nsubscription does not delete the balance. If you resubscribe later, the coins\nare still there.\n</Callout>\n\n<h2 id=\"refunds\">If you were already charged</h2>\n\n<p>\n  Cancelling stops future renewals. It does not refund a charge that already\n  went through, and it is not automatic.\n</p>\n\n<ol class=\"steps\">\n  <li>\n    <strong>Go to the store's refund route first.</strong> On iOS that is the\n    Apple \"Report a Problem\" flow; on Android it is the Play Store refund\n    request. These are the parties that processed the payment and they control\n    the outcome.\n  </li>\n  <li>\n    <strong>Cancel the subscription as well</strong>, so the refund request and\n    the renewal stop are both in place.\n  </li>\n  <li>\n    <strong>Be specific about the timeline</strong> — when you cancelled, when\n    the charge appeared, and what you were shown when you subscribed. If the\n    price you were shown differed from what was charged, say so: that gap is the\n    substance of the complaint.\n  </li>\n</ol>\n\n<p>\n  Contacting the app publisher is usually the slower path, because they cannot\n  issue refunds for store-processed payments. Use the store route first. The\n  wider pattern — why these prices move, and what to check before the first\n  payment rather than after the renewal — is in\n  <a href=\"/guides/short-drama-app-subscription-trap\">how the subscription trap\n  works</a>.\n</p>\n\n<AffiliateCTA\n  appName=\"DramaBox\"\n  href=\"https://r.reelsgo.tv/uR3A7JBLdipd\"\n  sub=\"Free to download · set a reminder before your first renewal, not after\"\n  buttonLabel=\"Open DramaBox\"\n/>\n\n<h2 id=\"limitations\">What cancelling does not do</h2>\n\n<ul>\n  <li>\n    <strong>It does not refund the current period.</strong> You keep access until\n    the period ends and you do not get that money back. For what a period\n    actually costs, see\n    <a href=\"/guides/dramabox-subscription-cost\">the price breakdown</a>.\n  </li>\n  <li>\n    <strong>It does not delete your account or your coin balance.</strong>\n    Remaining coins stay on the account, so nothing is lost if you come back.\n  </li>\n  <li>\n    <strong>It does not stop member points.</strong> It stops them. DramaBox\n    states that points are for paid members only, so cancelling ends your\n    accrual — one of the few places on these apps where leaving genuinely costs\n    you something.\n  </li>\n  <li>\n    <strong>It does not work retroactively.</strong> If the renewal already\n    processed, you are in refund territory, not cancellation territory.\n  </li>\n  <li>\n    <strong>It does not cover a subscription on a different account.</strong> If\n    DramaBox is absent from your list, check the other Apple ID or Google account\n    on the device before concluding there is nothing to cancel.\n  </li>\n</ul>\n\n<p>\n  If cancelling is not the goal and you would rather keep paying less, that is a\n  solvable problem too — the\n  <a href=\"/guides/how-to-stop-paying-for-short-drama-apps\">stop paying more than\n  you need to playbook</a> covers choosing the payment shape deliberately,\n  across apps.\n</p>\n\n<h2 id=\"bottom-line\">Bottom line</h2>\n\n<p>\n  DramaBox subscriptions cancel in the store that holds them — Google Play or\n  the App Store — not in the app, and not by deleting the app. Read the renewal\n  price before you confirm anything, because $9.99 for three weeks becomes $12.99\n  every week after that. Then go back and check that the billing date is gone and\n  an access-until date has replaced it.\n</p>","src/content/guides/how-to-cancel-dramabox-subscription.mdx","12ba21b758c65d51",{id:124,data:847,body:902,filePath:903,digest:904,deferredRender:74},{title:848,description:849,app:334,targetKeyword:850,intent:18,shortAnswer:851,publishedOn:599,updatedOn:599,priceVerifiedOn:27,toc:857,faqs:885,relatedGuides:901},"Are Short Drama Apps a Scam? What We Found Testing Six of Them","Six short drama apps tested in-app: store ratings versus real complaints. They are not scams — but the billing is aggressive. Here is how to tell the difference.","are short drama apps a scam",[852,853,854,855,856],"<strong>No, they are not scams.</strong> Six major apps keep their free content free and charge openly through the app stores. They are licensed publishers with real companies behind them, and their in-app purchases go through Apple and Google like any other app.","The trust problem is real but different: <strong>the billing is aggressive</strong>. Rotating intro discounts, renewal rates more than half again the introductory price, and automatic charges are techniques that look predatory even when the app is not a scam.","The clearest evidence: ReelShort scores <strong>4.7 on the App Store and 3.8 on Google Play, but 1.3 on Trustpilot</strong> — a 1.3 that comes from 265 reviews complaining almost entirely about billing and cancellation, not about the shows.","One thing genuinely worth calling out: the Trustpilot profile is <strong>unclaimed</strong>, meaning the company does not respond to complaints there. That is not fraud, but it is the reason bad experiences go unanswered.","The practical test: check the store listing and the renewal price before you pay. If a publisher is named, the store shows the exact charge, and the renewal terms are visible, it is a business, not a scam.",[858,859,862,865,868,871,874,877,880,883],{id:506,label:91},{id:860,label:861},"not-a-scam","What makes these apps legitimate",{id:863,label:864},"rating-gap","The 4.7 versus 1.3 gap, explained",{id:866,label:867},"what-complainants-say","What the complaints actually say",{id:869,label:870},"real-tricks","The billing tricks that are not scams",{id:872,label:873},"unclaimed-profile","The unclaimed Trustpilot profile",{id:875,label:876},"one-fair-concern","One legitimate concern",{id:878,label:879},"how-to-test","The five-minute legitimacy check",{id:881,label:882},"if-scammed","If you think you were actually scammed",{id:48,label:884},"What this assessment cannot tell you",[886,889,892,895,898],{q:887,a:888},"Are ReelShort and DramaBox scams?","No. Both are published by named companies — ReelShort by New Leaf Publishing and DramaBox by Storymatrix — and both sell through the Apple App Store and Google Play, which means Apple and Google vet the payments and can refund them. The complaints about these apps are overwhelmingly about subscription renewal and cancellation, not about the apps being fraudulent. What you are reacting to is aggressive billing design, which is a different problem and one you can defend against.",{q:890,a:891},"Why is ReelShort rated 4.7 in the app store but 1.3 on Trustpilot?","The two numbers measure different populations. App store ratings come from people who chose to install the app, and they rate the content. Trustpilot is a third-party review site people visit when they are already angry about a charge, so it collects billing complaints almost exclusively. A 1.3 built from 265 reviews about repeated charges and failed cancellations is a signal about the billing experience, not about whether the app works or whether the publisher exists.",{q:893,a:894},"Is it safe to subscribe to a short drama app?","It is safe in the sense that matters most: the payment runs through Apple or Google, not through a stranger with your card number, and you can cancel through the same store. The risk is not fraud, it is forgetting to cancel before a renewal that costs several times the introductory price. Read the renewal amount on the store subscription screen before you confirm, and set a reminder for the day before it charges.",{q:896,a:897},"What is the real complaint about short drama apps?","Four things recur across the reviews we read: a discounted first period that silently becomes a much higher renewal, charges landing before the user noticed the renewal date, difficulty finding the cancel button, and support being unreachable after the charge. All four are billing-friction complaints. None of them describe content that does not exist or payments going somewhere unexpected.",{q:899,a:900},"Are these apps free to download?","Yes, and that part is exactly as advertised. All six apps we tested install free, give away a genuine free block of episodes, and charge only when you go past it. The free-to-install model is standard for the category and is not deceptive in itself.",[68,275,123,11,70,481],"import Callout from '../../components/Callout.astro';\nimport Screenshot from '../../components/Screenshot.astro';\nimport AffiliateCTA from '../../components/AffiliateCTA.astro';\n\n<h2 id=\"verdict\">The short answer</h2>\n\n<p>\n  No. Short drama apps are not scams. That is the finding from testing six of\n  them in-app, and it is worth stating plainly because a lot of the search\n  results on this question are written by people who have not installed\n  anything.\n</p>\n\n<p>\n  They are licensed publishers with named companies behind them, they sell\n  through the Apple App Store and Google Play, and the free content they\n  promise is genuinely free. What you are actually reacting to when a\n  subscription feels like a scam is a set of billing techniques that\n  <strong>look</strong> predatory even when nothing illegal has happened.\n</p>\n\n<p>\n  Those are two different problems, and confusing them is expensive in both\n  directions: if you assume a scam you will keep paying, and if you assume it\n  is fine you will keep paying too. So here is both sides.\n</p>\n\n<h2 id=\"not-a-scam\">What makes these apps legitimate</h2>\n\n<p>\n  Legitimacy is not a vibe. It is a set of checkable facts, and all six apps we\n  tested pass them:\n</p>\n\n<ul>\n  <li>\n    <strong>A named publisher, not an anonymous listing.</strong> ReelShort is\n    published by New Leaf Publishing; DramaBox by Storymatrix; NetShort by\n    Netstory. All of them are identifiable companies with public storefronts.\n  </li>\n  <li>\n    <strong>The payment runs through Apple or Google.</strong> This is the single\n    most important fact on this page. When you subscribe, the money goes to the\n    app store, not to an unknown merchant. That means the store's refund process\n    applies, and Apple or Google can reverse a charge you did not authorise.\n  </li>\n  <li>\n    <strong>The free content is free.</strong> Every app installs free and gives\n    away a real block of episodes. No app in this category demands payment\n    before you have seen anything.\n  </li>\n  <li>\n    <strong>The store shows the exact charge.</strong> The renewal amount is\n    displayed in the store subscription screen before you confirm, which is\n    where the game this page is about is actually played.\n  </li>\n</ul>\n\n<Callout kind=\"info\" title=\"Why the store payment matters so much\">\nA scam usually needs your card number. On these apps it never gets your card\nnumber — Apple or Google handles it. That single fact removes the most common\nfraud vector in this category, and it is also why the correct response to a bad\nexperience here is a refund request through the store, not a dispute.\n</Callout>\n\n<Screenshot\n  src=\"/screenshots/reelshort-appstore-listing.webp\"\n  alt=\"ReelShort App Store listing showing a 4.7 star rating from 506 thousand ratings, developer name New Leaf Publishing, entertainment category ranking\"\n  caption=\"The App Store listing for ReelShort, checked 8 October 2026: a named developer, a visible rating count, and an identifiable publisher. This is what a legitimate listing looks like — the developer is a company you can look up, not an individual\"\n/>\n\n<h2 id=\"rating-gap\">The 4.7 versus 1.3 gap, explained</h2>\n\n<p>\n  Here is the single most useful piece of evidence on this whole question, and\n  it is the one that settles most of the argument.\n</p>\n\n<p>\n  ReelShort — the biggest app in the category — carries three ratings at once,\n  and they disagree wildly:\n</p>\n\n<table class=\"data-table\">\n  <thead>\n    <tr><th>Where</th><th>Rating</th><th>Sample</th><th>Who is rating</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>App Store (US)</td><td><strong>4.7 / 5</strong></td><td>506K ratings</td><td>People who chose to install it</td></tr>\n    <tr><td>Google Play</td><td><strong>3.8 / 5</strong></td><td>1.92M reviews</td><td>The same, on Android</td></tr>\n    <tr><td>Trustpilot</td><td><strong>1.3 / 5 (Bad)</strong></td><td>265 reviews</td><td>People arriving with a billing complaint</td></tr>\n  </tbody>\n</table>\n\n<p>\n  Read that as three different questions. The App Store rating answers\n  <em>is the content worth installing</em>. The Trustpilot rating answers\n  <em>what happens when I try to get my money back</em>. Both are true, and\n  they are not about the same thing.\n</p>\n\n<Callout kind=\"warn\" title=\"A 1.3 that is 3.4 points below the store rating is a billing signal\">\nWhen a Trustpilot score sits this far below the store score, the gap is almost\nalways about money rather than product. If the app were failing to deliver the\nshows, the App Store rating would fall too. It has not.\n</Callout>\n\n<Screenshot\n  src=\"/screenshots/reelshort-trustpilot-rating.webp\"\n  alt=\"Trustpilot page for ReelShort showing a 1.3 out of 5 rating marked Bad, from 265 reviews, with an unclaimed business profile\"\n  caption=\"ReelShort's Trustpilot profile, checked 8 October 2026: 1.3 from 265 reviews. Note the unclaimed profile line — we come back to what that means below, because it is the most actionable thing on this page\"\n/>\n\n<p>\n  The App Store numbers across the category cluster tightly, which is what you\n  would expect from a legitimate publishing model:\n</p>\n\n<table class=\"data-table\">\n  <thead>\n    <tr><th>App</th><th>Developer</th><th>Rating</th><th>Ratings</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>GoodShort</td><td>Singapore New Reading</td><td>4.90</td><td>529K</td></tr>\n    <tr><td>DramaBox</td><td>Storymatrix</td><td>4.75</td><td>872K</td></tr>\n    <tr><td>NetShort</td><td>Netstory</td><td>4.74</td><td>219K</td></tr>\n    <tr><td>ReelShort</td><td>New Leaf Publishing</td><td>4.69</td><td>506K</td></tr>\n  </tbody>\n</table>\n\n<p>\n  The full pricing picture for each app is in our\n  <a href=\"/guides/cheapest-short-drama-app\">cheapest short drama app\n  comparison</a>, and the ReelShort-specific checks are in\n  <a href=\"/guides/is-reelshort-legit\">our legitimacy review</a>.\n</p>\n\n<Callout kind=\"info\" title=\"A note on which store figure we use\">\nStore ratings drift slightly between the App Store web page and the iTunes\nlookup API, and DramaBox is a live example — both report 872K ratings but round\nto 4.8 and 4.75 respectively. We use the API figure in our comparison table\nbecause all five apps in it were pulled the same way, which keeps them\ncomparable. Either number is accurate to its source.\n</Callout>\n\n<h2 id=\"what-complainants-say\">What the complaints actually say</h2>\n\n<p>\n  We read the complaint data rather than the headlines. The complaints cluster\n  into four things, and not one of them is that the app lied about what it\n  sells.\n</p>\n\n<ul>\n  <li>\n    <strong>Repeated charges after trying to cancel.</strong> The most common\n    category. Almost always traces back to cancelling in the wrong place — the\n    app was deleted rather than the subscription, so the renewal carried on.\n  </li>\n  <li>\n    <strong>The renewal price jump.</strong> A discounted first week at $9.99\n    that becomes $12.99, or a NetShort intro at $15.99 that renews at $24.99.\n    Users describe this as bait-and-switch. It is a common industry tactic, not\n    a scam, and it is avoidable if you read the renewal figure.\n  </li>\n  <li>\n    <strong>Charges landing without warning.</strong> Google Play charges within\n    24 hours of expiry, and it does send a reminder two days before an\n    introductory price ends. The complaint is that people treat the reminder as\n    the end of the conversation rather than the start.\n  </li>\n  <li>\n    <strong>Support being unreachable after the charge.</strong> This is a real\n    failure mode, and it is the one worth being angry about — see below.\n  </li>\n</ul>\n\n<Callout kind=\"alert\" title=\"What is genuinely absent from the complaints\">\nWe looked for the serious categories — content that does not match the\nadvertising, payments to unknown merchants, accounts banned after paying,\ncrypto or gift-card demands. <strong>We found none of them in this category.</strong>\nThat absence is itself evidence: these are ordinary subscription businesses\nwith aggressive pricing, not fraud operations.\n</Callout>\n\n<h2 id=\"real-tricks\">The billing tricks that are not scams</h2>\n\n<p>\n  It is worth naming the techniques precisely, because naming them is how you\n  defend against them. Every one of these is measurable, and all of them are\n  documented in our\n  <a href=\"/guides/short-drama-app-subscription-trap\">subscription trap\n  breakdown</a>.\n</p>\n\n<h3>The rotating discount</h3>\n\n<p>\n  ReelShort showed 67% off one day and 21% off the next on the same plan. This\n  is manufactured urgency with a deadline that resets. Nothing dishonest\n  happens — the price is displayed clearly — but a discount that changes daily\n  removes the basis for a considered decision.\n</p>\n\n<h3>The intro-to-renewal jump</h3>\n\n<table class=\"data-table\">\n  <thead>\n    <tr><th>App</th><th>Introductory price</th><th>Then it renews at</th><th>Rise</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>DramaBox</td><td>$9.99/week for 3 weeks</td><td>$12.99/week</td><td>+30%</td></tr>\n    <tr><td>NetShort</td><td>$15.99 first week</td><td>$24.99/week</td><td>+56%</td></tr>\n    <tr><td>ShortMax</td><td>$12.79/week for 2 weeks</td><td>$19.99/week</td><td>+56%</td></tr>\n  </tbody>\n</table>\n\n<p>\n  Up to 56% more than the price you agreed to. This is the single most\n  important number to read before subscribing anywhere in this category.\n</p>\n\n<h3>The two-checkout problem</h3>\n\n<p>\n  One ReelShort Weekly VIP plan showed $10.99 inside the app and $11.87 at web\n  checkout on the same day — and the web page additionally disclosed a renewal\n  of $20.51 a week. Three prices for one plan in one day, none of them hidden,\n  all of them different. Our\n  <a href=\"/guides/why-short-drama-app-prices-differ\">price differences\n  breakdown</a> covers why this happens.\n</p>\n\n<Callout kind=\"warn\" title=\"The defence that takes ten seconds\">\nOpen your store's subscription list before subscribing and read the renewal\namount. Not the promotional price — the renewal price. If the two differ, that\ndifference is the entire cost of the month. Our\n<a href=\"/guides/how-to-cancel-reelshort-subscription\">cancellation guide</a>\ncovers the store-specific steps for both platforms.\n</Callout>\n\n<h2 id=\"unclaimed-profile\">The unclaimed Trustpilot profile</h2>\n\n<p>\n  This is the most concrete thing we found, and it is a criticism rather than\n  an accusation.\n</p>\n\n<p>\n  ReelShort's Trustpilot profile is marked <strong>unclaimed</strong>, which\n  means the company has not verified and does not answer reviews there. Not one\n  of the 265 reviews has an official response.\n</p>\n\n<p>\n  Read that against the complaint themes: people report being unable to reach\n  customer support after a charge, and the one public channel where a response\n  would be visible to other prospective buyers is one the company has not\n  engaged with. That is a service failure, and it is why a 1.3 persists on the\n  one platform where a company can answer.\n</p>\n\n<Callout kind=\"info\" title=\"This is not unique, and it is not fraud\">\nAn unclaimed profile is extremely common across app-based businesses — it is\nsimply not worth the staffing for a review site most customers never visit. It\ndoes not make a company illegitimate. It does mean the absence of replies there\nshould not be read as evidence of guilt.\n</Callout>\n\n<h2 id=\"one-fair-concern\">One legitimate concern</h2>\n\n<p>\n  We would rather flag this than let the page read as a defence of everything.\n</p>\n\n<p>\n  <strong>DramaBox carries an 18+ rating in the US App Store while ReelShort is\n  13+.</strong> Both are episodic video drama apps; the difference in\n  classification is a licensing and content-standards difference, not a quality\n  judgement. But it means parental controls and some device configurations\n  treat them differently, and it is the kind of thing a buyer should know\n  before installing.\n</p>\n\n<p>\n  Separately, the category's content is predominantly dubbed rather than\n  originally English-language, and audio quality varies by title. Nobody is\n  misrepresenting that — the store listings make the content type clear — but\n  it is the most common reason people feel they were not quite sure what they\n  were buying.\n</p>\n\n<h2 id=\"how-to-test\">The five-minute legitimacy check</h2>\n\n<p>\n  Rather than trusting anyone's verdict, including ours, run this on any app in\n  this category before you subscribe. All five checks take about five minutes.\n</p>\n\n<ol class=\"steps\">\n  <li>\n    <strong>Look for a named developer.</strong> In the store listing. A company\n    name you can look up is the foundation of everything else; no name, no deal.\n  </li>\n  <li>\n    <strong>Confirm the payment goes through the store.</strong> If checkout\n    happens inside the app with a card form for an unverified merchant, that is\n    the actual scam signal. If it hands off to Apple or Google, you are protected.\n  </li>\n  <li>\n    <strong>Read the renewal amount in the store subscription screen.</strong> Not\n    the price on the sales screen. This is where the real cost lives.\n  </li>\n  <li>\n    <strong>Check whether the ratings agree with each other.</strong> A 4.7 in\n    the store and a 1.3 elsewhere is a billing complaint. A 4.7 and a 1.0 with\n    the same complaint text is something else.\n  </li>\n  <li>\n    <strong>See whether the free block is real.</strong> Install, do not pay,\n    and count the episodes before the paywall. If the free content is a single\n    episode or a preview only, the listing is not being straight with you.\n  </li>\n</ol>\n\n<Callout kind=\"info\" title=\"How we ran this same check\">\nEvery figure on this page came from the apps themselves on Android and from\npublic store and review pages, recorded in October 2026 and kept in a dated\nprice log with every source screenshot attached. Prices and ratings change often —\nre-check before relying on any single number.\n</Callout>\n\n<h2 id=\"if-scammed\">If you think you were actually scammed</h2>\n\n<p>\n  There is a difference between overpaying and being defrauded, and the second\n  one needs a different response.\n</p>\n\n<p>\n  <strong>If you were charged for a renewal after trying to cancel</strong>, that\n  is almost always the wrong-place problem rather than fraud. Go back into the\n  store's subscription list, cancel it there, and screenshot the confirmation.\n  Then request the refund through the same store.\n</p>\n\n<p>\n  <strong>If you were charged by a merchant you do not recognise</strong> on your\n  card statement, that is a different situation and worth acting on immediately:\n  contact your bank's card issuer to dispute it, and change the card. Genuine\n  in-app purchases trace to Apple or Google, so an unfamiliar merchant name is\n  genuinely abnormal.\n</p>\n\n<p>\n  In both cases the store is the party that processed the payment and the party\n  that controls the outcome. Our\n  <a href=\"/guides/how-to-cancel-dramabox-subscription\">cancellation guide</a>\n  has the step-by-step for both platforms, including how to phrase a refund\n  request.\n</p>\n\n<AffiliateCTA\n  appName=\"ReelShort\"\n  href=\"https://r.reelsgo.tv/1vwtyh4hj9R3\"\n  sub=\"Free to download · read the renewal price before you subscribe\"\n/>\n\n<h2 id=\"limitations\">What this assessment cannot tell you</h2>\n\n<ul>\n  <li>\n    <strong>Six apps, one platform each.</strong> We tested on Android plus\n    public store pages. We did not run through every title in every catalogue.\n  </li>\n  <li>\n    <strong>Ratings move daily.</strong> Every score here is a snapshot from\n    October 2026. Store ratings in this category are large-sample and relatively\n    stable, but they do change.\n  </li>\n  <li>\n    <strong>We did not read every review.</strong> The complaint themes are from\n    the AI summary and the top-discussed topics on ReelShort's Trustpilot page,\n    plus patterns across the category. Individual outliers were not audited.\n  </li>\n  <li>\n    <strong>We are not a consumer watchdog.</strong> We are a price-comparison\n    site. Our incentive is to help you spend less accurately, which is why every\n    claim on this page is tied to a number we can show a screenshot of.\n  </li>\n</ul>\n\n<h2 id=\"bottom-line\">Bottom line</h2>\n\n<p>\n  Short drama apps are not scams. They are ordinary subscription businesses:\n  named publishers, store-handled payments, genuinely free content, and\n  customers who mostly rate them around 4.7.\n</p>\n\n<p>\n  What they are is <strong>aggressively priced</strong> — intro discounts that\n  rotate daily, renewal rates up to 56% higher than the price you clicked on,\n  and a billing flow that assumes you will not read the second number. The\n  complaints are real and they deserve an answer; they just are not evidence of\n  fraud.\n</p>\n\n<p>\n  So the useful posture is not suspicion, it is arithmetic: read the renewal\n  amount, set a reminder, and cancel through the store when the run is over. The\n  apps are not out to take your money by deception — they are betting you will\n  not read the second price, which is a bet you can beat in ten seconds.\n</p>","src/content/guides/are-short-drama-apps-a-scam.mdx","6bba67c2da305997",{id:226,data:906,body:965,filePath:966,digest:967,deferredRender:74},{title:907,description:908,app:16,targetKeyword:909,intent:18,shortAnswer:910,publishedOn:917,updatedOn:917,priceVerifiedOn:27,toc:918,faqs:945,relatedGuides:964},"ReelShort Cost Per Episode: What One Episode Actually Costs","One ReelShort episode costs 60 coins. What that works out to per episode at every coin pack price, from $0.60 on the smallest pack down to $0.40 on the largest.","reelshort cost per episode",[911,912,913,914,915,916],"One locked ReelShort episode costs <strong>60 coins</strong>. That is the price of an episode before you have bought anything — the app tells you this figure, it does not vary by series or tier.","What it works out to depends entirely on which pack you buy: <strong>$0.60 per episode</strong> on the $4.99 pack, down to <strong>$0.40 on the $49.99 pack</strong>.","That 50% spread is the single most useful number on this page. The episode costs the same 60 coins either way — you are paying for the price of the pack, not the price of the episode.","A $49.99 pack holds 7,500 coins, which is <strong>exactly 125 episodes</strong> and nothing left over.","For a typical 54-episode series with about 10 free, finishing it costs roughly <strong>$17.60–$20.30 in coins</strong> depending on the pack.","If you will watch more than roughly 5 episodes, a subscription undercuts coins — see our ReelShort price breakdown for where the line sits.","2026-10-18",[919,922,925,928,931,934,937,940,943],{id:920,label:921},"one-number","The one number that matters",{id:923,label:924},"what-it-works-out-to","What 60 coins works out to",{id:926,label:927},"the-spread","The 50% spread between packs",{id:929,label:930},"the-7500-pack","Why the $49.99 pack is the efficient one",{id:932,label:933},"a-whole-series","Working a whole series through",{id:935,label:936},"coins-vs-subscription","When coins stop being the answer",{id:938,label:939},"the-trap","The trap: the small pack is the one you see first",{id:941,label:942},"other-apps","How DramaBox compares per episode",{id:48,label:944},"What this arithmetic cannot tell you",[946,949,952,955,958,961],{q:947,a:948},"How much is one episode on ReelShort in dollars?","It depends on which coin pack you bought, and the spread is wide. A locked episode costs 60 coins. That works out to $0.60 per episode on the $4.99 pack, $0.50 on the $19.99 pack, and $0.40 on the $49.99 pack. All three are correct — the episode is 60 coins in every case, so the per-episode dollar cost is entirely decided by the price of the pack you purchased.",{q:950,a:951},"Why do different ReelShort coin packs give different value?","Because larger packs include a bonus: the $9.99 pack holds 1,100 coins rather than 1,000, the $49.99 pack holds 7,500 rather than 5,000. The per-coin price therefore falls steadily as packs get larger, from about one cent down to about two thirds of a cent. The smallest pack is the worst deal by that measure — it exists mainly because it is the easiest number to say yes to.",{q:953,a:954},"How many episodes can I watch for $49.99 on ReelShort?","The $49.99 pack holds 7,500 coins at 60 coins per episode, which is exactly 125 episodes with nothing left over. It is the only pack where the arithmetic comes out clean, which makes it easy to reason about but also easy to overspend — 125 episodes is a lot more than most people watch.",{q:956,a:957},"Is it cheaper to buy coins or subscribe on ReelShort?","For finishing a single series, coins usually win: roughly $17.60 to $20.30 for a typical 54-episode title with about 10 episodes free. Once you are watching several series a month, a weekly subscription undercuts that quickly, because it is unlimited rather than metered. The break-even sits at around five episodes on a single-series basis, and our price breakdown works the full comparison.",{q:959,a:960},"Which is cheaper per episode, ReelShort or DramaBox?","DramaBox, on both counts. It charges 50 coins per episode against ReelShort's 60, its entry pack is $2.99 against $4.99, and its best per-episode rate is $0.36 against ReelShort's $0.40 — DramaBox's largest pack carries a 40% bonus and costs half as much to start with. ReelShort does have the cleaner arithmetic: its $49.99 pack divides into exactly 125 episodes with nothing stranded. Cheaper is DramaBox, easier to plan is ReelShort.",{q:962,a:963},"Is the 60-coin price the same on every series?","Yes — ReelShort charges 60 coins per locked episode regardless of the series, its length or its production value. The figure appears on the paywall itself. What varies between series is how many episodes are free before that paywall, which ranged from about 10 on a 54-episode title to 16 on an 81-episode one in our testing.",[67,685,180,69,177,179],"import Callout from '../../components/Callout.astro';\nimport Screenshot from '../../components/Screenshot.astro';\nimport AffiliateCTA from '../../components/AffiliateCTA.astro';\n\n<h2 id=\"one-number\">The one number that matters</h2>\n\n<p>\n  Every locked episode on ReelShort costs <strong>60 coins</strong>. The\n  paywall states it outright, and it does not change with the series, its\n  length or its production budget. A dubbed two-minute vertical drama and a\n  licensed K-drama adaptation sit behind the same 60 coins.\n</p>\n\n<p>\n  That figure alone is not very useful on its own, because coins are not\n  dollars. What makes it useful is dividing it by the price of the pack you\n  actually bought — and that produces the most surprising number on this page.\n</p>\n\n<Screenshot\n  src=\"/screenshots/reelshort-coin-packs.webp\"\n  alt=\"ReelShort coin pack refill screen showing five tiers from 500 coins for 4.99 dollars up to 5,000 plus 2,500 bonus coins for 49.99 dollars\"\n  caption=\"The ReelShort coin refill screen on Android, 9 October 2026. Five tiers, and the price per coin falls the whole way down the list — the smallest pack is the most expensive per episode on the screen\"\n/>\n\n<h2 id=\"what-it-works-out-to\">What 60 coins works out to</h2>\n\n<p>\n  Here is the whole thing in one table. We priced every tier in-app and divided\n  the pack price by the coins it delivers, then multiplied by 60:\n</p>\n\n<table class=\"data-table\">\n  <thead>\n    <tr><th>Pack</th><th>Price</th><th>Coins (incl. bonus)</th><th>Per coin</th><th><strong>Per episode</strong></th></tr>\n  </thead>\n  <tbody>\n    <tr><td>Smallest</td><td>$4.99</td><td>500</td><td>$0.0100</td><td><strong>$0.60</strong></td></tr>\n    <tr><td>1,000 + 100</td><td>$9.99</td><td>1,100</td><td>$0.0091</td><td><strong>$0.54</strong></td></tr>\n    <tr><td>2,000 + 400</td><td>$19.99</td><td>2,400</td><td>$0.0083</td><td><strong>$0.50</strong></td></tr>\n    <tr><td>3,000 + 900</td><td>$29.99</td><td>3,900</td><td>$0.0077</td><td><strong>$0.46</strong></td></tr>\n    <tr><td>Largest</td><td>$49.99</td><td>7,500</td><td>$0.0067</td><td><strong>$0.40</strong></td></tr>\n  </tbody>\n</table>\n\n<p>\n  Read the last column top to bottom: <strong>$0.60, $0.54, $0.50, $0.46,\n  $0.40</strong>. Twenty cents separates the most expensive way to buy an\n  episode from the cheapest, for an episode that costs exactly the same either\n  way.\n</p>\n\n<h2 id=\"the-spread\">The 50% spread between packs</h2>\n\n<p>\n  The smallest pack charges <strong>$0.60</strong> per episode. The largest\n  charges <strong>$0.40</strong>. The large pack is therefore\n  <strong>50% cheaper per episode</strong> — which makes the intuitive move,\n  starting small \"just to test it\", the most expensive way to buy.\n</p>\n\n<p>\n  This is the practical form of the argument: your cost per episode is decided\n  entirely by your first purchase, and you cannot change it afterwards.\n</p>\n\n<Callout kind=\"warn\" title=\"The test-the-waters instinct costs you 50%\">\nPaying $4.99 to \"see whether I like it\" and then continuing on that pack means\nevery episode you ever watch costs $0.60. The identical viewing on the $49.99\npack costs $0.40 — and ReelShort does not credit the difference or convert it.\n</Callout>\n\n<p>\n  The mechanical reason is in the bonus structure, which is worth seeing\n  plainly because it is not obvious from the pack labels:\n</p>\n\n<ul>\n  <li>The $4.99 pack gives you <strong>500 coins for 500</strong> — no bonus.</li>\n  <li>The $9.99 pack is labelled \"1,000\" but delivers <strong>1,100</strong>.</li>\n  <li>The $49.99 pack is labelled \"5,000\" but delivers <strong>7,500</strong> — a 50% bonus, by far the largest in the list.</li>\n</ul>\n\n<Callout kind=\"alert\" title=\"The label is not the amount\">\nRead ReelShort's pack labels carefully: the headline number is what you\n<em>pay for</em>, and the bonus is added on top. A pack advertised as 5,000\ncoins costs $49.99 and gives you 7,500. This is also where our own earlier\nnote was wrong — we initially recorded only three tiers because the smaller\npacks are not shown on the main store page. They exist, inside the locked-episode\nrecharge flow, and they are the worst value on the screen.\n</Callout>\n\n<h2 id=\"the-7500-pack\">Why the $49.99 pack is the efficient one</h2>\n\n<p>\n  The largest pack has the lowest cost per coin, and it is also the only one\n  where the arithmetic lands on a whole number:\n</p>\n\n<p>\n  <strong>7,500 coins ÷ 60 coins per episode = exactly 125 episodes.</strong> No\n  remainder, no coins stranded in your balance that you will never spend.\n</p>\n\n<p>\n  That is genuinely convenient for planning, and it is also precisely how the\n  pack is designed to work on you: 125 episodes is a long way past the point\n  where most people stop, and the balance sits in your account looking like a\n  small asset rather than leftover cash.\n</p>\n\n<Callout kind=\"info\" title=\"When the big pack is the wrong call\">\nThe large pack wins on unit price and loses on exposure. If you might watch five\nepisodes, $49.99 buys 125 of them. Judge it on the series you are actually\nabout to watch — and remember that most of that series is free, so your coin\nspend starts at the paywall, not at episode one.\n</Callout>\n\n<h2 id=\"a-whole-series\">Working a whole series through</h2>\n\n<p>\n  Single-episode arithmetic becomes concrete once it is attached to an actual\n  series. Two examples from our testing:\n</p>\n\n<h3>A 54-episode series with about 10 free</h3>\n\n<p>\n  That leaves roughly 44 episodes to unlock, or\n  <strong>44 × 60 = 2,640 coins</strong>. Two packs cover it:\n</p>\n\n<table class=\"data-table\">\n  <thead>\n    <tr><th>Route</th><th>Pack bought</th><th>Per episode</th><th>Total for the series</th><th>Coins left over</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>Smaller route</td><td>$29.99 (3,900)</td><td>$0.46</td><td><strong>$20.30</strong></td><td>1,260</td></tr>\n    <tr><td>Larger route</td><td>$49.99 (7,500)</td><td>$0.40</td><td><strong>$17.60</strong></td><td>4,860</td></tr>\n  </tbody>\n</table>\n\n<h3>An 81-episode series with about 16 free</h3>\n\n<p>\n  That leaves roughly 65 episodes, or <strong>3,900 coins</strong> — which is\n  exactly one $29.99 pack. Finishing this one costs\n  <strong>$29.99</strong> on the smaller pack and <strong>$25.99</strong> on the\n  larger.\n</p>\n\n<p>\n  The pattern across both: <strong>finishing one series with coins lands between\n  roughly $17 and $30</strong>, and the pack you choose moves that figure by a\n  few dollars rather than by tens.\n</p>\n\n<Screenshot\n  src=\"/screenshots/reelshort-episode-free-boundary.webp\"\n  alt=\"ReelShort episode list showing the transition from free episodes to locked episodes marked with a padlock icon\"\n  caption=\"The free boundary on ReelShort, Android, October 2026. Roughly 10 episodes on this 54-episode title, about 16 on the 81-episode one — your coin spend starts here, not at episode one\"\n/>\n\n<Callout kind=\"info\" title=\"How we checked the free boundary\">\nThe count is not published anywhere and it moves from title to title: we\nmeasured about 10 free episodes on a 54-episode series and 16 on an 81-episode\none. Open the episode list and scroll to the first padlock before you commit to\nbuying anything. Our\n<a href=\"/guides/short-drama-app-most-free-episodes\">free-episode survey</a>\ncovers what six apps gave us.\n</Callout>\n\n<h2 id=\"coins-vs-subscription\">When coins stop being the answer</h2>\n\n<p>\n  The per-episode figures above assume you are finishing one series and\n  stopping. If you finish several, the arithmetic inverts, because a\n  subscription is a ceiling rather than a meter.\n</p>\n\n<p>\n  At $0.46 per episode, a second series costs another $12–14 in coins. A weekly\n  membership covers unlimited series for $9.99 to $12.99. So the coin route\n  stays ahead for roughly the first series and loses after that, and the\n  crossover is easy to calculate for your own case.\n</p>\n\n<p>\n  Our <a href=\"/guides/reelshort-price-explained\">ReelShort price\n  breakdown</a> works through both payment shapes properly, and\n  <a href=\"/guides/reelshort-coins-vs-vip\">coins versus VIP</a> isolates which\n  of the two paid layers is being wasted.\n</p>\n\n<AffiliateCTA\n  appName=\"ReelShort\"\n  href=\"https://r.reelsgo.tv/1vwtyh4hj9R3\"\n  sub=\"Free to download · one episode is 60 coins, so the pack decides the price\"\n/>\n\n<h2 id=\"the-trap\">The trap: the small pack is the one you see first</h2>\n\n<p>\n  This deserves naming as a design choice rather than an accusation, because it\n  is entirely legal and widely used across the category.\n</p>\n\n<p>\n  The smallest pack is what a new user meets first, and it is the worst deal on\n  the screen at $0.60 per episode. The best deal — the $49.99 pack at $0.40 —\n  is the one that requires committing to the largest number before you know\n  whether you will watch more than five episodes.\n</p>\n\n<p>\n  There is a second, smaller version of the same thing worth knowing: the\n  smaller packs are not shown on the main store page at all. They live inside\n  the locked-episode recharge flow, which is where most people actually buy. We\n  missed them for the same reason — we originally logged only three tiers\n  because we read the main store page.\n</p>\n\n<Callout kind=\"alert\" title=\"What is genuinely hidden, and what is not\">\nBeing fair here: the bonus coins are stated in the pack label, the per-coin\nrate is arithmetic anyone can do, and the renewal terms appear in your store\nsubscription screen. Nothing is concealed — the design simply makes the worst\nvalue the easiest to reach. That is worth knowing precisely because you can\nthen choose the other one deliberately.\n</Callout>\n\n<h2 id=\"other-apps\">How DramaBox compares per episode</h2>\n\n<p>\n  The comparison most price lists stop short of is the one that matters: not\n  coin price, but <strong>per-episode cost at each pack tier</strong>. DramaBox\n  charges <strong>50 coins per episode</strong> against ReelShort's 60, and the\n  packages diverge from there.\n</p>\n\n<table class=\"data-table\">\n  <thead>\n    <tr><th>App</th><th>Coins per episode</th><th>Cheapest pack</th><th>Per episode there</th><th>Largest pack</th><th>Best per episode</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>ReelShort</td><td>60</td><td>$4.99 / 500</td><td>$0.60</td><td>$49.99 / 7,500</td><td><strong>$0.40</strong></td></tr>\n    <tr><td>DramaBox</td><td>50</td><td>$2.99 / 300</td><td>$0.50</td><td>$24.99 / 3,500</td><td><strong>$0.36</strong></td></tr>\n  </tbody>\n</table>\n\n<p>\n  DramaBox wins on both rows. Its headline per-episode coin price is 17% lower,\n  its entry pack is cheaper at $2.99 against $4.99, and — the number most\n  comparisons miss — <strong>its best per-episode rate is $0.36 against\n  ReelShort's $0.40</strong>, because DramaBox's largest pack carries a 40%\n  bonus and costs half as much to begin with.\n</p>\n\n<p>\n  So the honest summary: <strong>DramaBox is cheaper per episode at both ends of\n  the range.</strong> ReelShort's $49.99 pack has the cleaner arithmetic — 125\n  episodes exactly, no remainder — which makes it easier to plan, but it is not\n  the better price. If per-episode cost is the only question,\n  <a href=\"/guides/reelshort-vs-dramabox\">DramaBox comes out ahead</a>.\n</p>\n\n<Callout kind=\"info\" title=\"The takeaway most price lists miss\">\nComparing coin packages across apps by dividing price by coins looks rigorous\nand is usually wrong, because it silently assumes you buy the largest pack\neverywhere. Decide the pack first, then compare.\n</Callout>\n\n<h2 id=\"limitations\">What this arithmetic cannot tell you</h2>\n\n<ul>\n  <li>\n    <strong>Prices rotate.</strong> The intro discounts in this category change\n    day to day — we saw ReelShort at 67% off one day and 21% off the next. Coin\n    pack prices are more stable than VIP tiers but they are not fixed, so\n    re-check before a large purchase.\n  </li>\n  <li>\n    <strong>Every figure is Android, October 2026.</strong> We did not verify\n    these tiers on iOS, and the store surfaces differ.\n  </li>\n  <li>\n    <strong>Free-episode counts are samples, not rules.</strong> Two titles gave\n    us 10 and 16. ReelShort publishes nothing, so your series may differ.\n  </li>\n  <li>\n    <strong>This page ignores subscriptions entirely</strong>, and for anything\n    beyond one series that is the wrong frame. Use it to price coins, then read\n    the price breakdown before deciding how to pay.\n  </li>\n</ul>\n\n<h2 id=\"bottom-line\">Bottom line</h2>\n\n<p>\n  One ReelShort episode costs <strong>60 coins</strong>, and that number never\n  moves. What moves is what a coin is worth, which depends on the pack you\n  bought:\n</p>\n\n<p>\n  <strong>$0.60</strong> per episode on the $4.99 pack.\n  <strong>$0.50</strong> on the $19.99 pack.\n  <strong>$0.40</strong> on the $49.99 pack — exactly 125 episodes, no coins\n  stranded.\n</p>\n\n<p>\n  So the practical rule is short: <strong>buy the pack that matches how many\n  episodes you will actually watch, and never buy the small pack twice.</strong>\n  For finishing a single series, $17.60–$20.30 in coins is the realistic range.\n  Past that, a subscription undercuts it, and the crossover is around five\n  episodes.\n</p>","src/content/guides/reelshort-cost-per-episode.mdx","bb141a0e8bc75b96",{id:326,data:969,body:1023,filePath:1024,digest:1025,deferredRender:74},{title:970,description:971,app:283,targetKeyword:972,intent:236,shortAnswer:973,publishedOn:917,updatedOn:917,priceVerifiedOn:27,toc:980,faqs:1006,relatedGuides:1022},"DramaBox vs GoodShort: Which One Costs Less to Watch","DramaBox and GoodShort both charge 50 coins per episode, but their weekly plans differ by $7 and their annual passes by $30. Both priced in-app, October 2026.","dramabox vs goodshort",[974,975,976,977,978,979],"Per episode they are almost identical: both charge <strong>50 coins</strong>, and the cheapest rate works out to <strong>$0.36 on DramaBox against $0.37 on GoodShort</strong> — a 4% gap that is not worth switching for.","Subscriptions are where they separate. DramaBox charges <strong>$9.99/week for three weeks then $12.99</strong>, with an annual pass at <strong>$119.99</strong>. GoodShort charges <strong>$19.99/week and $149.99/year</strong>.","That is a <strong>$30 annual difference and a $7 weekly difference</strong> — the real reason to pick DramaBox, not the coin maths.","GoodShort is more generous before you pay: <strong>7 ad unlocks a day against DramaBox 8</strong> is the only category where GoodShort is behind, but its <strong>seven-day check-in pays 320 coins against DramaBox 165</strong> — nearly double.","We could not verify GoodShort's second-week price. Its promo popup says \"US$ 19.99/w for 3 weeks, then /w\" and the renewal figure is <strong>missing from the text</strong>. Assume you pay $19.99 until you see otherwise.","For finishing one series, DramaBox is cheaper. For a daily habit spread across several series, the gap widens in its favour.",[981,983,986,989,992,995,998,1001,1004],{id:982,label:91},"quick-answer",{id:984,label:985},"per-episode","Per episode: a dead heat",{id:987,label:988},"subscriptions","Subscriptions: the real gap",{id:990,label:991},"annual-breakdown","What the annual pass actually buys",{id:993,label:994},"free-tier","The free tier: where GoodShort wins",{id:996,label:997},"one-series","Finishing one series, worked through",{id:999,label:1000},"missing-price","The price we could not verify",{id:1002,label:1003},"which-one","Which one to pick",{id:48,label:1005},"What this comparison cannot tell you",[1007,1010,1013,1016,1019],{q:1008,a:1009},"Is GoodShort cheaper than DramaBox?","No. GoodShort costs $19.99 a week and $149.99 a year, against DramaBox at $9.99 a week for three weeks then $12.99, and $119.99 a year. GoodShort's coin packs are almost identical to DramaBox's — both charge 50 coins per episode, and the best rate is $0.36 on DramaBox against $0.37 on GoodShort. DramaBox is cheaper on subscriptions and effectively equal on coins.",{q:1011,a:1012},"How much is one episode on DramaBox vs GoodShort?","Exactly the same coin price: 50 coins on both. What differs is what a coin costs, which depends on the pack. On the cheapest pack both are $0.50 per episode. On the largest pack DramaBox works out at $0.36 and GoodShort at $0.37. Because the coin price is identical, the episode price is nearly identical too — the difference between these two apps is in the subscriptions, not the coins.",{q:1014,a:1015},"Which app has more free episodes?","DramaBox, in our testing. Its series was free from episode 1 and hit the paywall at episode 12 — about 11 free episodes. GoodShort was free from episode 1 to episode 7 before locking, about 7. Neither app publishes its free block and both vary by title, so treat these as measured samples rather than fixed rules.",{q:1017,a:1018},"Can I cancel a GoodShort subscription?","As with every app in this category, cancelling goes through the store you subscribed on — Google Play or the App Store — rather than inside the app. GoodShort's own listing says \"Cancel anytime\". One caveat specific to GoodShort: we could not confirm what it renews at after the promotional weeks, because the figure is missing from its promo text.",{q:1020,a:1021},"Is GoodShort worth it over DramaBox?","Only for one specific reason: its check-in pays 320 coins across seven days against DramaBox's 165. If you open the app daily and collect them, that gap is real money. In exchange you pay $30 more a year and get fewer free episodes before the paywall. For most people finishing one or two series, DramaBox is the better buy.",[274,739,177,481,179],"import Callout from '../../components/Callout.astro';\nimport Screenshot from '../../components/Screenshot.astro';\nimport AffiliateCTA from '../../components/AffiliateCTA.astro';\n\n<h2 id=\"quick-answer\">The short answer</h2>\n\n<p>\n  These two apps are much closer than the price tags suggest, and the closeness\n  is the useful finding. Both charge <strong>50 coins per locked episode</strong>\n  — identical, episode for episode. If you buy coins, you are buying the same\n  thing on either app.\n</p>\n\n<p>\n  Where they diverge is the subscription. DramaBox sells weekly access at\n  <strong>$9.99 for three weeks and $12.99 after that</strong>, with an annual\n  pass at <strong>$119.99</strong>. GoodShort charges <strong>$19.99 a week and\n  $149.99 a year</strong>. That is a <strong>$30 gap on the annual pass</strong>\n  and <strong>$7 a week</strong> — and it is the whole reason to choose between\n  them.\n</p>\n\n<Callout kind=\"info\" title=\"One honest caveat before the tables\">\nGoodShort's promotional popup reads \"US$ 19.99/w for 3 weeks, then /w\" — and\n<strong>the renewal price is simply missing from that sentence</strong>. We\nphotographed it (see below) and could not resolve it. So on GoodShort we can\nonly confirm the first price. Everything below treats $19.99 as the ongoing\nweekly figure, which is the worst-case assumption.\n</Callout>\n\n<h2 id=\"per-episode\">Per episode: a dead heat</h2>\n\n<p>\n  Both apps charge 50 coins per episode. The cost of an episode therefore\n  depends entirely on the coin pack you buy, and here is what that works out to\n  on each app:\n</p>\n\n<table class=\"data-table\">\n  <thead>\n    <tr><th>Coins bought</th><th>DramaBox</th><th>Per episode</th><th>GoodShort</th><th>Per episode</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>Smallest pack</td><td>$2.99 / 300</td><td>$0.50</td><td>$4.99 / 500</td><td>$0.50</td></tr>\n    <tr><td>Second tier</td><td>$6.99 / 770</td><td>$0.45</td><td>$9.99 / 1,050</td><td>$0.48</td></tr>\n    <tr><td>Third tier</td><td>$12.99 / 1,600</td><td>$0.41</td><td>$19.99 / 2,200</td><td>$0.45</td></tr>\n    <tr><td>Largest pack</td><td>$24.99 / 3,500</td><td><strong>$0.36</strong></td><td>$29.99 / 4,050</td><td><strong>$0.37</strong></td></tr>\n  </tbody>\n</table>\n\n<p>\n  The interesting detail is that <strong>the smallest pack is identical on both\n  apps — $0.50 per episode</strong>. From there they diverge slightly and then\n  converge again: <strong>4% apart at the best rate</strong>. That is not a\n  meaningful gap. Nobody should switch apps over four cents.\n</p>\n\n<p>\n  Both apps label their bonus percentages openly, and GoodShort is arguably\n  cleaner about it: its packs carry explicit +5%, +10% and +35% badges.\n</p>\n\n<Callout kind=\"warn\" title=\"The real difference is not the coins\">\nIf you are deciding between these two apps on the strength of a per-episode\ntable, the table is telling you they are the same. They are. Pick on the\nsubscription price and the free tier instead.\n</Callout>\n\n<Screenshot\n  src=\"/screenshots/dramabox-store-plans.webp\"\n  alt=\"DramaBox in-app store showing coin packs from $2.99 for 300 coins up to $24.99 for 3,500 coins alongside membership offers\"\n  caption=\"DramaBox coin packs on Android, 9 October 2026. The largest pack gives 3,500 coins for $24.99, which works out at $0.36 per episode at 50 coins each\"\n/>\n\n<h2 id=\"subscriptions\">Subscriptions: the real gap</h2>\n\n<p>\n  This is the table that decides the comparison. Both apps sell unlimited\n  access, and one of them charges considerably less for it:\n</p>\n\n<table class=\"data-table\">\n  <thead>\n    <tr><th>Plan</th><th>DramaBox</th><th>GoodShort</th><th>Difference</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>Weekly — intro</td><td><strong>$9.99 for 3 weeks</strong></td><td>$19.99</td><td>DramaBox $10.00 cheaper</td></tr>\n    <tr><td>Weekly — ongoing</td><td><strong>$12.99</strong></td><td><strong>$19.99</strong> ⚠️ unconfirmed</td><td>DramaBox $7.00 cheaper</td></tr>\n    <tr><td>Annual</td><td><strong>$119.99</strong></td><td>$149.99</td><td><strong>DramaBox $30.00 cheaper</strong></td></tr>\n    <tr><td>Annual, as a daily rate</td><td>$0.33/day</td><td>$0.41/day</td><td>DramaBox 21% cheaper</td></tr>\n  </tbody>\n</table>\n\n<p>\n  The annual gap is the one to hold on to: <strong>$119.99 against $149.99 is\n  $30, and GoodShort's is 25% higher</strong> than DramaBox's. Both apps run the\n  same \"unlock all series\" model, so on a pure value comparison the subscription\n  is where the decision gets made.\n</p>\n\n<Screenshot\n  src=\"/screenshots/goodshort-store-plans.webp\"\n  alt=\"GoodShort store plans screen showing Weekly VIP at 19.99 dollars and Yearly VIP at 149.99 dollars alongside coin packs\"\n  caption=\"GoodShort's store on Android, 9 October 2026: Weekly VIP at $19.99 and Yearly VIP at $149.99. Note the weekly price matches ShortMax exactly — pricing across this category has converged hard\"\n/>\n\n<h2 id=\"annual-breakdown\">What the annual pass actually buys</h2>\n\n<p>\n  Since both annual passes claim \"unlock every series\", the useful question is\n  how many series each one pays for.\n</p>\n\n<table class=\"data-table\">\n  <thead>\n    <tr><th></th><th>DramaBox annual</th><th>GoodShort annual</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>Price</td><td>$119.99</td><td>$149.99</td></tr>\n    <tr><td>Weekly equivalent</td><td>$2.31/week</td><td>$2.88/week</td></tr>\n    <tr><td>Daily equivalent</td><td>$0.33/day</td><td>$0.41/day</td></tr>\n    <tr><td>What it covers</td><td>Unlimited series for a year</td><td>Unlimited series for a year</td></tr>\n  </tbody>\n</table>\n\n<p>\n  The two passes are the same product at different prices, so the honest way to\n  judge them is against what you would otherwise spend. Finishing series with\n  coins costs roughly <strong>$9.99–$24.99 each on DramaBox</strong> and\n  <strong>$15.92–$29.99 on GoodShort</strong> — so GoodShort's $149.99 annual\n  pass only makes sense once you would have spent more than that on coins, which\n  for GoodShort means roughly five or more series.\n</p>\n\n<p>\n  DramaBox reaches that point sooner. On the same arithmetic its $119.99 is\n  matched by about five series in coins, and it keeps being the cheaper option\n  for everything above that.\n</p>\n\n<Callout kind=\"info\" title=\"Why neither of these annual passes is cheap\">\n$119.99 for a year of unlimited viewing is about $0.33 a day. Most streaming\nservices cost more than that, so DramaBox is not expensive against Netflix\nstandards. It is expensive against <em>finishing one series</em> — which is the\ncomparison that actually matters here, and the one we make in\n<a href=\"/guides/dramabox-subscription-cost\">our DramaBox price breakdown</a>.\n</Callout>\n\n<h2 id=\"free-tier\">The free tier: where GoodShort wins</h2>\n\n<p>\n  Before you pay anything, the two apps behave differently in ways worth\n  knowing:\n</p>\n\n<table class=\"data-table\">\n  <thead>\n    <tr><th>Free route</th><th>DramaBox</th><th>GoodShort</th><th>Better</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>Free episodes per series</td><td>11 (43-episode title)</td><td>7 (50-episode title)</td><td><strong>DramaBox</strong></td></tr>\n    <tr><td>Ad unlocks per day</td><td>8</td><td>5</td><td><strong>DramaBox</strong></td></tr>\n    <tr><td>Check-in coins across 7 days</td><td>165</td><td><strong>320</strong></td><td><strong>GoodShort</strong></td></tr>\n    <tr><td>Video tasks per day</td><td>15 × 20 coins = 300</td><td>Third-party offerwall only</td><td><strong>DramaBox</strong></td></tr>\n    <tr><td>Reliability of ad unlocks</td><td>Stable</td><td><strong>Fails sometimes</strong></td><td><strong>DramaBox</strong></td></tr>\n  </tbody>\n</table>\n\n<p>\n  GoodShort takes the one category it wins: <strong>check-ins pay 320 coins a\n  week against DramaBox's 165</strong> — nearly double, rising to 90 on day\n  seven. If you are the sort of person who opens the app every day anyway, that\n  difference is worth real money.\n</p>\n\n<p>\n  Two GoodShort caveats that cut the other way. Its ad unlocks cap at\n  <strong>5 a day, half of DramaBox's 8</strong>, and we captured an\n  <strong>\"Ad unlock failed. Please try again later\"</strong> message — so the\n  free allowance there is both smaller and less reliable.\n</p>\n\n<Callout kind=\"alert\" title=\"GoodShort's free coins come from a third party\">\nIts reward system pays through offerwalls — the kind that ask you to install\nother apps or complete sponsored offers. That is a materially different thing\nfrom a first-party daily check-in, and it is why we would not count those coins\nas reliable income the way we count DramaBox's.\n</Callout>\n\n<Screenshot\n  src=\"/screenshots/dramabox-ad-unlock.webp\"\n  alt=\"DramaBox episode paywall offering three routes at once: unlock with 50 coins, watch an ad to unlock free, or join membership\"\n  caption=\"The three-way paywall on DramaBox, 9 October 2026: 50 coins, an advert, or a subscription. GoodShort offers the same three routes but with a daily ad cap of five rather than eight\"\n/>\n\n<h2 id=\"one-series\">Finishing one series, worked through</h2>\n\n<p>\n  The most common case is a single series, and the two apps separate clearly\n  there. Using the series we tested on each:\n</p>\n\n<h3>DramaBox — a 43-episode series, 11 free</h3>\n\n<p>\n  That leaves <strong>32 episodes × 50 coins = 1,600 coins</strong>. The\n  $12.99 pack covers that exactly. Total <strong>$12.99</strong>.\n</p>\n\n<h3>GoodShort — a 50-episode series, 7 free</h3>\n\n<p>\n  That leaves <strong>43 episodes × 50 coins = 2,150 coins</strong>. The\n  $19.99 pack holds 2,200, so it just covers it. Total <strong>$19.99</strong>.\n</p>\n\n<table class=\"data-table\">\n  <thead>\n    <tr><th>Route</th><th>DramaBox</th><th>GoodShort</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>Episodes to unlock</td><td>32</td><td>43</td></tr>\n    <tr><td>Coins needed</td><td>1,600</td><td>2,150</td></tr>\n    <tr><td>Pack that covers it</td><td>$12.99</td><td>$19.99</td></tr>\n    <tr><td>Subscription alternative</td><td><strong>$9.99 first week</strong></td><td>$19.99/week</td></tr>\n  </tbody>\n</table>\n\n<p>\n  Finishing one series with coins costs <strong>$12.99 on DramaBox and $19.99 on\n  GoodShort</strong> — a $7 gap. Note that GoodShort needs more unlocked\n  episodes (43 against 32) purely because its free block is shorter, not\n  because the series is longer in the same proportion.\n</p>\n\n<h2 id=\"missing-price\">The price we could not verify</h2>\n\n<p>\n  We would rather flag this than paper over it. GoodShort's promotional popup\n  reads:\n</p>\n\n<p>\n  <em>\"US$ 19.99/w for 3 weeks, then /w\"</em>\n</p>\n\n<p>\n  The renewal figure after \"then\" is <strong>blank</strong>. We photographed the\n  screen and could not resolve it, and GoodShort's listing does not publish it\n  either.\n</p>\n\n<Callout kind=\"alert\" title=\"Assume you pay the promo price\">\nBecause we could not confirm a lower renewal, every GoodShort figure on this\npage uses <strong>$19.99 as the ongoing weekly price</strong> — the worst case\nfor GoodShort. If its renewal turns out to be lower, DramaBox's advantage is\nsmaller than shown, never larger.\n</Callout>\n\n<p>\n  The same app also shows <strong>inconsistent discount claims</strong> — the\n  home screen advertises \"50% OFF\" while the in-show popup says \"51% OFF\" for the\n  same period. Neither percentage is verifiable because the struck-through base\n  price is not displayed. Treat both as marketing rather than arithmetic.\n</p>\n\n<h2 id=\"which-one\">Which one to pick</h2>\n\n<p>\n  In order of how likely each factor is to decide it for you:\n</p>\n\n<ol class=\"steps\">\n  <li>\n    <strong>You will subscribe — pick DramaBox.</strong> $30 cheaper a year,\n    $7 cheaper a week. There is no version of this where GoodShort wins on\n    price.\n  </li>\n  <li>\n    <strong>You will buy coins to finish one series — pick DramaBox.</strong>\n    $12.99 against $19.99, and a shorter paywall to get past.\n  </li>\n  <li>\n    <strong>You open the app daily and like collecting — consider GoodShort.</strong>\n    Its 320-coin check-in week is the one genuine advantage it holds. Pair it\n    with the knowledge that its ad unlocks are capped at five and sometimes fail.\n  </li>\n  <li>\n    <strong>You want the biggest free catalogue — pick DramaBox.</strong>\n    16,000+ claimed titles against GoodShort's smaller library, and we have not\n    measured GoodShort's catalogue depth directly.\n  </li>\n</ol>\n\n<AffiliateCTA\n  appName=\"DramaBox\"\n  href=\"https://r.reelsgo.tv/uR3A7JBLdipd\"\n  sub=\"Free to download · $9.99 a week for three weeks against GoodShort's $19.99\"\n  buttonLabel=\"Open DramaBox\"\n/>\n\n<p>\n  If you are weighing DramaBox against ReelShort instead, that is a different\n  comparison — different coin price, different structure, and a much wider gap.\n  See <a href=\"/guides/reelshort-vs-dramabox\">ReelShort vs DramaBox</a>.\n</p>\n\n<h2 id=\"limitations\">What this comparison cannot tell you</h2>\n\n<ul>\n  <li>\n    <strong>GoodShort's renewal price is unconfirmed.</strong> Everything here\n    uses the promotional $19.99 as the ongoing figure. If the real renewal is\n    lower, the gap narrows.\n  </li>\n  <li>\n    <strong>One series per app.</strong> Our free-episode counts come from a\n    43-episode title on DramaBox and a 50-episode title on GoodShort. Neither\n    app publishes its free block and both move by title, so treat these as\n    samples.\n  </li>\n  <li>\n    <strong>Android only, October 2026.</strong> Both were tested through Google\n    Play on an emulator with real billing. We have not verified iOS pricing.\n  </li>\n  <li>\n    <strong>Catalogue depth is not measured.</strong> DramaBox claims 16,000+\n    titles; we did not count GoodShort's.\n  </li>\n  <li>\n    <strong>Content quality is subjective and mostly untested.</strong> We are a\n    price comparison. Where the apps differ on dubbing quality or originals, we\n    have not done the testing to tell you which is better.\n  </li>\n</ul>\n\n<h2 id=\"bottom-line\">Bottom line</h2>\n\n<p>\n  <strong>Per episode, they are the same app.</strong> Fifty coins each, $0.50\n  on the smallest pack, and within four cents of each other at the best rate.\n  Nothing here justifies switching for the coins.\n</p>\n\n<p>\n  <strong>Per subscription, DramaBox wins clearly.</strong> $119.99 against\n  $149.99 a year — a $30 gap — and $12.99 against $19.99 a week. Same unlimited\n  model, materially different price.\n</p>\n\n<p>\n  <strong>GoodShort's one real advantage is its check-in</strong>, at 320 coins\n  a week against DramaBox's 165. If you collect daily it is worth having. It is\n  offset by a shorter free block (7 episodes against 11) and ad unlocks that cap\n  at five and sometimes fail outright.\n</p>\n\n<p>\n  So: <strong>subscribing or finishing one series, take DramaBox</strong>.\n  Collecting daily streaks and nothing else, GoodShort is defensible. And check\n  the renewal price in-app before you commit to either — we could not confirm\n  GoodShort's, and neither can you from the app's own text.\n</p>","src/content/guides/dramabox-vs-goodshort.mdx","ec8fa5d5193e68b1"];

export { _astro_dataLayerContent as default };
